const r={tools:[{n:"常用维修工具",mf:"/",job:"技工",lg:"Y",ds:"常见的扳手、锤子、螺丝刀等等，可以用来维修各种日常的东西，包括无人机、车辆、家具等等。但义体和枪支往往需要特别的工具。你可以用这套工具进行升级或者常规维修，部分需要专门维修的产品则需要专门的工具。",ra:"N",pr:30,tier:"便宜",grp:"技工"},{n:"枪支维护保养套装",mf:"/",job:"技工/独狼",lg:"Y",ds:"基础的枪匠维护工具，包括了枪用毛刷、枪油、通条、防水布等常用工具。使用十分钟后可以临时将一把低可靠性的武器提升至中可靠性，射击10ROF或者两次全自动（包括机枪短点射）后失效。一次全自动射击算作5ROF。无法让中可靠性的武器提升至高可靠性",ra:"N",pr:50,tier:"便宜",grp:"技工"},{n:"义体备用零件包",mf:"/",job:"技工/技医",lg:"Y",ds:"可以修复义体的严重伤势，哪怕义体出现断肢的时候也可以进行修复，同时可以作为急救包给FBC（赛博格）进行急救。要接上断裂的义体，必须通过一次DV20的赛博技术检定，且只有一次机会。该物品是一次性的，且占用一个M级别的空间。",ra:"N",pr:20,tier:"便宜",grp:"技工"},{n:"辅助机械臂背包",mf:"泽塔科技",job:"技工/技医",lg:"Y",ds:"有些人不愿意给自己身上加那些乱七八糟的改造件，所以他们就会携带这款外接式的辅助机械臂背包。这个背包需要用神经链接相连，它提供了两个小型机械臂，可以握持额外的工具，最多用来抓住一升的水，不能使用武器，也不能帮助你手提盾牌。它可以在你的神经信号操作下进行一些简单但是精度不高的动作，用其进行维修或者急救检定时，你可以免费重骰一次，并在两骰之间取较高的数值。",ra:"SR",pr:400,tier:"平价",grp:"技工"},{n:"N级材料",mf:"/",job:"技工",lg:"Y",ds:"最廉价最常见的便宜合金、聚合物，还有那些垃圾场里找到的东西。能不在你手里解体都算谢天谢地了。",ra:"N",pr:1,tier:"便宜",grp:"技工"},{n:"R级材料",mf:"/",job:"技工",lg:"Y",ds:"一些常见的工业材料、合金和纤维。也包括了消费级的芯片和电路板。你可以从绝大部分地区的普通市场上搞到的东西。",ra:"R",pr:10,tier:"便宜",grp:"技工"},{n:"SR级材料",mf:"/",job:"技工",lg:"Y",ds:"昂贵的专业材料、高纯度合金和特种聚合物，还有高精度的芯片与算力强悍的处理器。许多都需要从工厂直接订货。",ra:"SR",pr:100,tier:"平价",grp:"技工"},{n:"SSR级材料",mf:"/",job:"技工",lg:"N",ds:"多半是公司机密级别的特种材料、昂贵的稀土合金和军用规格的芯片与电路板。哪怕在黑市都价格不菲。",ra:"SSR",pr:500,tier:"值钱",grp:"技工"},{n:"小型工坊工具",mf:"/",job:"技工",lg:"Y",ds:"几乎每家每户家里都会有的常见工具，锤子、卷尺、扳手、螺丝刀，再加上一张不会随便解体的桌子，你就能在上面肆意展现你的想象力了。允许制造、升级N级的物品（不包括载具）",ra:"N",pr:80,tier:"平价",grp:"技工"},{n:"中型工坊工具",mf:"/",job:"技工",lg:"Y",ds:"高级一点的家用工具库，各种不同标准的螺丝刀头和奇形怪状的扳手可以塞满一整个工具箱，连工作桌也是专业的。上面刻满了高精度的尺规和测量标准。你还可以用一台家用3D打印机自己打印一些稀缺的零部件。但都是脆弱的塑料和树脂做的。允许制造、升级N和R级的物品（不包括载具）",ra:"R",pr:1e3,tier:"高级",grp:"技工"},{n:"大型工坊工具",mf:"/",job:"技工",lg:"Y",ds:"几乎可以塞满一座车库的专业工具库，几乎市面上能想到的高级工具和零部件在你这里都能找得着。还有专用的工程机械臂替你起重、焊接。你可以在这里修一辆车，或者造一台车。只要你有足够的材料，弄一辆土造坦克也不是不行。允许升级N、R和SR级别的物品，可以升级装甲车、坦克和炮艇以外的载具，但你依然不能制造它们。",ra:"SR",pr:5e4,tier:"顶奢",grp:"技工"},{n:"高精度机床工坊",mf:"/",job:"技工",lg:"Y",ds:"可以算得上一家小型公司的高精度车间了。不仅有可编程的机械流水线，还有一整台占满整座房间的高精度3D打印机床，可以直接打印现在的前沿合金。而在它旁边的那台真空智能锻炉和纳米级数控机床可以让你自由发挥所有想象力，但维护和使用它们的价格，也需要你，或者拥有它们的企业动用一些想象力。允许升级、制造一切物品，但你制造载具需要的时间大大延长（N级载具一周，R级两周，SR级一个月，SSR级半年，装甲车、坦克和浮空车载具时间翻倍），且需要的材料翻倍。",ra:"SSR",pr:5e5,tier:"顶奢",grp:"技工"},{n:"便携式工坊",mf:"/",job:"技工",lg:"Y",ds:"一口工具箱大小的盒子，里面装满了小型化的各类工具，展开后即可作为一个小型工坊使用。",ra:"R",pr:125,tier:"平价",grp:"技工"},{n:"随身工程师",mf:"IEC",job:"技工",lg:"Y",ds:"一口行李箱大小的盒子，里面装满了小型化的各类工具，甚至包括一个小型3D打印机和数控机床，展开后即可作为一个中型工坊使用。",ra:"SR",pr:1500,tier:"高级",grp:"技工"},{n:"便携式精工机床",mf:"IEC",job:"技工",lg:"Y",ds:"一口大型行李箱大小的箱子，里面装了一整个便携的高精度数控打印机床，你可以在链接电脑并输入图纸和材料后，自主制造你想要的大部分日常用品，就是有些耗费材料。展开后可以作为一个大型工坊工具使用，但不能用来制造和升级载具。",ra:"SSR",pr:6e4,tier:"顶奢",grp:"技工"},{n:"战地急救包",mf:"/",job:"技医",lg:"Y",ds:"包含手术刀、注射器、绷带、酒精、麻醉剂、手术钳、夹板、止血绑带、缝线工具等手术用品，市面上有预组的套装，但你也可以自己配置一个。允许你在野外环境对人进行急救和手术。",ra:"N",pr:50,tier:"便宜",grp:"技医"},{n:"激光手术刀",mf:"泽塔科技",job:"技医",lg:"Y",ds:"大医院常用的高能激光手术刀，可以高效切割人体组织。但出于安全性考虑，在超过30cm的距离使用它就只会变成一杆激光笔。作为手术工具使用时，急救+2，战地急救+1，外科手术等级（技医）+1。也可以在近身战时作为一把轻型近战武器使用，其伤害为3D4，ROF2，穿甲等级轻反器材。",ra:"SR",pr:500,tier:"值钱",grp:"技医"},{n:"义体专用切组工具",mf:"IEC",job:"技医",lg:"Y",ds:"包含了义体专用扳手、特种钳、小型电锯和各家义体专用口径的螺丝刀头。是进行义体维护、更换所必要的切割和装卸工具，允许你在野外环境快速切割保存义体。在肢解义体时往往需要通过一个由RF决定的赛博技术/外科手术检定。",ra:"N",pr:105,tier:"平价",grp:"技医"},{n:"自动体外心脏去颤器 （AED）",mf:"/",job:"技医",lg:"Y",ds:"便携的自动体外心脏去颤器，在进行短暂充能后可以快速进行急救。适用于那些暂时失去心跳，但还有生命体征的目标。以此工具对正在经历死亡豁免的目标进行战地急救将获得+2的加值，且若掷骰出1，可重骰一次。它也可以作为一件需要双手共持的重型近战武器使用，造成ROF1，7D6中间威力穿甲等级的电击伤害。",ra:"R",pr:400,tier:"平价",grp:"技医"},{n:"封闭式医疗泡沫",mf:"沛卓石化",job:"技医",lg:"Y",ds:"可以用一个动作进行快速手术，使用后暂时（30分钟）治愈一个非断肢、器官失效、或位于头部的严重伤势，或者自动稳定重伤。",ra:"SR",pr:150,tier:"平价",grp:"技医"},{n:"义体越狱接入器",mf:"泽塔科技",job:"技医",lg:"N",ds:"多种用途的越狱工具，外观上看是一个类似掌上代理的平台，外部附带有多种义体的通用检修接口。可以让义体解除限制，临时超频，或者让那些经过了认证和定位的义体失去上述功能。实现这些功能需要通过一个由RF决定的赛博技术检定，并和RF讨论某种效果是否可行。（例如临时使某种技能+1或+2，但同时要承受大失败概率增加、持续承受伤害等可能的副作用）有诊所或者医院执照的技医可以通过合法渠道购入，而黑市购入往往需要花费双倍的价格。",ra:"R",pr:300,tier:"平价",grp:"技医"},{n:"戒瘾神经重塑包",mf:"沛卓石化",job:"技医",lg:"Y",ds:"一个包含了脑脊探针、神经脉冲电信号发生器、开颅手术套组、透析装置、仿生学骨胶等一系列瘆人工具的旅行包，用以帮助瘾君子戒除某种药物上瘾，或是对赛博精神病进行短效的，饮鸠止渴般的抑制。出于显而易见的原因，只有受过培训的专业医师才有资格在正规市场购入这里面的大部分工具。在治疗药物造成的副作用时，使用者将可以用自己的战地急救+外科手术等级，用以对抗该药物的副作用DV。进行一次手术时间需要2小时，若成功即可移除该药物造成的副作用，但同时也会移除正在生效的正面作用。使用者也可以用其对抗赛博精神病的症状，使患者在24小时内将人性锁定为30，但持续时间内除共情外所有属性额外-1。技医无法对自己进行这种手术。 PS:如果你打算用这玩意进行审讯，那根据你用这些工具进行RP的力度RF可以酌情提供+2~+4的加值。",ra:"SR",pr:800,tier:"值钱",grp:"技医"},{n:"气化药物配置工具",mf:"IEC",job:"技医",lg:"Y",ds:"这套工具包含了简易的离心机、试管、反应釜、真空泵、整合式分离与纯化设备等一系列化学制药工具，许多都是用民间有类似功能的仪器代替的。高科技的实验仪器往往要比这套工具贵上十倍（上述实验室环境可以使制药专精+3）。这些工具大约占据一个工作桌大小。不允许随身携带，但可以放在车辆的后备箱或者货舱里。它允许使用者花费一小时的时间，用一瓶毒药或是一瓶镇定剂作为原材料，以一个DV14的科学检定和30eb的原材料费将其合成为一颗烟雾手雷。这种手雷爆开后会制造一个6m半径的不透明烟雾，持续6回合。在烟雾范围内开始回合的，所有不戴防毒面具的目标都要进行一次药物抵抗/折磨检定，失败将会承受药物的效果。但以此方式散发的药物持续时间减半。",ra:"SR",pr:800,tier:"值钱",grp:"技医"},{n:"快速制药工具包",mf:"沛卓石化",job:"技医",lg:"Y",ds:"一个精巧的小包，里面装着迷你的化学工具组合。可以在野外环境花费1分钟的时间迅速配置药剂，里面最多装纳5种不同药剂的原材料，但你最多可以用这些原材料配置出三瓶不同的药剂（如果配置的都是同一种药剂，则最多可以配置出四瓶）。药剂用尽后需要你本人进行补充。配方价格参考技医制药专精的说明。",ra:"R",pr:150,tier:"平价",grp:"技医"},{n:"气动注射枪",mf:"沛卓石化",job:"技医",lg:"Y",ds:"相当于一把ROF1 中可靠性，精度2，单发装填的中型手枪。射程只有25m。可以通过气动原理发射注射针管，需要瞄准目标身上的无甲部位，无法穿透任何护甲。每次只能装填一管可以进行注射的药剂。",ra:"R",pr:200,tier:"平价",grp:"技医"},{n:"高手玩家电竞超梦椅",mf:"泽塔科技",job:"网行",lg:"Y",ds:"那些乳臭未干的小屁孩们要么坐在上面打游戏，要么坐在上面打飞机。但也有些特别的聪明小孩会用那额外的处理芯片来潜入暗网。算力+2，潜入暗网的交互界面检定+1",ra:"R",pr:400,tier:"平价",grp:"网行者"},{n:"南极风 黑客冷却椅",mf:"微科",job:"网行",lg:"Y",ds:"专门为网络安全专家准备的深潜用外置冷却装置，通过直连神经链接的方式对大脑进行冷却。每回合算力冷却+1，潜入暗网的交互界面检定+2",ra:"SR",pr:900,tier:"值钱",grp:"网行者"},{n:"法老 棺式网行床",mf:"渡鸦微控",job:"网行",lg:"Y",ds:"全覆盖的棺式网行床，有一个相当舒适的卧式空间，既可以放松肌肉，也可以在潜入的过程中对身体进行按摩。还内置了先进的分布式处理器和脑部冷却系统，是每个企业网行者的标配。渡鸦微控也有针对个别企业的高端定制款式，但那价格就不是很美丽了，甚至一台就可以达到上万eb。每回合算力冷却+2，算力+2，网行动作+1，潜入暗网的交互界面检定+3",ra:"SSR",pr:3e3,tier:"昂贵",grp:"网行者"},{n:"维护者 手持式碟板",mf:"微科",job:"网行",lg:"Y",ds:"同赛博碟板，但是用该碟板入侵网络建筑会使算力-1，该碟板视作拥有20hp的网行个体。遭受直接伤害时，只会伤害到碟板HP而不会伤害网行本人。维修碟板需要花费100eb。",ra:"R",pr:500,tier:"值钱",grp:"网行者"},{n:"星界™ 便携电脑",mf:"EBM",job:"网行",lg:"Y",ds:"网行动作+1，适合极客的高端便携电脑，拥有强大的算力性能，可以作为掌上代理和电脑使用，不能作为赛博碟板或者电子战平台使用，但可以在链接义体的时候作为副碟板使用。但必须持用在单手上。拥有两个魔偶插槽和三个程序插槽。",ra:"SR",pr:800,tier:"值钱",grp:"网行者"},{n:"银河XLC-700 手提碟板",mf:"渡鸦微控",job:"网行",lg:"Y",ds:"算力+3，网行动作+1，笔记本大小的手提式碟板，可以安装正常电脑的操作系统，也可以在链接神经链接的时候作为主或副碟板使用。它相比植入式的碟板要更笨重，却有更好的处理器，可以分担黑客的压力。该碟板视作拥有25hp的网行个体。遭受直接伤害时，只会伤害到碟板HP而不会伤害网行本人。它不能作为电子战平台使用，拥有3个魔偶插槽和6个程序插槽",ra:"SR",pr:1e3,tier:"高级",grp:"网行者"},{n:"伯利恒™ 手提碟板",mf:"EBM",job:"网行",lg:"Y",ds:"算力+5，交互界面检定+1，使用者遭受来自黑客或者程序的直接伤害减少3。作为网行者中有口皆碑的“极客碟板”，大小如同一个公文包。伯利恒系列虽然昂贵，但绝对是市面上最好的手提碟板。它既可以做电脑也可以做黑客碟板使用，相比植入式的碟板笨重很多，但也具备更好的智能处理器。它拥有5个魔偶插槽和10个程序插槽，可以作为电子战平台使用，但无论作为那种方法来用，使用时必须连上使用者的神经链接。拥有50m的射程。",ra:"SSR",pr:5e3,tier:"极贵",grp:"网行者"},{n:"远程链接天线",mf:"渡鸦微控",job:"网行",lg:"Y",ds:"一个附带微型天线的接口，可以让网行者远程入侵网络建筑。只要接口可以链接当地网络或者局域网，黑客就能通过局域网的接口链接它。如果黑客无法接入本地局域网或者互联网与其链接，则该天线的最大范围是100m。",ra:"N",pr:25,tier:"便宜",grp:"网行者"},{n:"快捷存储芯片",mf:"微科",job:"网行",lg:"Y",ds:"可以用来存储一个程序或者一个魔偶，或者大概一个TB的文件。可以快速插入到你的电子战天线和赛博碟板里，但每次只能同时插入一个，插入或者更换一枚存储芯片需要消耗一个动作。你最好别把平时存的黄片和你的魔偶搞混了。",ra:"N",pr:20,tier:"便宜",grp:"网行者"},{n:"一次性入侵装置",mf:"/",job:"网行",lg:"N",ds:"那些老网行们通常叫这玩意“小花招”，可以让你直接破解一个最大DV为你的交互界面等级两倍的装置，比如密码门、无人机、加密过的掌上代理，或者在入侵网络建筑的某一层时以一个网络动作直接发现一个安全漏洞。（你必须已知该层的所有节点）但在注入一次后就会失效。",ra:"R",pr:50,tier:"便宜",grp:"网行者"},{n:"电子信号侦测装置",mf:"EBM",job:"网行/执法",lg:"N",ds:"一台大小如同平板电脑的装置，可以发射WIFI信号穿墙侦测一切电子设备，并以信号源和距离的方式显示在屏幕上。可联网的设备会被高亮标注，也可以侦测义体，但只有裸露的义体（赛博臂、腿和神经链接）会被侦测到。有效作用范围为50m",ra:"SR",pr:500,tier:"值钱",grp:"网行者"},{n:"定制模块包",mf:"/",job:"独狼",lg:"Y",ds:"每一个独狼都会为自己专门设计一套最舒适的出勤方案，这不仅包括了那些精校微调的各式武器，还包括了对于随身衣物的定制方案。该方案可以让你的一件随身衣物多出一个M级的口袋，一件衣物只能安装两次，不能安装在仅保护头部的衣物上。",ra:"N",pr:10,tier:"便宜",grp:"独狼"},{n:"定制挂架",mf:"/",job:"独狼",lg:"Y",ds:"独狼出勤执行任务的环境有时候往往需要一些重火力，但又不好明晃晃地带在街头，拆分装箱又很耗时间，于是有些独狼会在自己宽松的随身衣物上设计一个特殊的武器挂架，用来收纳一把全尺寸的突击步枪。该定制方案可以让你的一件夹克、大衣、风衣多出一个隐藏突击步枪/重型近战武器及以下装备的空间，一件衣物只能安装一次，不能安装在仅保护头部的衣物上。",ra:"R",pr:150,tier:"平价",grp:"独狼"},{n:"DIY弹药带",mf:"/",job:"独狼",lg:"N",ds:"为你的衣物上额外增加一条定制的武装带，看起来就像是动作电影里的硬汉主角。但路上的条子大概不会很喜欢看见你这副拽拽的样子。这条弹药带相当于一个m级别的口袋，但只能容纳弹药。你每次战斗第一次装填弹药将会从上面快速取来弹药，并将不会花费任何动作。",ra:"R",pr:100,tier:"平价",grp:"独狼"},{n:"护心镜",mf:"/",job:"独狼",lg:"Y",ds:"有些独狼确实会在自己的关键部位放一块“幸运道具”，以在关键时刻帮自己挡下一枪。但这些东西怎么放，放哪儿，用什么东西放，都是十分有讲究的。你的躯干部位即将承受一次严重伤势时，你免受该伤势的效果。如若一次攻击即将将你致死但破甲后伤害小于你的幸运（最小1），则你免受这一次伤害。你一次只能装备一次该物，两种效果成功发动其一即损坏。且损坏后只能在战后弥补。",ra:"SR",pr:200,tier:"平价",grp:"独狼"},{n:"枪匠精调工具",mf:"/",job:"独狼",lg:"Y",ds:"任何一个经验丰富的独狼都会有一把或者多把自己的专属枪械，尽管这些专属枪械都是市面上的消费产品，但独狼们会根据自己的需要精校、调整爱枪的零部件，比如加厚枪托、削薄击锤、调整扳机力度、或是对某些区域进行重量的调整。事实上，根据每一位佣兵和每一把武器的需求，这一套工具所包含的东西会有所区别。每个独狼都可以指定一把枪械并购买专用的调校工具，使该枪械无论基础可靠性，每次出目1都可以重骰一次。但重骰后必须接受重骰的结果。",ra:"SR",pr:500,tier:"值钱",grp:"独狼"},{n:"刀匠维护工具",mf:"金田一",job:"独狼",lg:"Y",ds:"从封建时代开始，无论是西方的骑士还是东方的武士，他们一天中的许多时光都会用来保养自己的刀剑。到了当代，人们有了单分子剑和热能武士刀，也有了维护、保养这些武器专用的工具和替换零件。一个更舒适的握把可以在决斗中掌握一个武者的生死，一道更锋利的刀刃可以在决定性的一击中拼断对方的兵刃。每个独狼都可以指定一把近战武器并购买专用的维护工具，使该武器在大成功时可以直接造成一个严重伤势，并击落对方手上的武器。（除非武器有无法脱手的能力）",ra:"SR",pr:300,tier:"平价",grp:"独狼"},{n:"扩音麦克风",mf:"/",job:"滚青",lg:"Y",ds:"常见的扩音麦克风，可以将乐谱和你职业能力的影响范围增加10m",ra:"N",pr:30,tier:"便宜",grp:"摇滚青年"},{n:"二手乐器",mf:"/",job:"滚青",lg:"Y",ds:"这些二手乐器跟了他们上一任主人好几年，上面满是油污和时代的味道，说不定比你的年纪还大。但还没到报废的程度，能堪一用。使用其进行演奏时，你的相关表演-1.",ra:"N",pr:60,tier:"平价",grp:"摇滚青年"},{n:"传统乐器",mf:"/",job:"滚青",lg:"Y",ds:"旧时代常见的那些手工乐器，入门级的价位还算廉价，外观和性能也足够文艺青年拎着去泡妞了，但如果你要的是那些大师级别的定制款，那可能就得好好出一些血了。（大师乐器相关演奏+2，酷+1，稀有度SSR，价格5000eb起步）",ra:"N",pr:150,tier:"平价",grp:"摇滚青年"},{n:"辅助指弹器",mf:"微科",job:"滚青",lg:"Y",ds:"附加在乐器上的可编程指弹器，可以让你只用一只手演奏需要两只手演奏的乐器。但你不能完全依赖它来演奏乐谱，在演奏乐谱时，你必须至少有一只手在控制乐器。",ra:"R",pr:300,tier:"平价",grp:"摇滚青年"},{n:"电子节拍器",mf:"泽塔科技",job:"滚青",lg:"Y",ds:"打击乐器 管类乐器 一种便携的电子鼓，你依然需要自己去演奏，但演奏的方式变成了类似指弹的方式，除了打击乐之外，你还可以通过上面的吹管来造成管乐的效果。那些正经的鼓手对此不屑一顾，称只有圈外的小屁孩才会玩这种东西。",ra:"R",pr:500,tier:"值钱",grp:"摇滚青年"},{n:"雷霆工业™ 智能电吉他",mf:"泽塔科技",job:"滚青",lg:"Y",ds:"弦类乐器 造型酷炫，附带了霓虹灯条和全息特效器的电吉他，附有一个行为分析芯片，辅助乐手弹奏，哪怕只用一只手，也能弹出绝佳的SOLO！",ra:"R",pr:500,tier:"值钱",grp:"摇滚青年"},{n:"高地人™ 史诗电子管",mf:"微科",job:"滚青",lg:"Y",ds:"管类乐器 键盘乐器 模仿苏格兰风笛样式做成的电子音乐管，它有一个特别的携行具可以挂在身上，同时通过编程好的方式来进行吹奏，它还附带了琴键，可以吹奏的同时用一只手进行弹奏。2045年一位前卫爵士大师曾经用它和其他乐器一个人完成了一个乐队的工作量，立刻在行业内打响了它的知名度。",ra:"SR",pr:600,tier:"值钱",grp:"摇滚青年"},{n:"全息核心™电子琴",mf:"EBM",job:"滚青",lg:"Y",ds:"键盘乐器 电子乐器 你见过最近的乐队小青年都在live上玩什么吗？他们就带一个镀铬的金属块过去，然后手在上面一滑，琴键、合成器、DJ台，全都投影到半空中了。用那东西演奏就和跳舞差不多，整个现场都嗨爆了！这个乐器可以用挂带挂在身上，同时作为键盘乐器和电子乐器使用。",ra:"SR",pr:800,tier:"值钱",grp:"摇滚青年"},{n:"快速易容套装",mf:"/",job:"媒体人",lg:"Y",ds:"一个精巧的化妆盒和便于收纳的备用装饰物，用于伪装的表演获得一次重骰机会。",ra:"R",pr:150,tier:"平价",grp:"媒体人"},{n:"“替身”",mf:"渡鸦微控",job:"媒体/网行",lg:"Y",ds:"这东西是渡鸦微控为黑客准备的一种线上替身，但后来不知道为什么它的主要客户变成了各个自媒体平台上的媒体人。它可以用神经链接直连，来反馈使用者在网络空间的所作所为。除了作为一个可以兼容world.inc和精灵战线等多种网游的自定义形象以外，最为核心的功能是其自带反入侵和追踪的伪造IP跳跃功能，可以让使用者无法被追踪，以让那些知名主播和互联网内容生产者逃离讨厌的追随者。",ra:"R",pr:300,tier:"平价",grp:"媒体人"},{n:"超梦反编译破解软件",mf:"WNS",job:"媒体/执法",lg:"N",ds:"专业媒体工作者通常会使用的一种反编译软件，在警方也有专门的部门使用。该软件是一种类似蠕虫病毒的AI分析软件，允许使用者对超梦片段进行“越狱”，以获取额外的感官信息（对超梦片段的信息进行重骰），更为有趣的是，它还可以对超梦片段的主角进行生理分析，主角体内的生理机能、植入物（无法具体到型号，只能具体到安装部位和大概特征）和负重分布。通常的超梦片里只能通过主角的视角去感知世界，有了它，你就能用来感知主角本身。",ra:"SR",pr:450,tier:"平价",grp:"媒体人"},{n:"“独角兽”智能助理",mf:"微科",job:"媒体人",lg:"Y",ds:"“梦魇”助理的简化版本，民间的自媒体创作者基本上人手一个。即便它的创作能力限制了许多，但它也依然是市面上最好的视频编辑软件之一。它操作简单、容易上手，即便不购买高级版本也能实现许多复杂且炫酷的操作。基本上所有视听相关的院校都有培训学生们使用它的方式。",ra:"N",pr:50,tier:"便宜",grp:"媒体人"},{n:"“梦魇”智能助理",mf:"微科",job:"媒体人",lg:"Y",ds:"一个高性能的智能编辑AI，是现在主流媒体公司最喜欢的内容编辑助理。简单来说，你只需要通过神经链接将你的想法告诉它，它就能根据要求生成任何你想要的画面。原本在传统编辑软件上需要做一周甚至一个月的片子，它一天就能做好。即便是超梦，他也能朝里面添加特效。无论是新闻工作者还是生产内容的视频号，他们都爱死这个AI了。但可惜的是，这玩意的价格简直贵到离谱，它一个月就要500eb，还需要认证过的媒体创作者（即平台粉丝达到10w以上）才能获取它的使用权限。对于那些大工作室和专业媒体工作者来说，EBM还有为他们个人定制的版本，那价格就更加夸张了，传说一些给他们个人定制的专用版本，一个月就要2500eb。该智能助理可以让需要该物的传媒大亨能力的准备时间掷骰取最小值。",ra:"SSR",pr:500,tier:"值钱",grp:"媒体人"},{n:"定向劫持天线",mf:"/",job:"媒体人",lg:"N",ds:"这东西基本上就是一个便携的卫星锅，如果你的预算足够，也能购买一个更大更给力的车载款式（距离+700m），它可以通过定向投射电波的方式劫持信号，将你想要的内容投送到目标区域。是最暴力、最高效的信号劫持方式之一。但它的弊端在于，需要使用者手持天线来到目标区域投射信号，且最远距离只有300m，在部分安保比较严密的地区甚至需要在50m以内进行劫持。",ra:"SR",pr:300,tier:"平价",grp:"媒体人"},{n:"卫星直播摄影机",mf:"N54",job:"媒体人",lg:"Y",ds:"通过和轨道航空/欧空局的卫星合作，可以在任何非地下环境不断网的直播摄影机。即便身处建筑和地下深处，只要你头顶上不是50m厚的实心土壤/岩石，你也可以照样保持直播通畅。",ra:"SR",pr:1e3,tier:"高级",grp:"媒体人"},{n:"战地记者挂带",mf:"DMS",job:"媒体人",lg:"N",ds:"DMS在战区进行深度采访时为战地记者专门设计的武装挂带，这种挂带有多个快拆挂扣和挂钩，并有多处松紧带来调整人机工效。除了携带摄影设备以外，该挂带还可以携带防身武器和弹药。该挂带一共有一个可以隐藏任意手枪的枪套、一个可以存放任意冲锋枪的枪套或者一个L级的腰包，还有两个M级的口袋和一个L级的腰包。",ra:"SR",pr:200,tier:"平价",grp:"媒体人"},{n:"雅典娜人工智能助手",mf:"EBM",job:"执法者",lg:"N",ds:"由EBM开发，能力享誉全球的军/警用人工智能，拥有市面上最强大的检索、归纳能力。仅用数秒就可以分析上千万字的内容，并用相对简洁的方式归纳、提取重点。它的民用版本叫“阿波罗”，在效率上差了雅典娜至少三倍，很多雅典娜的专属功能也没有开放。雅典娜的客户端需要用一块专门的加密芯片承载，可以被部署在私人电脑或者掌上代理上，必须使用每个注册客户专属的激活解码器才可以使用。它的触须可以在眨眼间伸遍表层网络的每一个角落，网络监察就利用过它抓捕了不少流窜AI。于是它在链接警用数据库后也便成为了最好的心理分析专家。但也出于它本身的高便利性，只有高级警督和各行各业的高级情报人员才有资格获取它的使用权限。EBM也会专门核查每个客户是否遵循了用户协议中的使用规范，以免其落入了错误的人手里。",ra:"SSR",pr:5e3,tier:"极贵",grp:"执法者"},{n:"警用门缝摄像头",mf:"渡鸦微控",job:"执法者",lg:"N",ds:"一种便携的连线针孔摄像头，可以透过门缝观察门后的画面。能将画面投射到义眼或者掌上代理中。只有执法者才有渠道购入。",ra:"R",pr:100,tier:"平价",grp:"执法者"},{n:"催泪喷雾",mf:"/",job:"执法者",lg:"Y",ds:"喷射辣椒素的催泪喷雾，类似于一把只有5m射程的中型手枪，但它不造成伤害也无法加装改件，被其命中的目标必须经过一个DV16的折磨/抵抗药物检定，否则陷入一回合的目盲。",ra:"N",pr:20,tier:"便宜",grp:"执法者"},{n:"警用黑客设备",mf:"EBM",job:"执法者",lg:"Y",ds:"警用的黑客碟板，只有文职警察才有受过相关培训。使其可以像等级一半的网行者一样破译电子锁。它还可以用来感应30m内的电子设备，并显示距离和强度。如果使用者有义眼或者智能目镜，同样可以投射到上面去。",ra:"SR",pr:150,tier:"平价",grp:"执法者"},{n:"便携式警用穿墙雷达",mf:"EBM",job:"执法者",lg:"N",ds:"通过穿墙电磁波的反馈探测人形轮廓，有效作用范围30m，且必须占用单手才能使用。只有执法者有合法渠道购入，黑市上的价格是常规的三倍。",ra:"SR",pr:400,tier:"平价",grp:"执法者"},{n:"便携测谎仪",mf:"EBM",job:"执法者",lg:"N",ds:"智能分析AI，通过监测目标的表情、动作细节、声音和脉搏来进行测谎。察言观色/推理+2，必须和使用者的神经链接相连。只有执法者有合法渠道购入，黑市上的价格是常规的两倍。",ra:"SR",pr:300,tier:"平价",grp:"执法者"},{n:"特勤武装腰带",mf:"塔伦警用",job:"执法者",lg:"N",ds:"警用的专业武装腰带，只有外勤的时候允许佩戴。上面有一个可以放置任何类型手枪的枪套，三个放置投掷物的位置，两个s级别的口袋和两个m级别的口袋。",ra:"N",pr:100,tier:"平价",grp:"执法者"},{n:"巡警枪带",mf:"/",job:"执法者",lg:"N",ds:"巡警腰上常见的基础武装带，有一个可以放置类型手枪的枪套，一个放置投掷物或者胡椒喷雾的位置，两个s级别的口袋。",ra:"N",pr:20,tier:"便宜",grp:"执法者"},{n:"城市通勤会员卡",mf:"/",job:"公司人",lg:"Y",ds:"公司和城市交通签订协议，发放给员工的公共交通会员卡。使用其可以免费搭乘公共交通工具通勤。在使用出租车时，也可以享受50%的折扣。若你的公司本身有通勤交通工具，你也可以凭借这个证件使用它们。",ra:"N",pr:50,tier:"便宜",grp:"公司人"},{n:"特殊豁免证",mf:"/",job:"公司人",lg:"Y",ds:"需要备案办理的公司豁免证书，使你可以接触到一些正常来说无法购入或是携带的违禁物品，如枪械、战斗义体、武装无人机等等。但是位于部分地区时该豁免权依然无效（由RF决定）。你可以凭借该豁免证书购买公司内部的SSR稀有度物品。",ra:"R",pr:100,tier:"平价",grp:"公司人"},{n:"医疗保险",mf:"/",job:"公司人",lg:"Y",ds:"由公司办理的昂贵医疗保险，使你在诊所或医院医治外伤、中毒、疾病时享受80%的折扣。若你的肢体受损，在出示保险证书后诊所会为你免费安装替换的医疗义肢。价格为月费。",ra:"SR",pr:200,tier:"平价",grp:"公司人"},{n:"红外窃听仪",mf:"/",job:"公司/执法",lg:"Y",ds:"一种通过发射红外激光感应物体振动来还原对话信息的工具，事实上，他的原理和刻录黑胶唱片差不多，只是更加高科技。它一般装配在云台上或者使用脚架支撑，不可以在不稳定的平台上使用（例如在没有稳定云台的帮助下手持）。使用者可以发射激光窃听最远500m外的通话，且可以穿透如玻璃的透明表面。",ra:"SR",pr:300,tier:"平价",grp:"公司人"},{n:"贴身安保服务",mf:"/",job:"公司人",lg:"Y",ds:"你雇佣一位贴身保镖为你服务，该保镖在日常生活中和你形影不离，在战斗中受你控制。他会尽可能保证你的安全，但他只能保证八小时的安全时间，除非你再雇一位。保镖携带一把SR级及以下的任意手枪或者普通冲锋枪，平时隐藏在衣服里。内穿一件12SP，EV1的装甲夹克，或一件10sp的防弹西装。他不会将自己自带的武装交给雇主，但雇主可以将自己购置的装备交给他使用。在战斗中，若你位于保镖身侧2m以内，他会为你挡下来袭的子弹。保镖平均属性为6，在战斗中的技能系数是12，加价2000雇佣高级保镖，平均属性升级至8，技能系数升级至15，并让其可以使用SSR级别的装备。保镖的价格按周计算。（PS：该服务尽量限制只能买一次）",ra:"SR",pr:1e3,tier:"高级",grp:"公司人"},{n:"创伤小队白银会员",mf:"创伤小队",job:"通用",lg:"Y",ds:"为每个公司员工或是普通人准备的基础服务，一个生命侦测芯片会被免费植入在你的身体里，监控你的身体活动，但只有当你受到重伤的时候才会被触发。在附近巡逻的创伤小组会在2d6轮次内抵达你的位置（战力数值如战争手册创伤小组突击队员），抵达现场后，他们会尽量保证你的安全，为你稳定重伤或者致命伤，并转移至最近的医院。但不会治疗你的严重伤势或是恢复生命值，你医治伤口和更换义肢需要自己支付额外的费用。费用为月费，若你从职业能力里获得了这一项会员，则不需要支付费用。",ra:"R",pr:500,tier:"值钱",grp:"公司人"},{n:"创伤小队黄金会员",mf:"创伤小队",job:"公司人",lg:"Y",ds:"为公司中层管理人士准备的高级服务，一个生命侦测芯片会被免费植入在你的身体里，监控你的身体活动。只要你受伤就可以主动呼叫，或是在你陷入重伤时自动触发。在附近巡逻的创伤小组会在1d8轮次内抵达你的位置，抵达现场后，他们会尽量保证你的安全，为你稳定重伤和致命伤，治疗你的严重伤势，并转移至最近的医院。若你需要更换义肢，则需要自己支付额外的费用。费用为月费，若你从职业能力里获得了这一项会员，则不需要支付费用。",ra:"SR",pr:1e3,tier:"高级",grp:"公司人"},{n:"创伤小队白金会员",mf:"创伤小队",job:"公司人",lg:"Y",ds:"为公司高层管理人士准备的顶级服务，一个生命侦测芯片会被免费植入在你的身体里，监控你的身体活动。只要你受伤就可以主动呼叫，或是在你陷入重伤时自动触发。在附近巡逻的精锐创伤小组会在1d6轮次内抵达你的位置（战力数值如战争手册的精英创伤小队），抵达现场后，他们会尽量保证你的安全，为你稳定重伤和致命伤，治疗你的严重伤势。并可以免费为你更换医疗义肢或回收你断掉的肢体，再将你转移至最近的医院。这一套流程结束后，你将可以直接恢复所有生命值。费用为月费，若你从职业能力里获得了这一项会员，则不需要支付费用。",ra:"SSR",pr:2e3,tier:"昂贵",grp:"公司人"},{n:"隐秘储藏空间",mf:"/",job:"游民",lg:"N",ds:"走私一直是世界各地最赚钱的行当之一，许多游民都想从这种活里赚些外快，于是他们都会为车辆进行一些“隐蔽改造”，座椅下、轮胎下、甚至引擎边的空间都不在话下。它可以提供一个L级别的空间用来存放任何物品，加价300可以获得一个XL的空间。每辆车只能改造一次。存放在隐藏空间里的物品对抗检查的检定+你的游民等级。",ra:"R",pr:300,tier:"平价",grp:"游民"},{n:"修车工具箱",mf:"/",job:"游民",lg:"Y",ds:"允许游民像技工一样修理自己的载具，并在拥有改造部件时，可以在任何地方为载具进行升级改造。卸下一个载具改造需要花费1d6*10分钟的时间，装上也需要这么多的时间。技工可以正常使用他的工具或是工坊帮助游民完成升级。",ra:"N",pr:70,tier:"平价",grp:"游民"},{n:"特调“鸡尾酒”",mf:"/",job:"游民",lg:"Y",ds:"对于自家的宝贝载具，有些游民在魔改之余，也从家族的“炼金术士”那学来了一些特别的燃料配方，经过自己一番捣鼓，能让引擎发挥出更强大的效率，但也会造成更大的磨损。游民可以花费一个动作将该燃料注入引擎，使载具当回合速度+4，但是当回合游民的载具驾驶技能-4。该物品不可用于描述中使用电做能源的车辆（无描述则默认醇2或者燃油）。该物品是一次性的，如果玩家需要，也可以用作液态醇2燃烧弹使用。",ra:"SR",pr:50,tier:"便宜",grp:"游民"},{n:"游民口粮",mf:"/",job:"游民",lg:"Y",ds:"游民们在应急时刻食用的“高蛋白”口粮，你在看到高蛋白这三个字的时候就应该猜到这里面装着什么了……它的口感很脆，但味道算不上好。对于游民来说，能在应急时刻保证吃饱就行了。它可以提供一餐所需的热量和蛋白质。算是一份普通人造食品级别的餐食，大约是一个s口袋的大小。",ra:"N",pr:1,tier:"便宜",grp:"游民"},{n:"荒野电台",mf:"/",job:"游民/媒体人",lg:"Y",ds:"在穿越荒野的漫漫长路中，人总需要什么东西来维持清醒。而荒野电台就是帮助长途司机们解闷的好帮手。事实上，荒野电台并没有一个电台中枢发射这些信号，而是由自愿的游民家族和司机们搭载信号中继天线组成的电台网络。自愿为电台提供信号的长途司机，就连刀锋掠夺者也很少会去攻击。电台的主播来自于游民的几大家族，他们多半都是在路上直播的。你需要一个专门设置的调频器安装在车用电台上才可以收听，而这调频器的秘密往往只有游民家族的族长知道。除了那些民俗八卦、音乐节目、情感故事以外，游民电台还提供了实时的路况汇报、天气预告、紧急求救、“顺风车”等服务。你也可以用电台呼叫同一家族的游民，在情况窘迫的时候，让家人来为你搭把手，送来些应急的物资，或是呼叫一场复仇行动。需要铭记的是，来自你家族的善意不是无限的，在呼叫之前，务必三思而后行……",ra:"N",pr:50,tier:"便宜",grp:"游民"},{n:"荒野求生组合包",mf:"/",job:"游民",lg:"Y",ds:"只有那些朝夕与荒野相处的人，才知道在真正无依无靠的时候自己该用什么活下去。这套组合包包含了睡袋、便携锅炉、折叠帐篷、防风打火机、求生匕首、滤水器、防虫药等一系列你在荒野求生时必备的物品，收纳在一个行李箱大小的背包中。你使用这个组合包时，可以在任何条件下获得良好的睡眠，并可以烹饪熟食、饮用净水。无论你处于何处，你都不会因为劣质的休息条件遭受惩罚，也可以食用普通人造食品级别的食物。",ra:"R",pr:500,tier:"值钱",grp:"游民"},{n:"鼠道钥匙",mf:"/",job:"游民/中间人",lg:"N",ds:"城市的下水道四通八达，城市的边境线千疮百孔，而幸运的是，你知道每一条隐藏在边境和下水道中的“鼠道”位置。而这就是打开那些鼠道所必须的钥匙或指引。鼠道是走私者对于秘密通道的特别称呼，它可以是地道、废弃的下水道、地铁线路、检修通道、没有画在地图上的小巷等。你可以经过一个成功的当地专家：鼠道检定（购买之后才解锁，且等级固定为5），获知最近的鼠道方位。大部分鼠道不能开着载具通过，只有少部分才可以。通过一个DV由RF决定的幸运检定可以在鼠道中找到临时的安全屋，可以提供基本的生活条件。躲进鼠道可以逃脱追捕，鼠道有时候也是捷径或是后门，虽然它往往足够隐秘，但它不会是绝对安全的……",ra:"SR",pr:700,tier:"值钱",grp:"游民"},{n:"匿名者 掌上代理",mf:"/",job:"中间人",lg:"N",ds:"每个地区中间人必备的魔改掌上代理。大部分都由市面上的杂牌代理改造而来，其特征是拥有极高的匿名性和保密性，不会被监听，也极难被追踪。且通常都留有一个链接暗网的后门，你对抗追踪的检定+4，有一个完全私密的交流软件，且可以不需要检定登录一个指定的暗网网址。出现紧急情况时，你还可以远程将其一键格式化。",ra:"SR",pr:400,tier:"平价",grp:"中间人"},{n:"走私者工具包",mf:"/",job:"中间人",lg:"N",ds:"每个中间人都有办法将违法物资通过神不知鬼不觉的方式从四面八方运进来。而这不仅要靠他们八面玲珑的口舌，也要依赖他们各显神通的走私偷运手段。它可以是一台经过特别改装的无人机，可以是一个留有隐秘空间的坐垫。甚至可能会埋藏在人或动物的体内……不论如何，你作为一个中间人，你维护你的走私路线总需要一些独特的办法，而这些改造用的工具就是你独属的“商业机密”。你使用这套你个人独属的工具进行货物走私的谈判和购入时，你的八面玲珑等级+1，购买价格额外-10%",ra:"R",pr:1e3,tier:"高级",grp:"中间人"},{n:"证件伪造机",mf:"/",job:"中间人",lg:"N",ds:"无论是身份证明还是驾照，这套功能齐全的机器都可以进行仿制。从纸的质感到油墨的质量，只要中间人手段通天，就没有不能弄得以假乱真的。当然，它并不负责将仿造的数据和信息录入对应的系统，若你要做到这点，可能还需要一个额外的网行者协助。",ra:"SR",pr:500,tier:"值钱",grp:"中间人"},{n:"隐藏枪套",mf:"/",job:"中间人",lg:"Y",ds:"一个有备而来的中间人绝对不会忘记带自己的武器，但你通常也猜不到他会把武器放在什么地方。这个隐藏枪套可以藏匿一把任意类型的手枪或者一把普通冲锋枪，且对抗搜查时的检定增加相当于你中间人职业等级的数值。高科技装备无法直接扫描到这个隐藏枪套内的武器。",ra:"R",pr:100,tier:"平价",grp:"中间人"},{n:"“仓库”",mf:"/",job:"中间人",lg:"N",ds:"一个能在江湖上立足的掮客往往狡兔三窟，他们会在城里四处寻找安全的地方藏匿违禁物品。这样的仓库既是你的立身之本，又是你在危急时刻的备用手段。最基础的仓库只有一间橱柜大小（2XL）的空间用来存放物品，你可以花费每个月500eb去扩容到一间车库的大小，或是花费2000eb去扩容到一间二室公寓的大小。这些“仓库”可能是下水道的某根废弃水管、某个不为人知的地下室、一栋无人问津的烂尾楼或是一座郊区的小破屋……只有你才知道这些“仓库”的方位，并拥有它们的钥匙。在仓库里可以储存任何它能装下的违法物品，在危急时刻，一个大型仓库也可以作为一个用来躲避的安全屋。或是利用专长“最终底牌”，让你提前准备好的某样东西刚好出现在里面。你需要提前和RF商讨你“仓库”和位置和可行性。",ra:"R",pr:100,tier:"平价",grp:"中间人"},{n:"战地急救包",mf:"/",job:"通用",lg:"Y",ds:"包含手术刀、注射器、绷带、酒精、麻醉剂、手术钳、夹板、止血绑带、缝线工具等手术用品，市面上有预组的套装，但你也可以自己配置一个。允许你在野外环境对人进行急救和手术。",ra:"N",pr:50,tier:"便宜",grp:"通用"},{n:"1加仑醇2",mf:"/",job:"通用",lg:"Y",ds:"一加仑醇2，不包括附带的油桶（一加仑的散装醇2油桶大约价格15eb）。这个价格在美洲大陆通常会在2eb以内波动，但大企业和游民家族们基本上都和沛卓石化、苏石化这些能源企业有协议，可以用更便宜的价格大宗购入。",ra:"R",pr:10,tier:"便宜",grp:"通用"},{n:"防炫光目镜",mf:"/",job:"通用",lg:"Y",ds:"使用者免疫手电筒和闪光弹的爆闪。",ra:"R",pr:400,tier:"平价",grp:"通用"},{n:"可编程全息诱饵",mf:"泽塔科技",job:"通用",lg:"Y",ds:"小型化的全息投影仪，只能最多用来在原地投影一个1.8m左右的人形，并播放预制的动画和语音。它的真实度还行，需要认真看才能分辨出它只是个投影。它伪造的形象不会被巷战雷达、超声波或是热成像视觉看见，其他情况下被肉眼观察时，对方需要经过一个DV14的专注检定，或是朝它攻击一次后才会察觉它是个假目标。只要它的投影装置没有被毁坏（视为部位瞄准，-4精准，拥有5sdp），它就能重复利用。",ra:"SR",pr:500,tier:"值钱",grp:"通用"},{n:"自动撬锁工具",mf:"/",job:"通用",lg:"N",ds:"一只精巧的小型机器人，可以附着在门锁上，通过内部勘探的感应仪辨别机械锁的机关，并自动且安静地撬开DV在16以下的机械锁。不能敲开电子锁。是一些间谍组织和潜伏记者会使用的小道具。",ra:"SR",pr:300,tier:"平价",grp:"通用"},{n:"锁匠工具包",mf:"/",job:"通用",lg:"Y",ds:"这东西比随处可以搞到的铁丝高级多了，它所包含的小工具可以解决任何形式的机械锁，在进行撬锁检定时，你获得+2的加值。但电子锁往往需要专业的黑客使用网行接入。",ra:"N",pr:50,tier:"便宜",grp:"通用"},{n:"环境分析装置",mf:"微科",job:"通用",lg:"Y",ds:"整合式的异常读数侦测装置，可以侦测周围10m的辐射、次/超声波、磁场环境、有毒气体等。它还会自动检测周围环境某项读数的峰值是否超过阈值，并随着读数波动而发出高频的蜂鸣警报和灯光提示。",ra:"R",pr:100,tier:"平价",grp:"通用"},{n:"夜视仪",mf:"/",job:"通用",lg:"Y",ds:"军用规格的夜视仪，可以装配在头盔的支架上，也可以单独携带。具有2km的可探测距离。夜视仪可以无视黑暗的环境。",ra:"R",pr:200,tier:"平价",grp:"通用"},{n:"热成像",mf:"/",job:"通用",lg:"Y",ds:"军用规格的热成像，可以装配在头盔的支架上，也可以单独携带。具有2km的可探测距离。热成像可以无视黑暗和烟雾的环境辨认活物，但无法穿透障碍物，也无法看穿玻璃。",ra:"SR",pr:1300,tier:"高级",grp:"通用"},{n:"声纳视觉仪",mf:"/",job:"通用",lg:"Y",ds:"在光学迷彩流行的今天获得普遍使用的探测仪器，和其他夜视仪、热成像目镜差不多大小。可以发射超声波探测100m半径内的一切形状，不能穿透墙壁和任何硬表面。",ra:"SR",pr:800,tier:"值钱",grp:"通用"},{n:"V-4000多光谱观测镜",mf:"泽塔科技",job:"通用",lg:"Y",ds:"特种部队装备的整合式目镜，可以装配在头盔的支架上，也可以单独携带。具有2km的可探测距离，整合了微光夜视仪、热成像和红外光、望远镜、紫外光等诸多功能，还额外整合了超声波传感器，虽然这个功能只有50m半径的可探测范围，但可以探测那些连热成像都无法观测到的东西。",ra:"SSR",pr:1700,tier:"高级",grp:"通用"},{n:"白噪音反制系统",mf:"军用科技",job:"通用",lg:"Y",ds:"该装置从原理上来说像是一种低频噪音制造装置，大约有一口平底锅大小，可以被方便地用绑带固定在身上。这种不易察觉的低频噪音也能在一定距离内遮蔽环境音，掩盖潜入行动中主动制造的声音，如脚步声和衣物摩擦声。但同时也会发出大量干扰性音波，用来抵消现在常见的声纳探测。在25m内对抗有听觉目标的察觉时，潜行+2，同时在声纳视觉里，制造一个25m半径的屏蔽球。该物品和任何声纳装置不能同时使用。",ra:"SR",pr:900,tier:"值钱",grp:"通用"},{n:"扩音设备",mf:"/",job:"通用",lg:"Y",ds:"市面上常见的喇叭、音响、扩音设备。一般都是杂牌，能响就行。能让你需要扩散的声音扩散到50m~200m距离。但由于失真严重，无法扩散摇滚青年的乐谱。扩散到500~1km的版本需要加价300eb",ra:"N",pr:50,tier:"便宜",grp:"通用"},{n:"望远镜",mf:"/",job:"通用",lg:"Y",ds:"常见的民用望远镜，可以用来观察3km开外的事物，加价80可以购买8km可视距离的军用望远镜。",ra:"N",pr:20,tier:"便宜",grp:"通用"},{n:"手持式激光测距仪",mf:"/",job:"通用",lg:"Y",ds:"军用规格的激光测距仪，可以用来观察6km开外的事物，同时利用不可视激光对目标进行测距。可以与智能链接相连，并将标记的目标方位上传至系统中进行定位。",ra:"SR",pr:200,tier:"平价",grp:"通用"},{n:"瑞士军刀",mf:"/",job:"通用",lg:"Y",ds:"瑞士最出名的国家产品，但市面上的瑞士军刀多半不是在瑞士生产的。这款军刀里包含了大部分你能想到的日用工具，可以作临时维修或者撬锁使用，但不能处理DV在12以上的撬锁或者维修状况。必要时候也能当作一把匕首。",ra:"N",pr:10,tier:"便宜",grp:"通用"},{n:"间谍摄影机",mf:"/",job:"通用",lg:"Y",ds:"可以伪装成一粒纽扣、一枚戒指、一块胸针的间谍摄影机。它最高可以提供1080p的画质，并拥有3小时的拍摄内存。它通常是不联网的，额外花费100eb可以活取拥有1km信号传输能力的款式，",ra:"R",pr:100,tier:"平价",grp:"通用"},{n:"间谍笔",mf:"/",job:"通用",lg:"Y",ds:"内置了录音装置的间谍笔，从外表上看和一只普通的书写笔无异，市面上有多种外形，总有一款你看得上的。它同样也可以正常使用，只要不被拆开，就不会发现里面的机关。它无法远程连线，因此需要定期回收。额外花费100eb可以活取拥有1km信号传输能力的款式。",ra:"R",pr:80,tier:"平价",grp:"通用"},{n:"高曝闪光灯",mf:"/",job:"通用",lg:"Y",ds:"可以安装在相机或者武器上，也可以单独持用的高曝闪光灯，自带频闪系统。可以在近距离干扰肉眼和光学装置。能作为武器的其中一个一个ROF启动或者作为一个只有1ROF的中型手枪启动，范围效果同霰弹，但有15m的射程。被击中者需要过一个DV19的折磨/药物耐性检定，否则获得三回合的目盲严重伤势。",ra:"R",pr:180,tier:"平价",grp:"通用"},{n:"通用防护服",mf:"沛卓石化",job:"通用",lg:"Y",ds:"应对各种生化危害的全封闭防护服，可以防护糜烂性毒气和酸液，同时对电绝缘。可以外接氧气罐以在不适合呼吸的地方进行生存。它在外力之下很容易破损，因此即便它能抵御电击，也会被电击箭头和电击弹药穿透。",ra:"R",pr:70,tier:"平价",grp:"通用"},{n:"辐射防护服",mf:"苏石化",job:"通用",lg:"Y",ds:"专门应对核辐射的重型三防连体防护服，内部加装了铅衬所以十分沉重（EV1），专门用来针对核辐射区域的清理和探索。对一切抵抗核辐射的相关检定+4。",ra:"R",pr:100,tier:"平价",grp:"通用"},{n:"反雷达披肩",mf:"荒坂",job:"通用",lg:"Y",ds:"荒坂忍者在特殊行动中会装备的反雷达涂料战术披肩，自带兜帽，能在较远距离回避雷达波的侦测，但是由于人体自身外形的局限性，导致其作用效果有限，在近距离时还是会被雷达波发现。穿戴此披肩后，雷达对你的侦测范围减半。",ra:"SR",pr:1e3,tier:"高级",grp:"通用"},{n:"反红外吉利服",mf:"军用科技",job:"通用",lg:"Y",ds:"军用科技狙击手使用的全身型反红外伪装，其内部的阻隔反射材料很厚重，自带EV1。穿戴后，玩家在50m外将不会被热成像观测到。在50m内对抗热成像的潜行检定+2。",ra:"SR",pr:800,tier:"值钱",grp:"通用"},{n:"城市迷彩斗篷",mf:"军用科技",job:"通用",lg:"Y",ds:"使用了光学迷彩原理的斗篷，在街上穿着十分时尚——但是要小心路上的车辆，它们就算长了眼睛也不一定能看见你。你可以花费一个动作启动，让你在十分钟内潜行检定+4，且无法被夜视仪和热成像发现。但是在强光和淋水条件下会失效。由于这种斗篷有一个复杂的供电和发生装置，自带EV1。",ra:"SSR",pr:1800,tier:"高级",grp:"通用"},{n:"无人机操作面板",mf:"/",job:"通用",lg:"Y",ds:"链接一台无人机进行手动操作，并可以实时观看无人机的摄像头视角，需要双手共持才能使用。",ra:"N",pr:600,tier:"值钱",grp:"通用"},{n:"无人机背包",mf:"/",job:"通用",lg:"Y",ds:"一个可以容纳两台中型无人机或者4台小型无人机的背包，只要你在操作，无人机就可以在一个回合内一同飞出。",ra:"R",pr:800,tier:"值钱",grp:"通用"},{n:"便携式脑舞目镜",mf:"/",job:"通用",lg:"Y",ds:"允许你随时随地读取并观看脑舞。",ra:"N",pr:100,tier:"平价",grp:"通用"},{n:"虚幻世界眼镜",mf:"泽塔科技",job:"通用",lg:"Y",ds:"一种整合了掌上代理功能的智能目镜，可以通过眼动或者手动识别操作。加价300可以购买可连接智能武器的版本，让智能武器的弹道、状态和弹药数量可以投影到视觉之中。使用带有智能链接的武器进行0~12m的射击时，精度额外+2。",ra:"R",pr:600,tier:"值钱",grp:"通用"},{n:"SAR系列 智能目镜",mf:"EBM",job:"通用",lg:"Y",ds:"整合式的智能目镜，可以代替义眼的功能，可以如同义眼一样安装义眼的义体，但只有一个槽位。它同样具备掌上代理的功能，可以随时用来上网。",ra:"SR",pr:400,tier:"平价",grp:"通用"},{n:"“商务人士”武器箱",mf:"斯特恩梅耶",job:"通用",lg:"Y",ds:"有高级公文包、吉他盒、高尔夫袋等不同样式，专给那些不易隐藏的大型武器特别设计的弹出式武器箱。在使用时，只需按一个把手上的按钮就能自动弹出，方便快捷。可以将市面上绝大多数（需要部署的武器除外）不易隐藏的武器随身携带。但依然会被安全部门检测到。",ra:"R",pr:300,tier:"平价",grp:"通用"},{n:"重装突击胸挂",mf:"军用科技",job:"通用",lg:"N",ds:"穿上后无法使用原本外衣的口袋（除非是大衣、风衣），提供了两个L级的腰包，6个m级的口袋和4个s级的口袋。同时附带一个可以挂住武器的挂扣和一个容纳任意类型手枪的枪套，以及四个专门为挂载手榴弹而设计的挂钩。它带有2的EV。",ra:"SR",pr:200,tier:"平价",grp:"通用"},{n:"轻型安保武装带",mf:"荒坂",job:"通用",lg:"Y",ds:"可以穿戴在外套下方，带有两个可以放置任意手枪类型或者任意手榴弹的口袋，和两个m级别的口袋，以及一个可以挂住普通冲锋枪的挂钩。",ra:"SR",pr:60,tier:"平价",grp:"通用"},{n:"雷达式金属探测仪",mf:"IEC",job:"通用",lg:"Y",ds:"一个有些笨重的分体式金属探测雷达，可以手持或者安装在肩部以及背包上。其发射一种可以和金属谐振的磁场波检测平面100m地下10m距离内的金属，并在另一部分的手持显示器上显示外形和距离。",ra:"SR",pr:600,tier:"值钱",grp:"通用"},{n:"金属探测器",mf:"/",job:"通用",lg:"Y",ds:"安检常用的道具，用来检测人身上的金属物品。距离很近，只能贴身侦测。用其检查他人身上藏匿的武器和义体时，揭示物品检定+3",ra:"N",pr:150,tier:"平价",grp:"通用"},{n:"重型工业用载重钩爪",mf:"苏石化",job:"通用",lg:"Y",ds:"需要双手握持的重型钩爪装置，体型相当于一杆手持的工业钻头。它可以朝最远80m远的位置发射一条高强度尼龙钩锁，其带有倒刺的末端可以插在坚固的表面作为支撑。固定完毕后，使用者可以凭借钩爪枪内置的攀越引擎将自己吸附到目标位置，或是作为摆荡摆到另一侧。它的绳索最多可以支撑500kg的重量（或者总计20体格的人）进行攀升，且可能会受目标表面影响导致可支撑重量减少（视RF决定）。要使用它，就需要像射击一样用重武器技能进行发射，它使用突击步枪的射表，若对着人体目标射击，它会直接造成8D6全威力伤害，且玩家可以在命中后的下一回合与敌方进行体格对抗，若成功，则可以将目标拽到玩家面前。若失败，则钩爪脱钩。",ra:"SR",pr:800,tier:"值钱",grp:"通用"},{n:"钩爪枪",mf:"/",job:"通用",lg:"Y",ds:"朝最远50m远的位置发射一条高强度尼龙钩锁，其带有倒刺的末端可以插在坚固的表面作为支撑。固定完毕后，使用者可以凭借钩爪枪内置的攀越引擎将自己吸附到目标位置，或是作为摆荡摆到另一侧。它的绳索最多可以支撑一个8体格的人（或者大约120kg重量）进行攀升，且可能会受目标表面影响导致可支撑重量减少（视RF决定）。要使用它，就需要像射击一样用长枪射击技能进行发射，它使用冲锋枪的射表，若对着人体目标射击，它会直接造成5D6全威力伤害，且玩家可以在命中后的下一回合与敌方进行体格对抗，若成功，则可以将目标拽到玩家面前。若失败，则钩爪脱钩。",ra:"R",pr:100,tier:"平价",grp:"通用"},{n:"火箭背包",mf:"轨道航空",job:"通用",lg:"Y",ds:"这种火箭背包一般要搭配外骨骼使用，但也有不借助外骨骼使用的案例，而这相当危险。它可以让使用者进行短距飞行或是滞空，最长使用时间10分钟。需要定期补充燃料，支持飞行1分钟的醇2燃料需要花费50eb。它需要一个动作启动，使用时，视作使用者的移动属性翻倍，且可以在空中进行任意机动。在空中机动时，前往任何一个位置（包括滞空）都需要过一个DV为（5+移动总距离/m）的空中载具驾驶检定，失败则会在抵达时坠落在地，承受3d6无法被避免的伤害并趴下（详见特殊战斗动作）。滞空时，敌方远程攻击使用者的精度-2。",ra:"SR",pr:2e3,tier:"昂贵",grp:"通用"},{n:"高压喷气背包",mf:"阿斯特丽",job:"通用",lg:"Y",ds:"这种小型背包常见于阿斯特丽、法国和轨道航空的空降部队中，可以挂载在腰后，看起来就像一对微型的矢量喷口。由于使用压缩空气作为动能，它不像火箭背包一样需要定时补充醇二，但这也让它的动能不如火箭背包那样强大，只能做一些短距离滑翔以及落地保护。使用者的跳跃距离翻倍，摔落伤害减半，若摔落伤害小于5，则完全减免这次伤害。同时使用者可以无视地形滑翔大约6m的距离（同样要使用使用者的移动）",ra:"R",pr:800,tier:"值钱",grp:"通用"},{n:"城市背包",mf:"/",job:"通用",lg:"Y",ds:"登山包、突击背包、或者是一个书包……相当于1个XL级别的口袋。但是由于其背在背上，你要取用里面的东西必须花费一个动作。",ra:"N",pr:50,tier:"便宜",grp:"通用"},{n:"多功能模组腰带组合",mf:"IEC",job:"通用",lg:"Y",ds:"你可以在建筑工人、摄影师、技术工人甚至城市佣兵的腰上见到它，它由一个提供了多种挂扣和快拆扣的腰带与两个穿在大腿上的固定装置组成，其上的挂扣可以挂上不同的腰包和装备挂钩，可以根据职业和使用情景的需求更换每一种不同的需求。它上面的4个挂扣可以提供以下的自定义模块：2个S级腰包（占用一个挂扣），1个m级腰包（占用1个挂扣），1个L级腰包（占用2个挂扣，EV1）,这些挂扣还可以用来暂时悬挂武器（不能是重武器），或是钩索。当你穿着大衣和风衣时，可以将挂着的武器隐藏在衣服下方。",ra:"R",pr:150,tier:"平价",grp:"通用"},{n:"战术挎包",mf:"/",job:"通用",lg:"Y",ds:"相当于一个L级别的口袋，附带拉链，可以快拆快取。",ra:"R",pr:80,tier:"平价",grp:"通用"},{n:"战备武装腰带",mf:"/",job:"通用",lg:"N",ds:"市面上常见的武装腰带，提供了可以容纳一把任意手枪类型的枪套，还有2个s级别的口袋，1个存放投掷物的位置，以及1个m级别的腰包",ra:"R",pr:70,tier:"平价",grp:"通用"},{n:"通话耳机",mf:"/",job:"通用",lg:"Y",ds:"市面上常见的无线电耳机，可以在200m内和链接的友方频道互相通话。有可能会被截获监听。",ra:"R",pr:20,tier:"便宜",grp:"通用"},{n:"军用卫星无线电",mf:"/",job:"通用",lg:"Y",ds:"可以在任意外部无遮挡环境中提供稳定的友方频道通讯。加密的信号使得截取信号难度大大增加（电子安防DV20或者魔偶破解DV15）",ra:"SR",pr:180,tier:"平价",grp:"通用"},{n:"手持军用长距无线电",mf:"/",job:"通用",lg:"Y",ds:"能提供3km的稳定加密友方频道通讯，穿墙性能良好，加密的信号使得截取信号难度大大增加（电子安防DV20或者魔偶破解DV15）",ra:"SR",pr:250,tier:"平价",grp:"通用"},{n:"拾音降噪耳机",mf:"/",job:"通用",lg:"Y",ds:"战术耳机，除了提供队内通话以外，内置的智能分析芯片可以快速分拣背景里的噪音和其他细微的动静，在聆听异常情况的场合中，你的察觉可以进行一次重骰。",ra:"R",pr:100,tier:"平价",grp:"通用"},{n:"激光扫描手榴弹",mf:"/",job:"通用",lg:"Y",ds:"一种带有耐摔外壳的可复用扫描手榴弹，可以远程链接掌上代理或者义眼，将激光扫描的画面实时投射在荧幕上。",ra:"SR",pr:100,tier:"平价",grp:"通用"},{n:"频闪手电",mf:"塔伦警用",job:"通用",lg:"Y",ds:"可以照亮20m范围，对15m内的单一目标持续造成闪光弹的效果，可以以占用一个附件槽的方式安装在枪械上。",ra:"R",pr:25,tier:"便宜",grp:"通用"},{n:"高流明手电",mf:"塔伦警用",job:"通用",lg:"Y",ds:"可以照亮100m范围，还可以对30m内的单一目标进行照射，目标需要经过一个DV22的折磨/抵抗药物检定，否则会陷入永久的目盲，眼部的义体和观测设备也会直接损毁。",ra:"SR",pr:250,tier:"平价",grp:"通用"},{n:"防毒面具",mf:"/",job:"通用",lg:"N",ds:"造型时尚的便携式防毒面具，自带可以呼吸两小时的滤毒罐。免疫吸入式毒气，但不能抵抗糜烂性毒气。但平民在公共场合佩戴会引来不必要的注意。市面上常见的通用滤毒罐价格10eb",ra:"N",pr:30,tier:"便宜",grp:"通用"},{n:"掌上代理",mf:"/",job:"通用",lg:"Y",ds:"市面上各种常见的杂牌掌上代理，配置不高，造型老土，但可以人手一个。开放掌上代理的基础功能",ra:"N",pr:150,tier:"平价",grp:"通用"},{n:"PiR2掌上代理",mf:"EBM",job:"通用",lg:"Y",ds:"可以远程链接义体的掌上代理，需要使用者至少要有一个全息投影装置或者义眼，以及神经链接。其本体就像一个外观精致的铁盒子，带在身上很有格调。",ra:"R",pr:280,tier:"平价",grp:"通用"},{n:"A级 掌上代理",mf:"泽塔科技",job:"通用",lg:"Y",ds:"目前市面上最好用的消费级掌上代理系列之一，自带投影装置，防水，可链接义体，而且造型美观。其自带的AI办公助手可以让你在上面进行检索时的检定+1。",ra:"SR",pr:800,tier:"值钱",grp:"通用"},{n:"网路通 掌上代理",mf:"微科",job:"通用",lg:"Y",ds:"一款方便你链接赛博空间……算了，我们忽略那些虚伪的广告词，这个高保密度的反追踪掌上代理是专门为了暗网冲浪、黑色行动、犯罪组织互相联络而准备的。它被追踪定位的相关检定难度+2，你使用它登录暗网时的交互界面检定+1，且你使用它链接在身上入侵网络建筑时，你免疫一次反入侵诱捕陷阱。",ra:"SSR",pr:1e3,tier:"高级",grp:"通用"},{n:"无线间谍摄像头",mf:"/",job:"通用",lg:"N",ds:"一种隐秘的微型间谍摄像头，可以远程发射信号链接你的设备。要找出它需要经过一个DV18的揭示物品检定。它在无电源供应下可以续航超过十小时，并提供1km的信号范围和2k的高清录影。",ra:"SR",pr:70,tier:"平价",grp:"通用"},{n:"无线间谍麦克风",mf:"/",job:"通用",lg:"R",ds:"一种隐秘的微型间谍摄像头，可以远程发射信号链接你的设备。要找出它需要经过一个DV18的揭示物品检定。它在无电源供应下可以续航超过十小时，并提供1km的信号范围和2k的高清录音。",ra:"SR",pr:70,tier:"平价",grp:"通用"},{n:"复合监察装置",mf:"荒坂",job:"通用",lg:"SR",ds:"可以用光学迷彩波隐藏自身的微型监控装置，可以同时记录声音、影像，且自带降噪效果。要找出它需要经过一个DV25的揭示物品检定。它在无电源供应下可以续航超过12小时，并提供1km的信号范围和2k的高清录影/音。",ra:"SR",pr:300,tier:"平价",grp:"通用"}],goods:[{n:"一顿狗粮",ef:"耐药/折磨DV10 失败将呕吐",ds:"你不会想知道这种就像是一坨呕吐物的东西到底是什么成分的。它并不是真正的狗粮，而是各种工业蛋白质块、维生素块、来历不明的肉和骨头混合在一起的产物。你如果能面无表情地每天把这玩意当饭吃，那你做什么都会成功的。",mf:"无",grade:"狗粮",ra:"N",pr:1,grp:"狗粮"},{n:"1磅压缩饼干",ef:"食用后-1D4 HP",ds:"用合成淀粉烤成的压缩饼干，啃一口下去可以把牙齿崩掉。这东西除了管饱以外没有别的用处，如果你考虑像那些游民和野战士兵一样放在水里煮开，那它就是一顿合成面粉糊。吃起来也和一碗狗粮没差多少。有传言说这种东西里面会有一些硬质纤维很难被消化，有人就因为这种搞笑的死法去世了，你最好祈祷一下它不是真的。",mf:"通用",grade:"狗粮",ra:"N",pr:1,grp:"狗粮"},{n:"10磅虫肉",ef:"/",ds:"作为后食品工业时代最闪亮的明珠，虫肉养殖业已经渗透了这个时代的方方面面。是平民蛋白质最主要的来源。当然，被提纯、磨粉、合成后的肉块基本上已经看不出虫肉的模样了，却总有一些餐馆会选择光明正大的烹饪它并端出来给人吃……虽然这东西入口也许口感还行，但光就外形来看，不是什么人都下得了嘴的。",mf:"伊比利亚农工",grade:"狗粮",ra:"N",pr:5,grp:"狗粮"},{n:"一根狗粮棒",ef:"/",ds:"由合成淀粉、工业糖精和一些乱七八糟的添加物组成。一口下去也许你会感觉口感还行，也能勉强管饱，可一回味起来，只会感觉恶心。更恶心的是，要靠这个填饱肚子，你至少得吃两大根。即便如此，这也已经是那些被叫做“狗粮”的食物里最容易入口的东西了。",mf:"大陆食品",grade:"狗粮",ra:"N",pr:.5,grp:"狗粮"},{n:"“街角汤”",ef:"耐药/折磨DV14 失败-2D6HP上限，翌日恢复",ds:"如果你有幸在贫民窟的夜市逛一圈，那你很有可能将见识到这种令人绝望的“街头美食”。它就像是一锅乱炖，由大家能找到的一切“新鲜食品”荟聚而成。而这通常包括了虫肉、老鼠肉、动物内脏、各种来历不明的蘑菇和杂草，以及一些口味齁人的工业调味料…一碗下去绝对会闹肚子，但至少他们会让这碗汤尝起来稍微可口一些。",mf:"无",grade:"狗粮",ra:"N",pr:1.5,grp:"狗粮"},{n:"牟牟汉堡™ 虫虫盛宴",ef:"/",ds:"在满大街的自动售货机和自动烹饪机里非常常见的“平民美食”，用两片合成淀粉面包，一块维生素块和一片烤至金黄焦脆的虫肉排加上各种稀奇古怪的廉价酱料与添加剂组成。你在大夏天把这样的一个东西放在外面晒三天三夜都不会腐烂说明了它那些工业添加剂的实力。尽管不论看起来还是尝起来都像一坨屎，但往好的方面想，它至少比狗粮棒好吃。",mf:"大陆食品",grade:"狗粮",ra:"N",pr:1,grp:"狗粮"},{n:"5磅“维生素块”",ef:"耐药/折磨DV10 失败将呕吐",ds:"大自然有很多藻类内部含有非常丰富的维生素，它们被搅碎提炼后就变成了这种难闻又难吃的东西，许多人吃它只是因为这东西是最廉价的维生素获取来源罢了。但说真的，这种东西一般都是拿去喂猪的。",mf:"大陆食品",grade:"狗粮",ra:"N",pr:3,grp:"狗粮"},{n:"5磅“蛋白质块”",ef:"耐药/折磨DV10 失败将呕吐",ds:"聪明的厂商都不会详细写出它蛋白质的具体来源，你觉得大自然最廉价的蛋白质来源是什么？懂得都懂……尽管厂商通常会在经过处理后往往会用大量添加剂盖过它原本的味道，但把这玩意拿来当饭吃还是容易令人作呕，更别提它本来就应该是给牲畜准备的。",mf:"大陆食品",grade:"狗粮",ra:"N",pr:2,grp:"狗粮"},{n:"一枚沙丁鱼罐头",ef:"/",ds:"前几次公司战争海洋的污染让沙丁鱼这种在海里常见的鱼类如今变得十分稀少，使得鱼肉价格也水涨船高。最终造成了这种名叫“沙丁鱼”罐头的东西里面实际上不是沙丁鱼，而是一种拥有沙丁鱼肉口感的肉泥，吃起来口感很怪。除此之外，最好不要好奇为什么这玩意的保质期长达10年之久。",mf:"伊比利亚农工",grade:"劣质人造食品",ra:"N",pr:3,grp:"劣质人造食品"},{n:"5磅海藻沙拉",ef:"/",ds:"自从真正的蔬果从平民的餐桌上销声匿迹之后，沙拉的原料就从绿色蔬菜变成了海洋里的绿色藻类。这些海藻……无一例外都非常难吃，但是富含成年人一天所需的维生素。",mf:"通用",grade:"劣质人造食品",ra:"N",pr:5,grp:"劣质人造食品"},{n:"10磅合成淀粉",ef:"/",ds:"这东西其实不能当真正的面粉用，虽然它通常会加一些配套的人工植物蛋白（通常从醇2小麦的废渣中提取）之后，凑合着也能用，但是它烤出来的面包口感又涩又硬，不加点工业糖精和软化剂根本无从下口。但你也没得选，不是吗？",mf:"通用",grade:"劣质人造食品",ra:"N",pr:6,grp:"劣质人造食品"},{n:"10磅速成米",ef:"/",ds:"在亚洲地区比较常见，在美洲的超市上也时常可以看见。相比传统的2季、3季稻，这种位于水培舱24小时紫外光照射的稻米只需一个季度即可成熟。部分经过基因改良的品种甚至只需要两三个月。这极大幅度地增加了它的产量，但也劣化了它的口感。它需要调味或是被做成其他料理才能勉强入口，如果只是单纯像正常做饭一样把它蒸来吃，它的口感简直干涩到无可下咽。",mf:"通用",grade:"劣质人造食品",ra:"N",pr:12,grp:"劣质人造食品"},{n:"1根清爽速食凝胶",ef:"食用后可以临时（一小时内）填补饥饿造成的惩罚。但是它不能当饭吃",ds:"从未如此清爽！从未如此嫩滑！这款太空食用的应急食品在地球上的销路也不错。是不少人街头巷尾的小零食。它能顶饱，提供可怜的一点营养，但只是暂时的。那些在舱外进行高烈度作业的工人们从来不会把这玩意当作正餐吃，尽管它的设计目的就是替代正餐。很可惜的是，它失败了，而且它的目标客户还给它起了个难听的外号：太空狗粮。它有如下口味： —柑橘薄荷味 —芝士蓝莓味 —牛奶草莓味 —清甜绿茶味 —什锦鲜果味 —酸奶葡萄味",mf:"轨道航空",grade:"劣质人造食品",ra:"N",pr:1,grp:"劣质人造食品"},{n:"1磅廉价点心",ef:"/",ds:"市面上各种杂牌的、盗版的、来历不明的甜食，配料表写得眼花缭乱。如果用来解解馋倒是还可以，如果用来当饭吃，很容易就会腻得犯恶心。",mf:"通用",grade:"劣质人造食品",ra:"N",pr:3,grp:"劣质人造食品"},{n:"1加仑平价果汁",ef:"搭配劣质人造食品一起吃的时候，不会因此减损人性",ds:"这种果汁里完全没有任何果汁含量，或者只有可怜的1%~2%，其余的全是工业添加剂，让这东西尝起来像果汁。同时里面还加入了“致死量”的工业糖精，以欺骗你的大脑释放多巴胺，掩过垃圾食品的各种怪味。",mf:"通用",grade:"劣质人造食品",ra:"N",pr:5,grp:"劣质人造食品"},{n:"1听可乐",ef:"搭配劣质人造食品一起吃的时候，不会因此减损人性",ds:"不熟悉的配方，熟悉的味道，而且相比以前也没涨多少价。从它正式称霸全世界到现在，它从来都不是什么健康饮品。",mf:"通用",grade:"优质人造食品",ra:"N",pr:2,grp:"劣质人造食品"},{n:"20盎司“泥巴咖啡”",ef:"一小时内无视劣质休息效果",ds:"市面上最便宜的咖啡因提取物，它叫这个名字不是没有原因的。除了能让人保持亢奋以外，几乎没有任何口感可言。许多公司的底层职员就靠着这个加班度日，因此而猝死的也不少。",mf:"通用",grade:"劣质人造食品",ra:"N",pr:1,grp:"劣质人造食品"},{n:"一罐午餐肉",ef:"吃一顿这个不会损失人性， 也不会恢复人性",ds:"这里面的真肉含量可能也就20%以内，其余的都是合成淀粉以及各种添加剂，然后染染色，让它看起来比较粉嫩。这东西吃起来至少口感没那么差，但也好不到哪去。",mf:"通用",grade:"劣质人造食品",ra:"N",pr:5,grp:"劣质人造食品"},{n:"一块能量棒",ef:"只吃一根的情况下可以在两小时内无视饥饿造成的负面效果",ds:"尝起来像劣质可可粉以及合成淀粉组合而成的东西，甜得令人发腻。它是一块热量炸弹。街头巷尾的小孩都爱吃，让贫困街区的孩子们蛀牙率奇怪的高。对于成年人来说，这种东西可以帮助他们临时保持精神，但要真靠它填肚子，至少要吃两三根。",mf:"通用",grade:"劣质人造食品",ra:"N",pr:1.5,grp:"劣质人造食品"},{n:"5磅合成肉",ef:"/",ds:"听说它尝起来和真肉差不多，但仅仅是还原口感就已经尽了厂商所有努力了。不要去看它的配料表，难道你指望在那边看到真肉的比例能超过30%吗？",mf:"通用",grade:"劣质人造食品",ra:"N",pr:7,grp:"劣质人造食品"},{n:"10磅土豆",ef:"/",ds:"土豆是这个星球上最伟大的主食来源之一，几乎在任何地方都能生长，毫无疑问是这个世界中产阶级最为广泛的碳水化合物来源。但自从耕地都被那些大公司用来种植醇2小麦后，就连这东西的价格也一路飞升。更可怕的是，公司为了在有限的耕地里提高它们的产量，将这种植物改良到了一种病态的级别。它的产量是上去了，可不知道为什么，它的口感总有一股塑料味。",mf:"大陆食品",grade:"优质人造食品",ra:"N",pr:12,grp:"优质人造食品"},{n:"10磅玉米",ef:"/",ds:"在随风摇曳的醇2小麦旁，通常就是经过基因改良的玉米地。在经过无数轮生态污染、基因改良后，这种玉米也和以往餐桌上见到的有很大区别。先不说微塑料和重金属含量的问题，它虽然个头更大了，但口感、含水量和营养等一些关键指标却不能和以往的相比。现在的主流烹饪方式是蒸一下再烤，最后弄点合成黄油裹上去，能让它口感上的问题消失大半。",mf:"大陆食品",grade:"优质人造食品",ra:"N",pr:12,grp:"优质人造食品"},{n:"5磅工业鸡肉",ef:"/",ds:"如果你去过南美洲旅游，那你经常可以看见规模巨大的工业鸡舍，从这些鸡舍里产出的肉都会被捣碎，并以“更高的效率”掺进各种合成肉产品里。在这个寸土寸金的世界里，大家都要讲求利润。而这就是利润最大化的操作，反正，消费者也算是能吃到鸡肉了，不是吗？",mf:"通用",grade:"优质人造食品",ra:"N",pr:18,grp:"优质人造食品"},{n:"1磅人造培根",ef:"/",ds:"公司将那些最便宜的边角料、部分内脏、脂肪、骨头搅碎成糊状，加上一些合成淀粉、大豆蛋白以及乱七八糟的添加剂，让它尝起来像猪肉。不要在意为什么它的脂肪花纹看起来那么整齐，反正一般在都市里生活的普通人这辈子都见不到猪，说不定它真长这样呢？",mf:"通用",grade:"优质人造食品",ra:"N",pr:9,grp:"优质人造食品"},{n:"一罐维生素片",ef:"一天之内服用三片，在晚上休息时额外恢复1d4体力",ds:"它是那些廉价海藻、药用植物和新鲜蔬果边角料合成的硬质药丸，是每个现代中产阶级家里的必备良药。在饭后服用一粒维生素片已经是每个家庭的“仪式”，以用来治疗这年头因为新鲜蔬果缺乏导致的维生素缺失。通常这样的一罐药片是100~150片装，不能直接用来当饭吃。更何况一天之内摄入过量维生素对人体来说也不是什么好事。",mf:"沛卓石化",grade:"优质人造食品",ra:"N",pr:30,grp:"优质人造食品"},{n:"1加仑“牛奶”",ef:"/",ds:"虽然牛还没有从这个世界上灭绝，但是在如今庞大的人口需求下，为了增大产量，奶牛牧场生产的牛奶通常都会稀释过后再进行调味才上架出售，这样的一罐牛奶里真正的牛奶占比最高不会超过50%。这确实确保了每一个人都能喝到牛奶，但代价是什么呢？",mf:"通用",grade:"优质人造食品",ra:"N",pr:10,grp:"优质人造食品"},{n:"6枚海藻寿司",ef:"你吃这顿饭的最低时间仅需30秒",ds:"用速成米和海苔包的寿司，里面可能包着些合成肉，或者是虫子，也有可能是其他海藻。对于一个家里连微波炉都没有的工薪族来说，这就是一顿最好的员工餐了。在很多日本企业，这甚至成为了标配。它足够效率，足够简单，还提供了足够的能量，还有比它更完美的一顿饭吗？",mf:"通用",grade:"优质人造食品",ra:"N",pr:13,grp:"优质人造食品"},{n:"1磅合成生牛排",ef:"/",ds:"每个合成牛排的厂家都会宣传它们家的牛排有很高的真肉含量，通常这个数值是20%~30%左右，也有些“良心”厂家会宣称它们家的有50%以上……事实证明这些厂家哪怕往里面混一些牛油就都算数。说实话这种价格吃一块牛排可以了，管他是不是合成的。吃死了再说。",mf:"通用",grade:"优质人造食品",ra:"N",pr:12,grp:"优质人造食品"},{n:"10枚鸡蛋",ef:"/",ds:"也许你会认为作为这个世界最庞大的养殖工业的副产品，鸡蛋可能是平民能尝到最接近新鲜自然食品级别的食物，那你就大错特错了。这个时代的每一只肉畜都经过无数道基因筛选和改良，为了大量生产，你绝对猜不到养殖厂里的母鸡现在都长什么样子……呃，我是说，你最好想都不要想。",mf:"生物科技",grade:"优质人造食品",ra:"N",pr:20,grp:"优质人造食品"},{n:"一袋MRE",ef:"若你因为连续进食劣质食品而有人性减值，则吃一顿这个一次性恢复双倍人性",ds:"这些军用包装的野战食品长期以来都是美洲大陆的硬通货，以至于在库存消耗殆尽后，NUSA和各自由州的军队还在偷偷走私这些食物。它们足够一个成年人一顿饭的餐量，通常是各种口味的预制合成餐。其常见口味如下（注：这些口味只是口味，并不代表里面有真货）： —意大利肉酱拌面 —西班牙海鲜烩饭 —切达奶酪汉堡肉 —鸡蛋健康杂蔬粥 —四川麻婆红烧肉 —辣酱蚕豆牛肉丸 —墨西哥辣椒鸡丁",mf:"大陆食品",grade:"优质人造食品",ra:"R",pr:15,grp:"优质人造食品"},{n:"街边烤串",ef:"若你因为连续进食劣质食品而有人性减值，则吃一顿这个一次性恢复双倍人性",ds:"在各大城市的街头巷尾都十分常见的街边烤肉摊，里面没有真货，都是各种来历不明的合成肉，以及便宜的海藻和粗粮。好在这个年代香料都很便宜，在猛料之下你也尝不出刚才吃了啥。孩子们每次和家长一起逛夜市的时候，都会对这些东西流口水。该价格不是一串的价格，而是能填饱一个成年人一顿烤串的价格。",mf:"无",grade:"优质人造食品",ra:"R",pr:20,grp:"优质人造食品"},{n:"一顿拉面",ef:"若你因为连续进食劣质食品而有人性减值，则吃一顿这个一次性恢复双倍人性",ds:"用预制的汤粉和合成淀粉面条扔进锅里小煮两下做成的拉面，然后再加几片午餐肉或者合成肉，是你可以在街头吃到最好吃的街头食物之一。但很快你就会发现全城大街小巷所有小贩的面条几乎尝起来都一个味，不过，这也让你无论去哪都能吃到你最爱口味的拉面，难道不是一件好事吗？",mf:"无",grade:"优质人造食品",ra:"R",pr:15,grp:"优质人造食品"},{n:"街头汉堡/塔可饼",ef:"若你因为连续进食劣质食品而有人性减值，则吃一顿这个一次性恢复双倍人性",ds:"美洲大陆最标志性的街头美食，两块合成面包/一片玉米饼配上海藻叶和合成肉饼，再淋上各种各样满溢出来的酱汁，它就能成为工薪族上班时能买到的最完美的早餐。如果再配一杯可乐或是氚麦菲士…哇，街头巷尾的小鬼都馋哭了。",mf:"无",grade:"优质人造食品",ra:"R",pr:10,grp:"优质人造食品"},{n:"一份外卖披萨",ef:"若你因为连续进食劣质食品而有人性减值，则吃一顿这个一次性恢复双倍人性",ds:"自从无人机完全取代外卖员的工作之后，配送成本被压到了几乎没有的价格。现在只需要在代理上随手一点，一张新鲜可口的披萨就会在几分钟内送过来。这几乎已经成为了美洲大陆的一种独特文化，世界各地的人被问到“美国人平常都吃什么”，大家第一时间想到的都是一个躺在沙发上大嚼披萨的胖子。",mf:"通用",grade:"优质人造食品",ra:"R",pr:15,grp:"优质人造食品"},{n:"一根冰淇淋",ef:"夏天食用时，和正常食物一样恢复人性。",ds:"最伟大的夏日零食，同时也是你最美好的童年回忆。它现在不再用真的奶油和水果香料做了，但口味还是和当年那样甜美，甚至更甜一点！否则食客就该吃到合成香料的怪味了。",mf:"通用",grade:"优质人造食品",ra:"R",pr:5,grp:"优质人造食品"},{n:"一枚甜甜圈",ef:"若你因为连续进食劣质食品而有人性减值，则吃一顿这个一次性恢复双倍人性",ds:"街头巷尾的面包店都有卖，条子们的最爱解馋小零食。虽然也有咸味的，但市面上主要售卖的都是各种甜酱做的甜甜圈。对于其他国家的人来说，这玩意的风味非常腻，不配饮料几乎可以把人齁死。要用它解决一顿饭至少要吃五根。",mf:"通用",grade:"优质人造食品",ra:"R",pr:2,grp:"优质人造食品"},{n:"醇²",ef:"在2小时内精神百倍，免疫因为劣质休息条件造成的损害",ds:"一种添加了醇2小麦成分的功能性饮料，口感有一股麦香，十分甜美可口。它的里面含有巨量的咖啡因，但比市面上的浓缩咖啡好喝多了。虽然在它的罐身上贴有并不推荐任何人一天饮用三瓶以上的标示，但依然有许多人把这玩意当甜水喝。",mf:"大陆食品",grade:"优质人造食品",ra:"R",pr:5,grp:"优质人造食品"},{n:"氚麦菲士",ef:"搭配任意食品一起吃的时候，不会因此减损人性",ds:"它的原料作为醇2小麦提炼后的副产品之一，沛卓石化想到了一种绝佳的回收再利用方案。而在此之前很多人想都不敢想……它尝起来味道有点接近于啤酒，有很浓的小麦味。但它的酒精含量大概在1%~2%左右，除此之外是一种非常独特且浓郁的……机油味？",mf:"大陆食品",grade:"优质人造食品",ra:"R",pr:4,grp:"优质人造食品"},{n:"一瓶伏特加",ef:"和正常食物一样恢复人性，但需要过一个DV15的药物抵抗/折磨检定，失败在三小时内所有检定-2。",ds:"幸好这年头土豆不像正经小麦一样稀缺，你仍然可以在各大酒品商店里搞到这些用土豆蒸馏的伏特加酒。常常有人抱怨这年头的伏特加口感比以前差了不少，所以各大酒厂不约而同的加大了酒精的浓度。只要让这些酒鬼都醉倒过去，就没人抱怨酒的质量变差了。",mf:"通用",grade:"优质人造食品",ra:"R",pr:10,grp:"优质人造食品"},{n:"一瓶合成威士忌",ef:"和正常食物一样恢复人性，但需要过一个DV10的药物抵抗/折磨检定，失败在三小时内所有检定-2。",ds:"曾经作为市面上销量最广的平民酒水之一，它几乎在你见过的每一个酒吧里都有，是普通人忘掉一天所有烦恼的首选。而在谷物价格飙升的今天，想要喝那种传统的，用大麦酿制的就不太容易了。现在你只能喝到用合成酒精和调味剂混合而成的人造威士忌。对于那些从世纪初活到现在的老酒鬼们来说，这简直比下地狱还痛苦，但谁说现在的这个世界不是一个巨大的地狱呢？",mf:"通用",grade:"优质人造食品",ra:"R",pr:30,grp:"优质人造食品"},{n:"游民炖菜",ef:"24小时内增加1D6点临时生命值，不可叠加。",ds:"尽管每一个游民家族都声称他们内部有属于他们自己的炖菜秘方，但每次游民家族之间进行聚餐时，他们总会发现大家吃的炖菜口味都大同小异。其实它也没什么门道，无非是将一些游民自己种植或是路上收割的野菜加上合成肉或是野生动物肉，再下些番茄酱和狠料，就能做出一锅又美味又健康的炖菜。然而要在城里吃一锅这东西可不容易，只有你和一些游民家族关系足够铁，他们才会在聚餐时把自家秘传的炖菜分你一勺。",mf:"游民限定",grade:"优质人造食品",ra:"SR",pr:"/",grp:"优质人造食品"},{n:"一条沙丁鱼",ef:"/",ds:"如果你正好生活在海边，正好有一艘远洋小艇，正好有些专业捕鱼设备，那你在世界上的一些特定海域还是可以钓到这种鱼类的。但你最好注意一下，随着海洋食品工业在近几年的技术突破，一些食品公司已经会“圈养”一片海域作为自己的领土，在里面钓上来的鱼不仅要额外罚款，还有可能会被通缉。",mf:"皇家都会农业",grade:"新鲜食品",ra:"SR",pr:60,grp:"新鲜食品"},{n:"1磅金枪鱼肉",ef:"/",ds:"即便放在自然生态还完好无损的过去，金枪鱼也是海中的珍馐。如今这些只在大公司圈养的专属海域中成长的金枪鱼更是普通人难得一见的美味。然而由于食品公司联合对这种鱼类的垄断，除非去他们专属的海鲜市场订购，否则就连黑市都很少见这种鲜美的鱼肉。",mf:"皇家都会农业",grade:"新鲜食品",ra:"SR",pr:150,grp:"新鲜食品"},{n:"一头活猪",ef:"/",ds:"从一所工业猪圈里买一头活猪并不容易，这些只需四个多月就能出栏的猪多半会被直接送进屠宰场，如果你有幸获得了一头，不管你拿去做宠物还是自己养着宰了吃，它都会是一项昂贵的爱好。",mf:"伊比利亚农工",grade:"新鲜食品",ra:"R",pr:700,grp:"新鲜食品"},{n:"一只活鸡",ef:"/",ds:"这年头各大食品店和餐馆里卖的鸡肉多半都是科技与狠活，是那些长得像鸡，尝着像鸡，实际上不是鸡的东西。但假如你真的能搞到一只真的活鸡，那你最好把以前压箱底的食谱全都翻一遍，以确保它能够死得其所。",mf:"伊比利亚农工",grade:"新鲜食品",ra:"R",pr:80,grp:"新鲜食品"},{n:"10枚基因改良蛋",ef:"/",ds:"这种蛋和工业鸡舍里生产的那种蛋完全不一样，不仅个大饱满，无菌无臭，还富含营养。吃过一次这种蛋你就不会想回去吃那些工业蛋了。",mf:"通用",grade:"新鲜食品",ra:"SR",pr:200,grp:"新鲜食品"},{n:"10磅面粉",ef:"/",ds:"由真正的，并非醇2小麦碾成的精细面粉，在这个时代已经十分少见了。你也许可以在那些为企业员工和小康家庭特供的会员超市里看见，至少便利店和那些面向普通中产市民的超市里已经基本上见不到了。",mf:"通用",grade:"新鲜食品",ra:"R",pr:50,grp:"新鲜食品"},{n:"1加仑 真牛奶",ef:"/",ds:"如果你愿意多花点钱，那么你也是可以在一些超市的货架上看见这些100%纯牛奶的。它们很贵，但那醇香的口感确实是其他“牛奶”比不了的。",mf:"通用",grade:"新鲜食品",ra:"R",pr:80,grp:"新鲜食品"},{n:"1磅真牛排",ef:"若你因为连续进食劣质食品而有人性减值，则吃一顿这个一次性恢复三倍人性",ds:"在美国中部那些由大陆食品建起的生态巨构里，有好几处是专门为养牛而建立的生态牧场。这些牧场不仅产出牛奶，还产出牛肉。但牛肉价格如今这么贵的其中一个原因在于，它们基本上都被大公司买断了。很多大公司会专门订购牛肉为他们的中低层管理和优秀员工提供公司餐，在它们的专属餐厅里吃牛排往往也有更高的优惠价。这些牛肉都供不应求，只有一小部分会流向市场，并被标上高额的价格。",mf:"通用",grade:"新鲜食品",ra:"SR",pr:120,grp:"新鲜食品"},{n:"10磅新鲜蔬菜",ef:"在晚上休息时额外恢复1d4体力",ds:"这些蔬菜在几十年前几乎在每个百姓的餐桌上都可以看见，然而时过境迁，这些最容易获取的食物竟成为了普通人高不可攀的东西。而且更糟糕的是，大公司们为了炒起新鲜蔬菜的价格，把原本民间常见的品种全都“灭绝”了，取而代之的是它们各自垄断的高科技改良基因蔬菜，不仅更加鲜艳饱满，口感也更可口紧实。除了一些偏远地区还有自耕农和黑帮经营的水培田以外，你基本上无法在民间找到那些老品种的蔬菜了。",mf:"通用",grade:"新鲜食品",ra:"SR",pr:180,grp:"新鲜食品"},{n:"10磅新鲜水果",ef:"若你因为连续进食劣质食品而有人性减值，则吃一顿这个一次性恢复三倍人性",ds:"这个年代的土地兼并达到了一种令人发指的程度，一片土地该种什么，能种什么，由那些横跨大洲的食品公司们说了算。现在的技术更是可以廉价合成模仿果物香气的工业香精，导致食品加工厂也不是那么刚需水果了。而大公司们更是会直接承包剩下那点少得可怜的水果产量提供给高管，最终，能流通到市场上的水果都贵得难以忍受，彻底从普通人的餐桌上绝迹。",mf:"通用",grade:"新鲜食品",ra:"SR",pr:250,grp:"新鲜食品"},{n:"10磅基因选优蔬果",ef:"在晚上休息时额外恢复1d6体力",ds:"你在生物科技的高科技水培棚里可以看见这些鲜艳欲滴的基因改良蔬菜，它们都是大客户的特别订单，连一斤都不会流通到市场上。这个品级的每一种蔬果都会特别调整口味和口感，确保挑剔的富裕食客每一口都能满意。",mf:"生物科技",grade:"优质新鲜食品",ra:"SSR",pr:500,grp:"优质新鲜食品"},{n:"1磅特选牛排",ef:"若你因为连续进食劣质食品而有人性减值，则吃一顿这个一次性恢复至原点",ds:"你若有幸被受邀前往生物科技的一些设立在地球污染指数最低地区的那些生物实验室，你可能就会见到他们专门在此地培养、改良基因的肉畜。这些肉畜的一块肉排会被炒上天价，整头牛更是可以和一台小轿车的价格相提并论。在很多公司的特供餐馆里，你要是不预约，还没机会吃上这种肉呢。",mf:"生物科技",grade:"优质新鲜食品",ra:"SSR",pr:420,grp:"优质新鲜食品"},{n:"一根伊比利亚火腿",ef:"享用一顿由它烹饪的菜肴， 人性恢复1d8，上限同本品级食品的上限",ds:"由西班牙古法工艺结合现代科技基因优选猪肉熏制的火腿肉。每年产量有限，且订单都订到了好几年后。常人只能在影片里和综艺上看见富人们享用这种人间珍馐。除非你正好有一位大款好友，否则大概这辈子也无法想像它的美味。",mf:"伊比利亚农工",grade:"优质新鲜食品",ra:"SSR",pr:6e3,grp:"优质新鲜食品"},{n:"1磅灭绝生物肉",ef:"享用一顿由它烹饪的菜肴， 人性恢复1d8，上限同本品级食品的上限",ds:"现在一些已经灭绝的动物已经通过基因克隆重现在动物园里了。不用我说，肯定会有人好奇它们都是什么味道。于是生物科技在各地区总部的餐厅里都会提供这一服务。听说渡渡鸟的肉尝起来非常顶级，也难怪它们当年为什么灭绝了……",mf:"生物科技",grade:"优质新鲜食品",ra:"SSR",pr:800,grp:"优质新鲜食品"},{n:"水晶宫™温室葡萄酒",ef:"用它来贿赂他人额外提供+5加值，最多分十次使用",ds:"这种酒品理论上只能在水晶宫这一个地方享用，要把它从空间站带回地球需要付出天价的欧元。酿造这种葡萄酒的每一个环节，从葡萄种子的培育到酒水的酿制，都在太空的零重力中进行。这赋予了它一种独特于地球上所有葡萄酒的特殊风味。在地球的品酒会上，不说一瓶，就算是一口，都会被炒上天价。",mf:"欧空局",grade:"优质新鲜食品",ra:"SSR",pr:1e4,grp:"优质新鲜食品"},{n:"10磅优选粗粮",ef:"持续进食至上限可以增强你的免疫力，药物抵抗/折磨+2",ds:"即便都是在实验室里成长的粮食，有些粮食的成长环境和待遇也和其他种类的不同。速成米大棚的隔壁经常就是这些为富人和各国政要准备的粗粮。只要吃一口，哪怕是一口，你这辈子都不会忘记它的风味。有些公司中层管理不惜成为月光族，也要自己家里的粮食储备都是这些优质粗粮。",mf:"皇家都会农业",grade:"优质新鲜食品",ra:"SR",pr:300,grp:"优质新鲜食品"}],clothes:[{n:"皇帝的新装™完美之躯",mf:"新科",style:"超越主义",ev:"0",pt:"除头外全身",cap:"/",ds:"这东西就和它的字面意义一样，纯粹强调使用者那如文艺复兴雕塑般的完美体态，如果使用者没有，那这套衣服也能通过自编程的纳米机械肌肉来帮助使用者实现。这种神奇的流动金属由数以亿计的可编程纳米机器人组成，就好像使用者的第二层肌肤，可以在链接神经链接后，随心情自由塑造它的形态。",feat:"+1SP，+1敏捷",ra:"SSR",pr:2e4,grp:"上流"},{n:"中子星™异裁磁浮休闲服",mf:"新科",style:"超越主义",ev:"0",pt:"躯干胳膊or 腿",cap:"4m",ds:"来自法国的顶流时尚设计师杜兰·莱昂热曾经这么评价：中子星系列的服装设计师简直不足以用“大胆”来形容，可以说他们是在施展魔法！这套结合了电磁浮设计的服装可以直接让装饰和一些衣服模块浮在穿着者的身体表面大约1cm的高度，同时还会在边缘散发出微光，就像外星科技一样。这些磁浮模块还可以用来悬停一些金属制品，随时都能拿下来取用，让你看起来就像个魔法师。",feat:"COOL+2",ra:"SSR",pr:8e3,grp:"上流"},{n:"亚马逊™探险夹克",mf:"奇装",style:"新军权主义",ev:"0",pt:"躯干、胳膊",cap:"4m",ds:"旧日殖民帝国的余晖仍然影响着整个世界的运转。而那些殖民帝国最核心的精神是什么？答案显而易见，那便是探险精神！这套复古的夹克上还带有夸张的流苏和仿旧时代军事贵族的全息勋章，其采用的高级纳米尼龙面料可防火耐酸，可以适应世界各地的恶劣环境。你大可在点燃篝火的时候把它直接丢进火堆里，再把它拿出来时，它上面的脏污就“清洗”完毕了！",feat:"COOL+1 免疫强酸和电击，火焰伤害减半",ra:"SSR",pr:6e3,grp:"上流"},{n:"绅士甲胄™",mf:"新科",style:"新军权主义",ev:"1",pt:"躯干胳膊or 腿",cap:"1m+2s",ds:"这东西看起来像是从某部太空歌剧里走出来的上将军装，板正的造型和极具威慑力的，棱角分明的线条设计让每一个看见它的人都情不自禁向对穿戴者敬礼。尽管这套衣服的背部和躯干的硬质护甲设计会强迫穿戴者挺直腰杆，而且穿着有点沉，但是它带来的气质是无与伦比的，足以让你成为会议室里最威风凛凛的明星。它成套贩卖，因此价格是购买覆盖全身的一整套的价格。",feat:"躯干15sp，四肢11sp， 不会因为近战导致SP折半",ra:"SSR",pr:9e3,grp:"上流"},{n:"天穹上将™定制休闲服",mf:"菲茨博",style:"新军权主义",ev:"0",pt:"躯干胳膊or 腿",cap:"2m+2s",ds:"新军权的设计要点便在于肃穆典雅，以及那股不近人情的威慑力。即便脱离了正装，把这套设计语言放置在休闲服上也十分引人注目。不仅如此，天穹上将系列还整合了最新的纳米防弹面料，既保证了使用者穿着舒适，又能确保在突发的危险状况下不被流弹所伤。它成套贩卖，因此价格是购买覆盖全身的一整套的价格。",feat:"具有14的SP",ra:"SSR",pr:5e3,grp:"上流"},{n:"禅™定制和服",mf:"荒坂",style:"新军权主义",ev:"1",pt:"躯干胳膊or 腿",cap:"2m",ds:"这款块状设计的和服定义了新时代的东方美学：典雅、禅静、以及那份独有的君临万物的傲慢。它使用了一种特别的高级化合纤维，无论在什么情况下，都可以保持衣物的平整，几乎不会产生任何褶皱。这也使得它可以运用更加大胆的块状配色设计，以在第一眼就让人感觉到十足的威压感。它成套贩卖，因此价格是购买覆盖全身的一整套的价格。",feat:"具有13sp， 免疫一切重手枪等级的子弹射击",ra:"SSR",pr:7e3,grp:"上流"},{n:"天界御使™",mf:"奇装",style:"新刻奇主义",ev:"0",pt:"躯干胳膊or 腿",cap:"2m",ds:"这款和精灵战线OL联名的高档休闲礼服能够直接再现游戏里的形象和装扮。它的基础款式是游戏里的氪金皮肤“天界御使”礼服套装，其纽扣、手环、腰带都内置了高精度全息投影仪，启动之后能够直接还原游戏里的多种套装变体和浮夸特效。包括那些金光闪闪的盔甲、翅膀和光圈，甚至是游戏里那些全服限量的神话武器，都可以投影在使用者的身上，甚至是武器上！它成套贩卖，因此价格是购买覆盖全身的一整套的价格。",feat:"COOL+3",ra:"SSR",pr:1e4,grp:"上流"},{n:"迪斯科夹克",mf:"菲茨博",style:"新刻奇主义",ev:"0",pt:"躯干、胳膊",cap:"2m+2s",ds:"佣兵舞会中最耀眼的明星！如果强尼银手活到了今天，他一定会穿着这套夹克去再炸一次荒坂塔。这件华丽的夹克采用了摇滚明星的经典大开襟设计，其上缝了大量荧光亮片，闪瞎敌人的眼睛。不过，穿着这玩意在晚上潜行不是一个好主意。",feat:"具有12的SP，潜行-2，任何在0~12米朝你攻击的敌人，都会在命中上承受-2的减值。",ra:"SR",pr:2e3,grp:"上流"},{n:"超新星™玻璃纤维套装",mf:"新科",style:"新刻奇主义",ev:"0",pt:"躯干胳膊or 腿",cap:"3m+4s",ds:"这件亮闪闪的玻璃纤维夹克是各国舞台明星的新欢。只要受到舞台灯光照射，它就会爆发出如同迪斯科灯球一样的炫彩光亮。同时它内置了一个微型降噪扩音器和一个音乐播放器，可以确保你在演唱会上不掉链子，也能确保你招摇过市的时候所有人都会为你回头。它成套贩卖，因此价格是购买覆盖全身的一整套的价格。",feat:"COOL+1，潜行-2 全体目光向我看齐专长检定+3",ra:"SSR",pr:4e3,grp:"上流"},{n:"铬金野兽™瑰丽皮草",mf:"新科",style:"新刻奇主义",ev:"0",pt:"躯干、胳膊",cap:"2L",ds:"这件大开襟复古皮草上的毛领用的并不是真实动物的皮毛，而是一种最新的纳米发光管，能自内而外散发出一种温和的全息柔光，可以让“鱼”在你的领子里游泳。一些定制款还能再搭配上它从生物科技定制的灭绝动物皮革，能让所有第一眼见到你的人都知道你是个大明星。",feat:"服装风格+4，潜行-2 全体目光向我看齐专长检定+3",ra:"SSR",pr:8e3,grp:"上流"},{n:"奥菲利亚™彗星面纱",mf:"奥林匹亚",style:"古典奢靡主义",ev:"0",pt:"头",cap:"/",ds:"2043年，一位名叫埃尔维拉·索托马约尔的欧洲名流在出席她丈夫的葬礼时，就佩戴了这枚绝美的全息彗星面纱。它让穿戴者时刻如同女神落泪一般，不断落下闪闪发光的彗星泪滴，既充满了神秘感，又美丽得令人叹息。当天几乎每一本时尚杂志都刊登了她的这副形象。至于她死掉的丈夫，不管后世和粉丝对他怎么评价，至少现在肯定是比不过他老婆的风光了。",feat:"你的所有交涉技能+3",ra:"SSR",pr:5e3,grp:"上流"},{n:"王朝™定制西装",mf:"奥林匹亚",style:"古典奢靡主义",ev:"0",pt:"躯干胳膊or 腿",cap:"4s",ds:"这家来自英国的服装公司一直以高端定制为主业，由他们设计的服装不仅优雅合身、不怕脏污、冬暖夏凉，还拥有一定的防护性能，有品位的公司高管家里多少都会有一套。对于一部分欧洲公司来说，家里至少得有一套王朝™的高定西装，才能算是入了上流社会的门槛。它成套贩卖，因此价格是购买覆盖全身的一整套的价格。",feat:"具有12sp， 免疫一切手枪穿甲等级的子弹射击",ra:"SSR",pr:4e3,grp:"上流"},{n:"奥菲利亚™流光丝袍",mf:"奥林匹亚",style:"古典奢靡主义",ev:"0",pt:"躯干、腿部",cap:"2s",ds:"当它在2046年戛纳影展亮相的时候，几乎立刻吸引了所有人的目光。它就好像根本不存在于使用者身上似的，只是一层自由流动的全息影像。事实上它的原理也差不多。它是一种材料保密的纳米可编程丝绸，在平常呈灰色，经过编程后，使用者可以让它完全透明，并用上面微小的全息投影仪来制造最高3cm厚度的浮动全息影像。穿上这个，你可以在身上缠一只会动的全息龙陪你一起出席各种盛大场合。还有什么能比这种方式更加炫耀呢？",feat:"COOL+1，服装风格+2",ra:"SSR",pr:18e3,grp:"上流"},{n:"珠光宝气™宴会礼服",mf:"奥林匹亚",style:"古典奢靡主义",ev:"0",pt:"躯干胳膊or 腿",cap:"1m",ds:"这套奢靡的礼服外观就像闪闪发亮的罗马长袍，意在强调穿戴者无比华贵的气质和体态（尤其是后者）用时尚批评家的话说：它就是一块纳米编程丝绸上嵌了几十块发光宝石。但谁叫那些有品位的富豪都好这口呢？而且，那些歌星影星在各个颁奖典礼上穿着它时，几乎每一次都能吸引全场的目光。它成套贩卖，因此价格是购买覆盖全身的一整套的价格。",feat:"服装风格+4",ra:"SSR",pr:15e3,grp:"上流"},{n:"罗夏™波动面具",mf:"吉布森",style:"机能异端主义",ev:"0",pt:"头",cap:"/",ds:"有些人不太喜欢让别人看清自己的脸色，又不想做那种有些疼还需要勤维护的义体手术，那这个全息面具就是为他们准备的。它通过全息投影技术将一整块罗夏墨迹测试投射在使用者的脸部，可以随使用者的心情自由变化图案。不过说句实话，那只是一滩对称的墨迹而已，谁能知道它到底代表了什么？（无法和12sp以上的头盔兼容）",feat:"他人无法对你察言观色",ra:"R",pr:100,grp:"中产"},{n:"黑客战术™尼龙冲锋衣",mf:"吉布森",style:"机能异端主义",ev:"0",pt:"躯干、胳膊",cap:"2m+3s",ds:"有些黑客可能不太喜欢穿着紧身衣出门的那种羞耻感，所以他们多少会在外面套些东西。而这件设计大胆、棱角分明的尼龙冲锋衣就是为他们准备的。其位于胸口和肩膀上的挂章是一块可编程的屏幕，黑客可以尽情将他们的标志或者喜欢的图案映射在上面，走在街头那回头率可是十分惊人的。",feat:"服装风格+1",ra:"SR",pr:210,grp:"中产"},{n:"哥特魅影™吸血鬼卫衣",mf:"三露鸥",style:"机能异端主义",ev:"0",pt:"躯干、胳膊",cap:"2m",ds:"当下最潮的那些小伙子们最爱这件哥特风的战术卫衣了，它独特的翻领几乎比整个肩膀还大，加上那个神秘的兜帽，既十分霸气，又把神秘感拉满了。尽管穿着这玩意出门有被同龄人笑中二病的风险，但是，有哪个年轻人没有过中二时光的？",feat:"服饰风格+1",ra:"SR",pr:180,grp:"中产"},{n:"哥特魅影™狼人战术长裤",mf:"三露鸥",style:"机能异端主义",ev:"0",pt:"腿",cap:"2m+2s",ds:"这款带有铆钉的双层设计哥特风机能长裤在保证了舒适度的同时让你成为街头潮流的明星。它的拉链刻意设计成爪抓的狰狞模样，不仅可以快速拆卸裤腿的长度，也能用于更换裤子上的装饰品和口袋。是的，它官网上购买有一大堆附带的周边配件，但如果你全部购入的话，那总价都够再买三条了。",feat:"可以附加额外的口袋.最多添加2m/4s，一个s+20eb，一个m+50eb",ra:"SR",pr:150,grp:"中产"},{n:"狼月™战壕风衣",mf:"吉布森",style:"机能异端主义",ev:"0",pt:"躯干、胳膊",cap:"4M",ds:"你知道摩根黑手经常穿的那套行头是哪个牌子的吗？你知道现在街头佣兵最潮的衣服是哪件吗？你知道什么衣服穿出去给人一瞅就知道你不好惹吗？那这件高领肃杀的战壕风衣绝对是你的首选。这件风衣高度模块化，其内侧挂钩更是可以用来藏一整把截短霰弹枪（或者一把超重型手枪），当然，其实它和摩根黑手没什么关系，也没有防弹功能，只是故意设计成了相近的款式罢了。",feat:"内置一个超重型手枪挂钩 三个手榴弹挂钩",ra:"SR",pr:130,grp:"中产"},{n:"战术科技™模块夹克",mf:"军用科技",style:"机能异端主义",ev:"0",pt:"躯干、胳膊",cap:"2m+2s",ds:"它身上的拉链和扣子密密麻麻，而且随衣附赠的还有几个精致的小包和口袋，可以根据使用者的需求贴合、挂载在衣服上。它随时可以从一件外出的休闲服变成一件战术弹挂，只要使用者还记得那些附赠的小包被丢到哪里了就好。",feat:"可以附加额外的口袋.最多添加2m/4s，一个s+20eb，一个m+50eb",ra:"R",pr:200,grp:"中产"},{n:"战术科技™多功能都市战术裤",mf:"军用科技",style:"机能异端主义",ev:"0",pt:"腿",cap:"6s",ds:"为了“战术目的”的考虑，这件裤子从一开始只有军绿、黑和城市迷彩三种配色，上面别着密密麻麻的口袋和拉链，它还配备了战术卡扣作为腰带！你可以在里面塞满各式各样的小零食，确保你一天都不会饿。或者塞满弹匣和备用子弹，以确保下辈子都打不完。",feat:"可以附加额外的口袋.最多添加2m/4s，一个s+20eb，一个m+50eb",ra:"R",pr:150,grp:"中产"},{n:"匿名者@全息面具",mf:"泽塔科技",style:"机能异端主义",ev:"0",pt:"头",cap:"/",ds:"这枚面具使用了最前沿的表情识别AI技术，可以将任何角色或者用户自定义的投影覆盖在用户脸上。它和那些植入的面部投影装置没什么区别，最大的区别在于这东西非常容易坏（被命中一次头部即失效），而且会让使用者没法使用一些高级的头盔（无法和12sp以上的头盔兼容）",feat:"服饰风格+2",ra:"SR",pr:180,grp:"中产"},{n:"游击战争™低感态雨林迷彩服",mf:"吉布森",style:"机能异端主义",ev:"0",pt:"躯干、胳膊",cap:"2m+4s",ds:"令人回想起中美洲的雨林……但谁说混凝土丛林里不能打游击战争？这套主打功能性的迷彩服能让你像游击战士一样在丛林中神出鬼没，并从上面附加的无数口袋里随时掏出你的战术道具。它的肩膀上还有一个专为猎刀（中型及以下近战武器）准备的绑带，你可以准备一把匕首塞在那边，或者叼在嘴里，就像动作电影里的终极硬汉一样！",feat:"林地地形潜行+1，花费额外的50eb购买一个兼容通用插板的插口。",ra:"SR",pr:230,grp:"中产"},{n:"游击战争™混凝土丛林战士",mf:"吉布森",style:"机能异端主义",ev:"0",pt:"躯干、胳膊",cap:"2m+4s",ds:"虽然这种特制的都市迷彩仍然不如光学迷彩管用，但在现代混凝土丛林之中还是可以起到一定的隐蔽和模糊外形作用。有时候你只需要穿着这玩意往垃圾堆旁边一趴，那些来找你麻烦的帮派分子真的会从你的边上走过去。",feat:"城市地形潜行+1",ra:"SR",pr:250,grp:"中产"},{n:"游击战争™都市战术裤",mf:"吉布森",style:"机能异端主义",ev:"0",pt:"腿",cap:"4s",ds:"这件裤子非常耐操，无论是剧烈摩擦还是被尖锐物品勾挂，它都能保证绝对的坚韧。你可以穿着它天天在水泥地里打滚、滑铲或是在烂尾楼里跑酷，就算你人玩出事了，这条裤子说不定还能原封不动地作为遗产传给其他人。",feat:"城市地形潜行+1",ra:"SR",pr:150,grp:"中产"},{n:"游击战争™丛林突袭迷彩裤",mf:"吉布森",style:"机能异端主义",ev:"0",pt:"腿",cap:"2m",ds:"这种尼龙迷彩裤不怕脏，而且非常适合裹上泥浆和血迹。这不会让你看起来更脏，只会让你看起来更酷。它还附赠一套专业的防水军靴，可以和裤子连在一起，防止渡水的时候有泥沙和水渗进靴子里。",feat:"林地地形潜行+1",ra:"SR",pr:130,grp:"中产"},{n:"新浪潮 炫彩背心",mf:"三露鸥",style:"都市靓影",ev:"0",pt:"躯干",cap:"2S",ds:"自从可编程丝绸诞生以来，在衣服上显现动态图案就一直是属于富人的专利。但很快这项技术普及开来，并开始在更廉价的塑料上进行实验。最终的成果比丝绸闷热许多，也更加厚重，但好歹平民也可以利用这项技术尽情在自己身上显现动态图案了。",feat:"服饰风格+1",ra:"SR",pr:200,grp:"中产"},{n:"呼噜猫™塑料裁剪连体衣",mf:"三露鸥",style:"都市靓影",ev:"0",pt:"躯干",cap:"/",ds:"大胆、新潮、令人血脉喷张！这件形似高叉紧身连体泳装的衣服将胸口和肚脐附近的一大块布料都换成了塑料布，用以展示穿着者的火辣身材。虽然这件风格大胆的衣服看起来是为小妞们准备的，但实际上它也有男款。两者在基础的版式上没差多少，区别只在于男款的胯部空间会稍微大一些。",feat:"贿赂+1， 性张力专长额外加成+1",ra:"R",pr:100,grp:"中产"},{n:"呼噜猫™塑料热舞组合",mf:"三露鸥",style:"都市靓影",ev:"0",pt:"腿",cap:"1s",ds:"这套塑料布质感的短裙/短裤+运动吊带袜的组合让不少青年光看广告就血脉喷张。更出彩的是，它特别采用的塑料布可以随着光线变化变换不同的色彩，在夜店酒吧等场合穿着它绝对会让你成为舞池里的明星。对的，它也分男款和女款，但总的来说两者没什么差别。男款的使用者经常会抱怨它“勒得太紧了”。",feat:"贿赂+1， 性张力专长额外加成+1",ra:"R",pr:80,grp:"中产"},{n:"呼噜猫™高裁休闲装",mf:"三露鸥",style:"都市靓影",ev:"0",pt:"躯干、胳膊",cap:"2s",ds:"有时候你确实会怀疑这年头还有没有对未成年保护相关的法律，毕竟连这些有伤风化的衣服都能堂而皇之地登上各地的广告牌，简直是不可……但话又说回来了，看到街头的俊男靓女穿着这些刻意暴露肩部、大腿、胸口、腰线甚至是胯部，又配合身材曲线做了独特设计的衣装，确实是一道赏心悦目的风景……",feat:"贿赂+1， 性张力专长额外加成+1",ra:"R",pr:60,grp:"中产"},{n:"街头贵胄™仿制皮草",mf:"菲茨博",style:"都市靓影",ev:"0",pt:"躯干、胳膊",cap:"2s",ds:"夸张的深V大毛领，豹纹的、纯白的、骚紫色的仿制真皮，再加上喇叭袖口和夸张的袖扣，这时候你再抱上一把吉他，梳个飞机头，你就是上世纪那帮最骚气的摇滚明星！这件衣服没法水洗，如果你不想上面的仿制真皮过段时间就变得破破烂烂，那你最好还是勤加保养为妙。",feat:"服饰风格+2",ra:"SR",pr:300,grp:"中产"},{n:"街头贵胄™仿皮牛仔裤",mf:"菲茨博",style:"都市靓影",ev:"0",pt:"腿",cap:"2s",ds:"上世纪美国味的代表就是牛仔风，本世纪依然还是！带着马鬃的裤套牛仔裤永不过时，更何况它还用金色的丝线从上到下都刺了许多刺绣。即便你不穿那些花里胡哨的牛仔靴，它也在裤腿附带了一个帅气的马刺。谁说新世纪的街头不能有牛仔的？",feat:"服饰风格+2",ra:"SR",pr:200,grp:"中产"},{n:"街头贵胄™狂野绅士",mf:"菲茨博",style:"都市靓影",ev:"0",pt:"躯干胳膊or 腿",cap:"3s+2s",ds:"街头巷尾总有那么一群臭屁的人既想赶潮流，又想穿得更加体面优雅一点，还不能像是几百年前穿越来的古代人。那这套经过重新设计的、迎合了街头审美的西装礼服肯定最适合他们！它采用了粉紫、豹纹、珠光等高调的设计，并在腰部、膝盖、肩头等位置添加了适宜的剪裁，再加一根手杖，简直又帅又骚气，真不知道能迷死多少人！它成套贩卖，因此价格是购买覆盖全身的一整套的价格。",feat:"COOL+1",ra:"SR",pr:420,grp:"中产"},{n:"街头贵胄™后街淑女",mf:"菲茨博",style:"都市靓影",ev:"0",pt:"躯干胳膊or 腿",cap:"3s+2s",ds:"将上世纪的女士风衣、高叉铅笔裙和裤袜进行重新设计后，使它更适合街头，更符合新时代的审美。除了将材质转换成高反光色的尼龙布料之外，还用装饰性的添加了装饰性的披肩、金属挂饰和塑料布飘带。优雅成熟，前沿时尚，又不失美艳性感。它成套贩卖，因此价格是购买覆盖全身的一整套的价格。",feat:"COOL+1",ra:"SR",pr:420,grp:"中产"},{n:"铬金骑士™闪耀夹克",mf:"奇装",style:"都市靓影",ev:"0",pt:"躯干、胳膊",cap:"2m+2s",ds:"与其说是镀铬，不如说更像是镀锡。这套像是太空人一样闪闪发亮的摩托夹克适合在夜间与黑暗环境中使用，不仅可以耍帅，还可以反射远光，把那些乱开远光灯的混蛋闪的晕头转向。",feat:"潜行-2，全体目光向我看齐专长检定+1",ra:"R",pr:160,grp:"中产"},{n:"铬金骑士™闪耀喇叭裤",mf:"奇装",style:"都市靓影",ev:"0",pt:"腿",cap:"2s",ds:"这套长裤有点像上世纪摇滚明星穿的那种浮夸喇叭裤，但要更加闪闪发亮，别人想不注意到你都不行。如果你害怕晚上家门口路灯失修，一不小心被车撞死，那你就穿它出门。隔着50m开外都会有车注意到你的。",feat:"潜行-2，全体目光向我看齐专长检定+1",ra:"R",pr:130,grp:"中产"},{n:"剑与魔法™联动系列套装",mf:"奇装",style:"都市靓影",ev:"0",pt:"躯干胳膊or 腿",cap:"2m+2s",ds:"精灵战线OL的联动系列套装，将游戏里的多种不同热门幻化套装设计搬到现实，并进行了更适合现代出行的调整优化。为了照顾那些身材不好又没钱去做手术的顾客，他们还会特意为一些衣服调整尺寸、填充肌肉轮廓和腰肩比，让人人都有能力去在现实中还原他们的游戏形象。它成套贩卖，因此价格是购买覆盖全身的一整套的价格。",feat:"COOL+1",ra:"R",pr:400,grp:"中产"},{n:"忍者国度™跑酷连体服",mf:"菲茨博",style:"通用朋克",ev:"0",pt:"除头外全身",cap:"4m",ds:"这套帅气的，棱角分明的尼龙连体服在手腕和小腿处都做了收束性处理，且有一条从领口直下胯部的大拉链，可以用一分为二的方式进行快速穿脱。也可以通过解开它腰间的装饰性腰带来将上下两部分进行分离。这样就不用担心传统连体服要怎么去上厕所这样的严肃问题了。",feat:"运动+1",ra:"SR",pr:300,grp:"中产"},{n:"忍者国度™隼喙兜帽",mf:"菲茨博",style:"通用朋克",ev:"0",pt:"头",cap:"/",ds:"隼喙形制的兜帽无论是折叠在后方还是戴在头上都会给人带来一种十分酷炫的观感，但这东西真戴在头上的时候，总让人感觉有点看不太清东西。",feat:"服饰风格+1",ra:"SR",pr:50,grp:"中产"},{n:"大闹一通™朋克套装",mf:"菲茨博",style:"通用朋克",ev:"0",pt:"躯干、胳膊",cap:"2m",ds:"一开始这东西只是给“武侍”乐队推出的纪念款夹克和牛仔裤，后来一些别的摇滚乐队也逐渐在世界上崭露头角，菲茨博便将设计稍微改了改又拿出去卖，结果大受好评。现在，你认识的绝大多数乐队周边都有一件款式和这东西差不多的衣服，最多稍微改改几个细节。不管怎么说，大家都还觉得穿着这东西出门很“朋克”。它成套贩卖，因此价格是购买覆盖全身的一整套的价格。",feat:"服饰风格+1",ra:"R",pr:240,grp:"中产"},{n:"大闹一通™街头卫衣",mf:"菲茨博",style:"通用朋克",ev:"0",pt:"躯干、胳膊",cap:"2m",ds:"说唱明星喜欢它，街头的小孩也喜欢它，它和市面上几乎所有你所熟知的文化IP都有过联名，尽管款式上没有太大变化，但耐不住大家就好这一口不用插电就能在衣服上展示动态图案的技术。特别是看着你喜欢的IP在你的身上动起来，在同龄人面前这简直酷爆了。",feat:"服饰风格+1",ra:"R",pr:60,grp:"中产"},{n:"高楼跑客™双层运动裤",mf:"奇装",style:"通用朋克",ev:"0",pt:"腿",cap:"2s",ds:"专门为喜欢极限运动的青年们准备，使用先进的双层设计，外侧防水耐磨，内侧吸汗透气。同时还有一套连体短裤套在外部，用以遮盖尴尬部位。",feat:"/",ra:"R",pr:50,grp:"中产"},{n:"高楼跑客™全身连体服",mf:"奇装",style:"通用朋克",ev:"0",pt:"除头外全身",cap:"2m+2s",ds:"这套连体运动服将性感与实用合二为一，适合各种各样的运动场合，穿在身上感觉就像没穿衣服似的，留再多汗也会被快速蒸发。它同时还有和多家超级英雄漫画的联名款式，高度还原了那些紧身衣超级英雄的外观。这下那些义警不用再花费心思定制一套材质垃圾的破烂cos服去行侠仗义了。",feat:"运动+1",ra:"R",pr:200,grp:"中产"},{n:"嘻哈武士™",mf:"奇装",style:"通用朋克",ev:"0",pt:"躯干、胳膊",cap:"2m+2s",ds:"这套日裔街头混混最爱的大胆设计特意强调了使用者的健美身材，在防水露脐装之上是形似短款武士羽织的设计。下装是结合了一定现代设计的古日本武士袴裤，收束的裤腿更加方便运动，防水布料在沾上血之后也会很快滴落在地。它的不同款式主要包括了不同样式的东方花纹和配色，也有为炎热地区准备的短款。它成套贩卖，因此价格是购买覆盖全身的一整套的价格。",feat:"柔术+1",ra:"R",pr:350,grp:"中产"},{n:"都市领航者™自由卫衣",mf:"得体",style:"通用朋克",ev:"0",pt:"躯干胳膊or 腿",cap:"3m+4s",ds:"将实用和朋克相结合，这款剪裁大胆的卫衣成功解释了什么是“自由”。不，它的主体设计不采用拉链也不采用纽扣，而是采用磁吸扣的方式，将整件衣服以更前卫的块状设计拼在一起，而它的边缘设计，特别是在手臂的口袋和位于兜帽背部的松紧带，都使用了飘带设计，让使用者奔跑时，全身上下都能充满动感。",feat:"COOL+1",ra:"SR",pr:220,grp:"中产"},{n:"逐风骑士™",mf:"得体",style:"通用朋克",ev:"0",pt:"腿",cap:"2s",ds:"它身上的那些块状的设计物让他一眼望去像是某种特殊设计的战术护甲，实际上它们多半只有装饰作用，可以用来投射霓虹图案。除此之外，它的另一个特色便在于其用色的大胆。它完全舍弃了现代流行的黑白灰色，改用亮橙、鲜红、亮绿、湛蓝等饱和度更加鲜艳的色彩，并且支持用户自定义花纹和附带装饰。可以说，世界上很难找到两套完全一样的逐风骑士™。它成套贩卖，因此价格是购买覆盖全身的一整套的价格。",feat:"运动+1",ra:"SR",pr:340,grp:"中产"},{n:"都市领航者™运动忍者裤",mf:"得体",style:"通用朋克",ev:"0",pt:"腿",cap:"2m",ds:"战术忍者裤是时下的最新潮流，即便如此，也很少有其他设计师能做出都市领航者这么酷的忍者裤。它非常适合运动，高透气性设计让它在奔跑时虎虎生风，快速为腿部降温。同时深拉链口袋的设计也能将随身物品牢牢锁在身上，不会因为剧烈颠簸而飞出去。这使得它们非常适合在都市的建筑物顶端跑酷。",feat:"服饰风格+1",ra:"R",pr:100,grp:"中产"},{n:"壮志凌云™ 飞行员夹克",mf:"奥林匹亚",style:"实用主义",ev:"0",pt:"躯干、胳膊",cap:"2m",ds:"时尚有时候是新潮，有时候也是复古。这套由芳纶纤维加人造皮革纺织的飞行员夹克就很好诠释了这一点。它既保暖又结实，集绝缘、保暖、防风、耐磨等优点于一身，号称穿50年都不会坏。同时附件还有自定义的魔术贴徽章，让你穿出属于自己的范。",feat:"自带永不损坏的4sp， 服饰风格+1",ra:"SR",pr:500,grp:"中产"},{n:"壮志凌云™ 复古牛仔裤",mf:"奥林匹亚",style:"实用主义",ev:"0",pt:"腿",cap:"2s",ds:"牛仔裤一直是美国鼎盛时期的象征物，直到解体后的今日，它依然在街头巷尾流行。它的版式和材质和一百年前没有多大差别，即便如此，人们在这个时代依旧热爱通它。而它与皮夹克的搭配更是经典中的经典。",feat:"自带永不损坏的4sp",ra:"SR",pr:200,grp:"中产"},{n:"中端定制西装",mf:"奇装",style:"实用主义",ev:"0",pt:"躯干胳膊or 腿",cap:"4S",ds:"一些公司的低层管理人员订不起一套像样的王朝™西装，于是就会转而定制这一款合身紧凑、优雅美观的定制西服。如果他们稍微再有点小钱的话，一般会给自己买一套防弹西装。它成套贩卖，因此价格是购买覆盖全身的一整套的价格。",feat:"服饰风格+2",ra:"R",pr:500,grp:"中产"},{n:"得体™紧凑西装",mf:"得体",style:"实用主义",ev:"0",pt:"躯干胳膊or 腿",cap:"3s",ds:"作为全世界最畅销的服装公司的招牌产品，得体的这一套西装便宜实惠，经久耐用，就是穿久了不太舒服。无论是夏天还是冬天，穿着它都不会感觉膈应。全世界的各大公司和工薪族都非常喜欢它。就是它组成了世界各处那灰茫茫的西装海洋。它成套贩卖，因此价格是购买覆盖全身的一整套的价格。",feat:"/",ra:"N",pr:80,grp:"中产"},{n:"得体™日常休闲装",mf:"得体",style:"实用主义",ev:"0",pt:"各部位都有",cap:"2m",ds:"这一系列的休闲装款式多样，色彩艳丽，是都市居民日常穿着最具性价比的选择。它涵盖了几乎你能叫得上名字的每一种类型，还经常和各大IP进行联名，推出相应的联动时装。当然，这一部分的性价比就没那么高了。由于它的款式多样，购买者在选定某一类型时，应投掷2d6，将结果乘以10，就是最终价格。",feat:"/",ra:"N",pr:"20~120",grp:"中产"},{n:"北极星™极地冲锋衣",mf:"吉布森",style:"实用主义",ev:"0",pt:"躯干、胳膊",cap:"2m+2s",ds:"非常舒适，又非常有形的现代冬季冲锋衣，在世界各地销量火热。它内部有一块侦测变温的感应芯片，以及可变的气孔和半导体设计。它会自动感应周围的温度，进行降温或者升温。虽然概念很酷，但维护它是一件技术活。它不能水洗，还需要频繁充电。但如果你只是单纯考虑保温功能，那它即便在完全没电的情况下，也能当作正常棉袄穿。",feat:"使用者可以在零下20°C以上的气温中正常活动",ra:"R",pr:180,grp:"中产"},{n:"西伯利亚军用棉大衣",mf:"苏石化",style:"实用主义",ev:"1",pt:"除头外全身",cap:"2L",ds:"它很暖和，但也很笨重。是西伯利亚居民人手一套的御冬大衣，用料扎实，且十分耐穿。据说苏联人家里的这种大衣很多是他们爷爷辈传下来的。冬天的莫斯科到处都是穿着这套衣服在巡逻的苏联大兵。",feat:"使用者可以在零下20°C以上的气温中正常活动",ra:"N",pr:40,grp:"中产"},{n:"蓝领连体服",mf:"得体",style:"实用主义",ev:"0",pt:"除头外全身",cap:"1L+2m",ds:"在各大工厂和工地常见的各式连体服，耐用性和成本是它们最大的考量。根据厂商的需要有不同的颜色和花纹，或是荧光色设计。它非常容易在市场上订购到，出于成本考虑，大部分公司用的都是同一款。",feat:"/",ra:"N",pr:30,grp:"中产"},{n:"高性能聚合防护风衣",mf:"IEC",style:"实用主义",ev:"1",pt:"除头外全身",cap:"2m+4s",ds:"作为拾荒者和一些特殊工种人员所穿戴的特种服装，它几乎什么都防。绝缘、防水、防酸，甚至一定程度上可以抵御辐射。可它穿在身上很沉也很闷，在热播剧集《废都历险记》播出之前，街头上根本没人会传这玩意出门。但大家看见剧集主人公穿着这件帅气风衣上刀山下火海，有多种多样的奇特功能之后，它几乎一度被卖到断货。",feat:"对抗辐射的检定+2，X光无法穿透该衣服的材质。",ra:"R",pr:400,grp:"中产"},{n:"巴拉克拉瓦面罩",mf:"苏石化",style:"实用主义",ev:"0",pt:"头",cap:"/",ds:"经典的巴拉克瓦防寒面罩，冬天戴着十分保暖，但你最好别戴着这玩意去银行。",feat:"外人无法辨认你的容貌",ra:"N",pr:5,grp:"中产"},{n:"工程荧光背心",mf:"IEC",style:"实用主义",ev:"0",pt:"躯干",cap:"2m",ds:"工地里常见的荧光背心，在夜里非常显眼。除此之外没有什么特别的功能。",feat:"潜行-3",ra:"N",pr:10,grp:"中产"},{n:"生存者杂志推荐 组装大衣",mf:"无",style:"熵增主义",ev:"1",pt:"除头外全身",cap:"2L+2m",ds:"如果你也想给自己搞一套机能异端主义的帅气大衣，但你正好手头拮据，你会怎么做？答案很简单：你自己去垃圾场拼一套！用那些没人要的便宜合成纤维、塑料袋、金属板来自己定义自己的时尚！生存者杂志官方甚至就亲切地教你怎么去做这样的一套大衣。据说这是来自荷兰的时尚大师亲自设计的呢！",feat:"可以用EV额外+1的代价 获取10SP，服饰风格-1",ra:"N",pr:10,grp:"贫穷"},{n:"废土客时尚 打印衣装",mf:"无",style:"熵增主义",ev:"0",pt:"躯干胳膊or 腿",cap:"4s",ds:"在荒原中长途旅行的游民经常会面对自己的衣服在各种恶劣环境下磨损的问题。于是他们都会自备一台拆线机和服装打印机，而这种衣物就是他们智慧的结晶。他们会将各种搜刮来的破旧衣物洗净、拆线或是分解，然后再扔进打印机里再组装。像这样的衣服没什么独特的风格，且面料混杂，穿着可能不会太舒服。但你可以用它征服荒野。对了，如果你不是游民，而选择去游民手里买，那价格很有可能会翻倍算。它成套贩卖，因此价格是购买覆盖全身的一整套的价格。",feat:"/",ra:"N",pr:18,grp:"贫穷"},{n:"废土客时尚 耐操衣装",mf:"无",style:"熵增主义",ev:"1",pt:"躯干胳膊or 腿",cap:"2m",ds:"这种衣服手撕不烂刀砍不坏，就是穿着膈应，它多半是用麻袋和垃圾塑料纤维编织成的衣服，然后根据使用者的想法随便弄点什么上去，就当是装饰品。真要说的话，游民们一般也不穿这东西，但会把自己精心装饰的这种衣服挂在墙上，或者在一些恶劣天气的时候穿在身上，它们抵抗风沙可是一顶一的好。它成套贩卖，因此价格是购买覆盖全身的一整套的价格。",feat:"COOL-1",ra:"N",pr:20,grp:"贫穷"},{n:"OTAKU™一次性居家衣物",mf:"OTAKU",style:"熵增主义",ev:"0",pt:"躯干或腿部",cap:"/",ds:"这套衣服几乎在全世界任何平价服装店里都有售卖，有背心、T恤、短裤和内裤的款式，没有任何花里胡哨的花纹，也不存在黑白灰以外的第四种颜色。它不保暖也极度不耐穿，甚至被丢到洗衣机里洗一次就会起球，稍微勾挂一下就会破损。只有最绝望的人才会穿着它上街。",feat:"外穿时服饰风格-3，COOL-1",ra:"N",pr:1,grp:"贫穷"},{n:"OTAKU™环保打印衣装",mf:"OTAKU",style:"熵增主义",ev:"0",pt:"躯干或腿部",cap:"2s",ds:"这年头以环保名义产出的货色基本上全是垃圾，但好在这套穿起来就像报纸的衣服确实勉强可以拉出去见人。相比OTAKU的另一件产品，它好歹多了几套新的款式。但由于他们使用的打印材料过于劣质，这些衣服的保质期往往不太长久，而且极度不透气，冬天穿着还好，夏天可就要把人闷死了。",feat:"外穿时服饰风格-1，COOL-1",ra:"N",pr:5,grp:"贫穷"},{n:"乱杀™血腥勇士",mf:"R3VIVE",style:"帮派色号",ev:"0",pt:"躯干胳膊or 腿",cap:"1m+2s",ds:"这种服饰风格不知道为什么特别受新美国荒野那些刀锋掠夺者的喜爱，可能是这系列的衣服上真的有从垃圾里回收的金属刀片、尖刺和铁丝网，不仅锈迹斑斑，上面还在滴着血!当然，由于这东西用的是真货，你难免会不小心碰到……除了这点之外，它的其他部分就是一些回收的廉价人造皮革，不耐穿，也有些闷热。它成套贩卖，因此价格是购买覆盖全身的一整套的价格。",feat:"任意行动大失败时，减少使用者1d4生命",ra:"N",pr:22,grp:"贫穷"},{n:"乱杀™街头恶犬",mf:"R3VIVE",style:"帮派色号",ev:"0",pt:"躯干或腿部",cap:"2s+1m",ds:"这玩意看起来破破烂烂的，但谁说破破烂烂的不能是一种风格？2039年的米兰时装周可就是以“街头”为主题的！这个系列包含一套破布上衣和破洞牛仔裤，以及烂布条露脐卫衣和T恤。是的，它们都偷工减料，但至少价格上也没刁难你，你只需要预算在20eb以内，就可以获得一整套上过T台的酷炫衣装了！当然，你的身材和气质最好能够撑起它，不然看起来确实很像乞丐。",feat:"若COOL小于6， 则服饰风格-2",ra:"N",pr:8,grp:"贫穷"},{n:"乱杀™西海岸战争系列",mf:"R3VIVE",style:"帮派色号",ev:"0",pt:"躯干或腿部",cap:"2m",ds:"90年代西海岸帮派曾经红极一时的超长T恤以及松垮牛仔裤，用廉价的合成棉纺织而成，上面印着各种血腥暴力的图案。这东西看着唬人，穿着实际上并没有那么便利，特别是帮派分子们要从自己的腰间拔枪，还得先把这够到膝盖的超长T恤拉开才行。尽管问题重重，可西海岸的gangsta们还是没法轻易放弃自己的style。",feat:"先攻-1",ra:"N",pr:10,grp:"贫穷"},{n:"OTAKU™鬼武士羽织",mf:"OTAKU",style:"帮派色号",ev:"0",pt:"躯干",cap:"2m",ds:"这套由廉价化合纤维做成的羽织常见于日裔帮派成员的身上，也有裁短的“机能风”款式。上面通常刺绣着般若、赤鬼等日本传说妖怪的图案，穿在合适的人身上十分威风，但过于瘦弱的体型可能会让穿着者看起来相当滑稽可笑。好在这东西非常便宜，高中生用自己的零花钱就能随便给自己弄一套。",feat:"/",ra:"N",pr:7,grp:"贫穷"}],drones:[{n:"萨瓦纳蜂",mf:"吉拉法",size:"微型",mode:"飞行",ra:"SR",wpn:"无",endur:"4h",auto:"N",hp:"5/0",spd:"6",top:"20km/h",ds:"吉拉法在微型无人机领域的有力仿生学竞品，可以渗透哪怕只有一指宽的孔洞，并用其搭载的针孔摄像头和录音机记录情报。在其完全静止的情况下，可以续航长达三天之久。但若要连续飞行，最多只能飞行八小时。潜行技能11，闪避16，被入侵时相当于智力2，有效信号半径500m",pr:1e3,tier:"高级",grp:""},{n:"百足",mf:"荒坂",size:"微型",mode:"攀爬",ra:"SSR",wpn:"无",endur:"6h",auto:"Y",hp:"6/0",spd:"4",top:"5km/h",ds:"荒坂搭载了纳米AI芯片的微型暗杀机器人，荒坂情报部专用，只有少数出口。其最大特点是可切换自动和手动，它的内置AI可以理解人的基本命令，并自动计算最优路径。使用这种无人机时，不需要占用动作。它会钻入人的五官，并对体内的器官执行破坏行动。一旦它成功进入体内，它每回合会自动造成一次严重伤势，身体的严重伤势固定为体内异物，头部的严重伤势则随机投掷。积累三个由它造成的严重伤势后，目标会直接死亡。潜行技能10，闪避17，被入侵时相当于智力6，有效信号半径100m。",pr:2e3,tier:"昂贵",grp:""},{n:"蜂鸟",mf:"EBM",size:"微型",mode:"飞行",ra:"SSR",wpn:"无",endur:"10h",auto:"N",hp:"3/0",spd:"7",top:"60km/h",ds:"EBM专门为黑客设计的电子战用微型无人机。其上除了搭载可以感测环境的复眼型针孔摄像头和录音设备外，还额外搭载了一块昂贵的电子战纳米芯片。其可以屏蔽半径两米内的无线信号，也能停在敌对黑客身上，使其一切网络行动归零。若使用者是黑客，还能用其接入网络设施。它的续航时间24小时，自带光学迷彩，潜行技能17，闪避19，被入侵时相当于智力4，有效信号半径800m。",pr:5e3,tier:"极贵",grp:""},{n:"萨瓦纳雀",mf:"吉拉法",size:"小型",mode:"飞行",ra:"N",wpn:"无",endur:"5h",auto:"N",hp:"7/0",spd:"8/13",top:"100km/h",ds:"常见的吉拉法民用仿生无人机，通常是那些无人机摄像新手的玩具。技术乏善可陈，材料也是最为廉价的。只能搭载摄像头和录音设备，潜行技能5，闪避10，被入侵时相当于智力2，续航时间5小时。信号半径1km。",pr:70,tier:"平价",grp:""},{n:"SDF-2 “哨兵”",mf:"军用科技",size:"小型",mode:"飞行",ra:"N",wpn:"无",endur:"6h",auto:"N",hp:"8/4",spd:"11",top:"150km/h",ds:"世界各地雇佣兵组织和军队常用的前线侦察无人机，也是军用科技在无人机领域的拳头产品。不能搭载武装，自带高清望远摄像头（1km可视距离）和高解析度录音设备。续航时间6小时，潜行技能10，闪避14，有效信号半径5km。加价200购买军用信号天线，被入侵时相当于智力2，可以将信号半径提升至20km。",pr:230,tier:"平价",grp:""},{n:"天狗",mf:"荒坂",size:"小型",mode:"飞行",ra:"R",wpn:"冲锋枪",endur:"6h",auto:"Y",hp:"9/10",spd:"10",top:"130km/h",ds:"荒坂蜂群无人机部队的常见款式之一，偶尔也用来在空中反制其他无人机。作为主战机型过于脆弱，因此常常以量取胜。其基础款搭载了一门“WSA”型自动手枪，备弹50发。也可以加价500eb更换为一挺“座敷童子”冲锋枪，载弹量翻倍。潜行技能5，闪避10，射击技能12，有效信号半径10km。被入侵时相当于智力4，加价100可以搭载基础自律AI，使指挥它行动的时候不需要占用动作。",pr:800,tier:"值钱",grp:""},{n:"凯蒂",mf:"吉拉法",size:"小型",mode:"步行",ra:"R",wpn:"无",endur:"8h",auto:"Y",hp:"12/3",spd:"6",top:"40km/h",ds:"模仿宠物猫制作的仿生机器人，内部也搭载了仿生AI模拟家猫的行动。相比原生态的家猫要更加亲人，在富人的圈子里很受欢迎。潜行技能8，闪避10。加价100可以额外加装仿生毛发。被入侵时相当于智力5，通常不贩售可以让人操作的天线版本。而该版本的有效信号半径为1km。",pr:600,tier:"值钱",grp:""},{n:"科马雷“蚊”式",mf:"吉拉法",size:"小型",mode:"飞行",ra:"R",wpn:"手枪",endur:"4h",auto:"Y",hp:"14/0",spd:"6/10",top:"50km/h",ds:"常见于小型企业用于内部防御的蜂群无人机。尽管单只的战斗力十分脆弱，但是只要成群结队，即便是全副武装的犯罪分子也可以轻松制服。它搭载了一门定制的9mm手枪（同康陶28式），有20发弹药。它有基础款的自律芯片，却只能做到简单的敌我识别和分辨指令。除了手枪外，它还搭载了一根针状的撞角，可以在十米外用自杀式的方式撞击对手，视作进行了一次ROF1，伤害8D6的全威力攻击，并在命中后自毁。若攻击未命中还可保持存活。它的潜行技能5，闪避10，射击技能10，特殊撞击技能14，由于它的体型较小，命中它的难度额外+2。被入侵时相当于智力4，有效信号半径3km。",pr:300,tier:"平价",grp:""},{n:"JW-908“小帮手”",mf:"康陶",size:"小型",mode:"步行",ra:"R",wpn:"无",endur:"2h",auto:"Y",hp:"10/0",spd:"2",top:"5km/h",ds:"家务的好帮手，人民的好朋友。在城市中产阶级家中常见的贴地型家务机器人，只能做一些基础的家务工作。比如扫地、拖地、清理灰尘。对了，它不会上楼梯，就连一个随便跨过去的门槛都会挡住它。这导致它基本上只适合城市的平面公寓楼，不适合那些有高低差的大宅。它的自律能力仅限于理解使用者要它去哪儿，像它这样的存在也不适合搭载任何武装。它还会在黑夜环境下亮起灯，以免被人不小心踩到，这意味着……总之它除了扫地以外，你不能期待它的任何功能。它被入侵时相当于智力1。",pr:120,tier:"平价",grp:""},{n:"轻骑兵-3M",mf:"康陶",size:"小型",mode:"飞行",ra:"SR",wpn:"炸药",endur:"2h",auto:"N",hp:"8/0",spd:"6",top:"60km/h",ds:"这东西的民用款（稀有度N，价格200eb，载重减半）只是一件搭载了简陋摄像头，引擎便宜、机动差劲的入门款无人机罢了。但是这一款3M的军用改进型则成为了士兵们巷战的最好帮手。它可以搭载1KG炸药或者两枚防御型手榴弹进行自杀式袭击，一架就能确保一个小房间内没有任何活物。它身上的炸药可以通过撞击点燃引信或者让使用者手动触发，其标准配置搭载了一枚1KG的C-7炸药，可以对半径10m的范围造成7d12无视所有护甲的重反器材伤害，且对载具、掩体、墙面等无生命目标伤害翻倍。它不能搭载武装，但可以花费额外的100eb搭载最简单的自律芯片（即只能理解飞行方向，而不能理解其他如开火等复杂指令）。由于它的体型较小，命中它的难度额外+2。它的潜行技能5，闪避10，被入侵时相当于智力2.",pr:750,tier:"值钱",grp:""},{n:"Einsiedlerkrebs™",mf:"IEC",size:"小型",mode:"步行",ra:"SR",wpn:"无",endur:"6h",auto:"Y",hp:"8/4",spd:"5",top:"10km/h",ds:"一款介于地雷和自律机器人之间的战斗机器人，它安装了三对蛛行足，可以在任何表面上进行爬行。并且有一台超清潜望式火控，可以躲在灌木或者树上进行侦察。它的最大特色在于其背部安置了一枚IEC微型火箭（详见武器表，只有一发），可以在火控装置用一回合锁定目标后直接发射，并一击脱离，或是干脆舍弃在原地。它是极其恐怖的伏击杀手。可以用自律的方式索敌或是手动操作，为它装填需要花费一个动作。它的战斗技能10。潜行技能12，闪避5。被入侵时相当于智力4.",pr:1200,tier:"高级",grp:""},{n:"杀人蜂",mf:"IEC",size:"小型",mode:"飞行",ra:"SR",wpn:"毒针枪",endur:"6h",auto:"N",hp:"8/4",spd:"8",top:"62km/h",ds:"IEC制造的暗杀型无人机，搭载了一挺午夜军工“缄默”毒针手枪和光学迷彩装置，可以在20m内精确命中敌方目标。其搭载了先进的纳米AI芯片，可以理解你的命令。使用它时不占用动作。其战斗技能15。潜行技能7，闪避14。开启光学迷彩装置后潜行技能翻倍，续航时间减半。由于它的体型较小，命中它的难度额外+2。被入侵时相当于智力5，",pr:3300,tier:"昂贵",grp:""},{n:"PED-72 “万金油”",mf:"吉拉法",size:"小型",mode:"飞行",ra:"SR",wpn:"无",endur:"6h",auto:"Y",hp:"8/10",spd:"6",top:"50km/h",ds:"说来奇怪，这种造型小巧的悬浮无人机一开始本来是为了医学、工程等用途而开发的，但在近些年里却成为了人们最爱的电子宠物之一。它造型小巧，重量轻盈，通常搭载了一枚高清摄像头和HIFI音频装置，可以作为实用的小型侦察无人机使用。但它最大的特点在于其下挂的两只机械臂，可以用来持用不超过20kg的重物。机械臂上灵活的机械手指可以操作工具，甚至可以扣动扳机，但最好还是别给它后座力太大的东西，会把它崩飞的。它可以随意更换其下挂的装备，并可以像人一样捡起装备。它的体格相当于3，不能使用超重型手枪。其自带的自律芯片里有一个掌上代理水平的AI，可以和人正常交流，并理解人的大部分命令。战斗技能10。潜行技能10，闪避10。由于它的体型较小，命中它的难度额外+2。被入侵时相当于智力4.",pr:1700,tier:"高级",grp:""},{n:"爬蛛",mf:"IEC",size:"小型",mode:"步行",ra:"SR",wpn:"无",endur:"5h",auto:"Y",hp:"15/8",spd:"4",top:"18km/h",ds:"小巧灵活的爬行无人机，可以在垂直的表面上行走。它通常是黑客家里最可爱的电子宠物，可以帮主人做杯垫，用它小小的机械爪抓来画笔、插头之类的东西……不要考虑在这小家伙身上安装武器，哪怕是手枪，它也无法承受其带来的后座力。但它那标志性的8目摄像机可不是摆设，这让它拥有夜视（1km）、望远（4km）、热成像（1km）等特殊功能，而且它小巧的哑光外壳也让其在夜间十分不容易被发现。其战斗技能8，潜行技能12。被入侵时相当于智力6，",pr:4e3,tier:"昂贵",grp:""},{n:"萨瓦纳犬",mf:"吉拉法",size:"中型",mode:"步行",ra:"R",wpn:"无",endur:"12h",auto:"Y",hp:"21/5",spd:"7",top:"30km/h",ds:"模仿狗制作的仿生机器人，相比家猫款式，追加了模拟嗅觉的功能。在世界各地的警队中十分常见。可以切换自律和手动两种操作方式，潜行技能8，闪避11，追踪10。有效信号半径为1km。加价100可以额外加装仿生毛发。被入侵时相当于智力6，",pr:800,tier:"值钱",grp:""},{n:"萨瓦纳鹰",mf:"吉拉法",size:"中型",mode:"飞行",ra:"R",wpn:"冲锋枪",endur:"24h",auto:"N",hp:"18/4",spd:"10",top:"80km/h",ds:"吉拉法的主力产品之一，一种形似鹰的仿生无人机，适合执行多种不同任务。但主要提供给其他公司和治安部队进行巡逻和监视。作为当前无人机型中最万金油的款式，它本身的仿生学外形自带高清远距热成像（2km距离）和声音远距采样设备（100m），额外的槽位可以用来安装一把冲锋枪，也可以用来投掷手榴弹。它包括投掷在内的射击技能是14，潜行技能5，闪避14，信号半径10km。由于它的体型较小，命中它的难度额外+2。被入侵时相当于智力4.",pr:700,tier:"值钱",grp:""},{n:"卫士",mf:"康陶",size:"中型",mode:"步行",ra:"R",wpn:"电击枪",endur:"8h",auto:"Y",hp:"15/10",spd:"7",top:"40km/h",ds:"一款球形安保机器人，分为致命/非致命武装两种型号。可以在全地形机动的同时，代替警方进行执法抓捕行动。在特殊情况下，也可以使用高出力模式直接击毙嫌疑人。它非致命配置下弹药无限，使用警用泰瑟枪数据。加价500可以使用致命武装配置。其会使用两把突击-7改装的冲锋枪进行突破，并在战斗过程中一边保持机动，一边双持射击。致命配置的携弹量80发。它的射击技能13，闪避10，信号半径500m。被入侵时相当于智力5.",pr:1100,tier:"高级",grp:""},{n:"花园侏儒",mf:"IEC",size:"中型",mode:"步行",ra:"R",wpn:"步兵武器",endur:"5h",auto:"Y",hp:"20/4",spd:"/",top:"/",ds:"与其说是一款无人机，不如说是一款可以随时布置的折叠步兵炮台。平时能折叠到一个普通背包的状态，并可以用一个动作进行部署。它以一个不可移动的液压支架作为自己的底部支撑，可以通过更换支撑架的方式布置在任何表面上。有一个专门定制的卡槽位于其顶部，只要按照说明书的步骤来，它就可以安装除了重武器以外的任何步兵武器。然而美中不足的是，其使用的摄像头只是掌上代理级的普通摄像头，只能用以识别200m内的人形目标。对于军事的用途来说有些鸡肋，但对于建筑的安保来说刚刚好，就连一些中产阶级都会采购它来防贼。一些安保公司的保镖也会携带它出门，并在应急情况用来保护自己的雇主。它包括投掷在内的射击技能是12，觉察10，无法进行闪避。花费额外的400eb可以升级高级战斗芯片，把战斗技能提升至15。被入侵时相当于智力4。",pr:800,tier:"值钱",grp:""},{n:"海鸥",mf:"康陶",size:"中型",mode:"飞行",ra:"R",wpn:"无",endur:"4h",auto:"N",hp:"10/0",spd:"6",top:"150km/h",ds:"市面上最受欢迎的民用无人机款式之一，这款高度模块化的无人机可以通过改装适用各种常见场合，无论是进行商业拍摄任务还是绑上炸弹进行自杀式袭击，它都完全可以胜任，常有些客户抱怨它不够耐用，它的外壳过于脆弱——但看在它价格的份上，你又有什么可抱怨的呢？它自带民用级的摄像头（可以观察500m内的目标）。它的射击技能10，闪避10，潜行10，信号半径1km。加价200eb可以购买可编程的自律AI，也可以加价50eb购买加强装甲外壳（10sp,HP+5)由于它的体型较小，命中它的难度额外+2。被入侵时相当于智力2。",pr:230,tier:"平价",grp:""},{n:"萨瓦纳龟",mf:"吉拉法",size:"中型",mode:"步行",ra:"R",wpn:"无",endur:"2h",auto:"Y",hp:"20/2",spd:"4",top:"8km/h",ds:"轮足一体式自动家务机器人，大约高度在成年人的膝盖到大腿之间，内部有一个类似瑞士军刀的收容舱用以收纳各种家务设备，以对房间进行清扫、打理。它的延长臂和潜望镜最高可以伸到2m的高度，用以处理一些例如洗衣服和做饭之类的复杂工作。它的最大特色在于内部植入了一台智能代理作为计算核心，这让它拥有一个讨喜的服务型AI人格，不仅可以完全理解使用者的指令，甚至在一定程度上会陪主人进行角色扮……听着，我知道你在想什么，但这东西就是一台乌龟形状的机器人，而且有人已经因为这事被送到医院去了，所以想都不要想…求你了，好吗？它没有战斗技能，闪避6，觉察10，体格5，被入侵时相当于智力6。",pr:530,tier:"值钱",grp:""},{n:"Bibliothekar™",mf:"IEC",size:"中型",mode:"飞行",ra:"R",wpn:"无",endur:"4h",auto:"Y",hp:"13/6",spd:"5",top:"10km/h",ds:"会飞的旋翼式家务机器人，自带静音旋翼，有半个人大小。下方有着4条带着抓手的多功能机械臂，用以清理打扫房间和墙壁，还能理解一些复杂命令，比如帮助屋主整理书架，或是炒一盘菜，乃至照顾孩子。它通常存在于富裕中产家庭的家里和那些小康家庭的家里，偶尔也会在一些餐馆看见，用以取代服务员。由于民用机器人的限制和法律规定，它不被允许使用暴力和武器，其系统也不被允许它通过外部控制进行操作。它没有战斗技能，闪避6，觉察10，体格5，被入侵时相当于智力6。",pr:720,tier:"值钱",grp:""},{n:"狼群",mf:"吉拉法",size:"中型",mode:"步行",ra:"SR",wpn:"突击步枪",endur:"6h",auto:"Y",hp:"20/7",spd:"8",top:"47km/h",ds:"军用仿生侦察机器人，在巷战领域和野战领域皆有属于自己的定位。其坚实稳固的四足平台可以搭载一把突击步枪，也可以搭载一挺一次性火箭筒/反坦克导弹进行伏击。作为一个小型可编程自律战斗机器人，它以物美价廉的优势大量部署在各大战场和公司安保系统里。但它的反电子战性能较为脆弱，防弹级聚合物外壳也仅能对抗常规手枪子弹。其售价只有本体，不包含外挂的武器系统，因此模块化性能较高。它的射击技能11，闪避8，信号半径1km。被入侵时相当于智力6。",pr:1e3,tier:"高级",grp:""},{n:"KSM-01 飞鱼",mf:"IEC",size:"中型",mode:"飞行/游泳",ra:"SR",wpn:"泰瑟枪",endur:"6h",auto:"N",hp:"15/15",spd:"5/10 7",top:"80km/h 49km/h",ds:"IEC的许多重要设施都处于海滨，为了保护这些设施的安全，IEC研发了Kampfschwimmer系列无人机，它最大的特点是可以水空两栖，无论是下水道的污水河还是含盐量高的大海，它都可以胜任下方的巡逻任务。它搭载了一枚轻型声纳装置、一把泰瑟枪（同枪械表的泰瑟枪）和掌上代理级的防水摄像头，还额外整合了热成像装置，可以感应面前500m范围的活物，IECn内部使用的军用级观测系统可以让它的感应范围提升至5km。加价500eb可以为它安装自律芯片。它的射击技能11，闪避8，信号半径1km。由于它的体型较小，命中它的难度额外+2。被入侵时相当于智力6。",pr:800,tier:"值钱",grp:""},{n:"猞猁",mf:"IEC",size:"中型",mode:"步行",ra:"SR",wpn:"机枪",endur:"6h",auto:"N",hp:"22/18",spd:"8",top:"40km/h",ds:"在城市房间等狭窄过道里使用的四轮足式底盘安保无人机。其顶部的武器平台可以搭载任意步兵武器（包括机枪）。IEC的标准配置是让它携带一把MGK-5作为扫荡火力，但警方通常会给它安装一门榴弹机枪以进行多种任务。相比那些正经的无人装甲车，它的体积小，大约才占半人高度，因此可承载的武装也有限。但相比那些重型无人装甲车，它更灵活也更便宜，还可以靠它自由的四轮足爬上楼梯。最重要的是，它性价比足够高。有些丧心病狂的客户甚至为它加装了加特林……加价500可以为它安装自律芯片。它的射击技能13，闪避6，信号半径1km。被入侵时相当于智力6。",pr:4e3,tier:"昂贵",grp:""},{n:"ADF-4 “义勇军”",mf:"军用科技",size:"中型",mode:"飞行",ra:"SR",wpn:"狙击枪",endur:"5h",auto:"N",hp:"10/5",spd:"6/14",top:"100km/h",ds:"军用科技在2040年推出的狙击型暗杀无人机，为一些佣兵的特种任务专门设计。配备了专用的双稳定装置和一支专门设计过的狙击步枪（数据等同于LR-2020），备弹5发。其自带的一枚32x的高清摄像头，以及一个光学迷彩立场可以使它肉眼隐形，并在数百米开外狙击敌方。由于和自身系统联动，该武器不可拆卸不可更换。加价200可以获得带有自律芯片的版本。它的射击技能13，潜行技能7，闪避15，信号半径17km。由于它的体型较小，命中它的难度额外+2。被入侵时相当于智力4。",pr:2e3,tier:"昂贵",grp:""},{n:"突击蜂",mf:"IEC",size:"中型",mode:"飞行",ra:"SR",wpn:"冲锋枪",endur:"4h",auto:"Y",hp:"17/6",spd:"6/17",top:"130km/h",ds:"IEC在公司战争中使用过的蜂群突击无人机，在经过20年的改进后，形成了如今的版本。搭载了一挺专门设计的双联针刺冲锋枪（相当于PDW-ZERO数据），载弹量100发。IEC的自用版本使用专门设计的高穿甲针刺弹（相当于突击步枪穿甲等级），通常不对外出口。出口版本只使用普通弹药。由于和自身系统联动，该武器不可拆卸不可更换。它的射击技能14，潜行技能4，闪避12，信号半径10km。由于它的体型较小，命中它的难度额外+2。被入侵时相当于智力4，",pr:1200,tier:"高级",grp:""},{n:"投弹手",mf:"IEC",size:"中型",mode:"飞行",ra:"SR",wpn:"手榴弹",endur:"8h",auto:"N",hp:"20/0",spd:"6/14",top:"100km/h",ds:"第四次公司战争中大放异彩的投弹无人机，IEC的标配是使用他们自己开发的制导手榴弹，但很多第三世界的客户喜欢用它们投掷迫击炮弹。它投掷的技能系数是+13，拥有四个可以容纳手榴弹的挂钩（也可以用来挂上一枚60mm迫击炮弹），潜行技能5，闪避14，有效信号半径为17km。由于它的体型较小，命中它的难度额外+2。被入侵时相当于智力6。",pr:1400,tier:"高级",grp:""},{n:"忍犬",mf:"荒坂",size:"中型",mode:"步行",ra:"SR",wpn:"冲锋枪",endur:"10h",auto:"Y",hp:"20/7",spd:"8",top:"57km/h",ds:"荒坂出产的犬型侦察机器人，能帮助携带重物，同时自带10km可观测距离的超高清望远镜，以便观察远方的目标。它的摄像头旁还带一个可以兼任测距仪的激光指示器，在第四次公司战争中，它为荒坂的狙击手狙杀了不少重要人物，也为荒坂的重火力指引了许多目标。它在战时携带荒坂为其特制的消音冲锋枪，可以发射专属的淬毒亚音速穿甲弹。只要中了一发，非死即残。是许多军科士兵闻风丧胆的战争机器。其自带高级自律芯片，战斗技能14，潜行技能8，闪避11，手操模式下，有效信号半径为10km。被入侵时相当于智力7。",pr:2300,tier:"昂贵",grp:""},{n:"SDC-1 “黑寡妇”",mf:"军用科技",size:"中型",mode:"步行",ra:"SR",wpn:"无",endur:"6h",auto:"N",hp:"13/5",spd:"6",top:"10km/h",ds:"军用科技出口的中型电子战无人机，外观看起来像一只6足蜘蛛，里面塞满了笨重的电子战天线和芯片。它可以屏蔽12m半径的无线电信号，若使用者是黑客，也能用它为介质破解网络设施。若它停在敌对黑客的身上，它还可以直接停止该黑客的所有网络行动。潜行技能11，闪避8。被入侵时相当于智力7。",pr:3e3,tier:"昂贵",grp:""},{n:"CD-020 军团标枪",mf:"罗马工业",size:"中型",mode:"飞行",ra:"SR",wpn:"步枪",endur:"6h",auto:"Y",hp:"10/14",spd:"8/16",top:"140km/h",ds:"由罗马工业和阿斯特丽合作推出的一款新型安保镇爆无人机，使用微型化的浮空车引擎而非传统旋翼进行驱动，这加大了它的体积和重量，但也增强了它的续航性能（以及爆炸半径）。它的警用常规配置是一把泰瑟枪（只有非致命模式的电弧震荡炮），但在西非和巴尔干地区见到的款式就不会那么温柔了。它的军用型号会携带一款双联冲锋枪（数据同尤利西斯PDW），或者一挺突击步枪（数据同FA-5000），也可以自由选择配置。其自带高级自律芯片，战斗技能14，潜行技能8，闪避11，手操模式下，有效信号半径为10km.被入侵时相当于智力6。",pr:4e3,tier:"昂贵",grp:""},{n:"萨瓦纳犬-P",mf:"吉拉法",size:"中型",mode:"步行",ra:"SSR",wpn:"霰弹枪",endur:"12h",auto:"Y",hp:"18/7",spd:"11",top:"68km/h",ds:"吉拉法为世界各国的特警部队研发的先进款萨瓦纳犬，配有更先进的嗅觉传感系统和多种感官模式，使其能在多种环境下追踪犯人。其配备的警犬型自律AI芯片也不需要使用者分配动作去操控它，只需要简单下达言语命令即可。其具备很强的抗电子战能力，黑客入侵它的检定额外-4。同时身上配备一把野马军工“短程在握”霰弹枪，最大备弹量10发。反应8，射击技能13，潜行技能4，闪避技能12，追踪技能12。它在无命令的情况下和主人走散时，会自动寻回主人身边。被入侵时相当于智力8。",pr:5e3,tier:"极贵",grp:""},{n:"神风-特",mf:"荒坂",size:"中型",mode:"飞行",ra:"SSR",wpn:"炸弹",endur:"8h",auto:"Y",hp:"20/0",spd:"15/25/50",top:"400km/h",ds:"荒坂自己使用的自杀型蜂群无人机，不上市售卖，但是市面上有一些仿品。通常只搭载便宜的塑料外壳，以撞击的方式完成使命。自爆时，可以让直击半径5m的目标承受8D12的反坦克伤害（特效同单兵反坦克导弹），半径5m外15m内的目标承受8D6的高爆破片伤害。其操作方式接近巡航导弹，也可以切换为手操模式。重武器技能12，手操时使用操作者的重武器技能。有效信号半径40km。被入侵时相当于智力6。",pr:2400,tier:"昂贵",grp:""},{n:"DAPC-2 迦太基",mf:"罗马工业",size:"大型",mode:"步行",ra:"R",wpn:"民用设备/ 重型武器",endur:"6h",auto:"Y",hp:"30/12",spd:"7/14",top:"60km/h",ds:"常见的民用消防救灾多用途四足平台，采用了高度模组化的设计，可以将四足更改为轮式或者履式，它的四足自带小轮，可以在平稳路面上高速机动。其上方自带一个民用火控观测套组（花费额外2000eb更改为军用火控，战斗技能+4，且获得热成像能力）它的背上有一个可载重100kg的多用途平台，作为民用无人机应用时，上面多半安装的是灭火器、载重托盘等道具，但若是军用用途……那就看改造者的想象力了。罗马工业官方的无人机与战斗机器人团通常会在上面安装一挺重机枪或者榴弹发射器，偶尔也会安装导弹用来对抗敌方装甲。加价3000eb可以为其更换包含重装甲外壳和高功率电机的“军用套组”，将SP提升至20。它的战斗技能14，闪避8，潜行技能8。被入侵时相当于智力6。",pr:8e3,tier:"极贵",grp:""},{n:"GRAP2",mf:"吉拉法",size:"大型",mode:"飞行",ra:"R",wpn:"无",endur:"8h",auto:"N",hp:"30/4",spd:"4/10",top:"50km/h",ds:"工地里常见的飞行工程无人机，也是吉拉法的主要产品之一。在世界各地的工地都可以见到。它使用醇-2作为燃料，其牵引力足够拉起一辆小轿车，通常不会有人考虑将其用于军事目的。在搬运货物时，视为拥有20的体格，有效信号半径1km。被入侵时相当于智力4。",pr:1e4,tier:"奢侈",grp:""},{n:"鲁班-C2000",mf:"康陶",size:"大型",mode:"步行",ra:"R",wpn:"无",endur:"6h",auto:"Y",hp:"30/5",spd:"5",top:"7km/h",ds:"中国产民用人形机器人，采用局域联网设计。自带的自律芯片可以高效理解他人对它的指令，而由于操作上的复杂程度，这一类型机器人一般不能被人手工操控。它通常为服务业或者建筑工业使用，非常适合用来搬运货物或是干一些重复性较高的工作。例如粉刷、铺砖、焊接等，也会在一些餐馆担任前台收银员与上菜服务员。它的代码里完全没有任何战斗功能，即便被人攻击也只会蜷缩成一团保护关键部位。它没有战斗技能，闪避6，觉察10，体格12，被入侵时相当于智力4。",pr:9e3,tier:"极贵",grp:""},{n:"Verwalter™",mf:"IEC",size:"大型",mode:"步行",ra:"SR",wpn:"无",endur:"6h",auto:"Y",hp:"35/7",spd:"7",top:"10km/h",ds:"在欧洲高端餐厅和豪宅内十分常见的服务型机器人，被设计成了更接近人形的模样，出厂外壳使用镀铬处理的铝合金外壳，也有一些“特殊需求”的型号会被蒙上仿生皮。它采用了目前最高级的民用自律芯片，距离那些会被网络监察盯上的高知性AI只有几步之遥，无论何时，总会用最礼貌、最友善的态度和他人对话，让它们成为了富裕阶级最棒的保姆。小孩们都喜欢和他们的“铁皮管家”四处游玩。出于安全性考虑以及民用机器人的诸多法律上的规定，它被移除了战斗功能，也被压制了任何自卫和攻击性的倾向。但别以为袭击它们是毫无代价的，每一台注册在列的Verwalter机器人在被攻击时，都会录像并报警呼叫最近的治安机构，或是主人雇佣的私人安保。你不会想知道这些机器人的主人通常都为这些措施投资了多少资金的。它没有战斗技能，闪避8，觉察12，体格8，被入侵时相当于智力6。",pr:41e3,tier:"奢侈",grp:""},{n:"萨瓦纳豹",mf:"吉拉法",size:"大型",mode:"步行",ra:"SR",wpn:"猛禽之爪*2",endur:"8h",auto:"Y",hp:"25/14",spd:"12",top:"80km/h",ds:"既是富人阶级的家用宠物，又是他们最忠诚的家庭卫士。一种以美洲豹作为原型的仿生机器人，搭载了高水平的自律AI芯片。自带双单分子爪，可以把爆改混混轻松切成肉片。加价200可以加装定制人工毛皮。其近战技能16，闪避12，潜行11，觉察15，体格10，有效信号半径5km。被入侵时相当于智力6。",pr:6e3,tier:"极贵",grp:""},{n:"KSM-03P 美人鱼",mf:"IEC",size:"大型",mode:"游泳",ra:"SR",wpn:"鱼叉",endur:"18h",auto:"Y",hp:"35/14",spd:"7/12",top:"60km/h",ds:"第四次公司战争后，在IEC海岛设施外游弋的小型自律潜艇，用醇2作为燃料。是蛙人佣兵的噩梦。IEC内部使用的版本通常会安装水下步枪（同攻城弩，但能在水下使用），或者干脆安装战斗部当作小型鱼雷使用。但市面上常见的款式用的是一款可以自动装填的鱼叉枪（5发弹容，同梅塔集团捕鲸叉）。它通常由其他无人机携带并投送到水里，之后便凭着其高续航的特性在海中巡航，直到发现目标为止。其战斗技能16，闪避10（仅限水中），觉察14，潜行14。被入侵时相当于智力6。",pr:8e3,tier:"极贵",grp:""},{n:"午夜隼",mf:"泽塔科技",size:"大型",mode:"飞行",ra:"SR",wpn:"航空炸弹",endur:"12h",auto:"N",hp:"30/15",spd:"45",top:"800km/h",ds:"泽塔科技的轻型隐身无人轰炸机，比军用科技的出口产品更加轻量化，也更加便宜。但是代价是它只有一副武器挂架，最多只能携带一枚250lb的航空炸弹（相当于ACPA表100mm迫击炮弹最终伤害乘以3，范围半径+2m）。它通常不附带自律AI芯片，加装芯片的版本需要加价2000。其被雷达侦测的距离减少一半，重武器技能17，被入侵时相当于智力10。",pr:43e4,tier:"顶奢",grp:""},{n:"小矮妖",mf:"吉拉法",size:"大型",mode:"步行",ra:"SR",wpn:"机炮",endur:"6h",auto:"Y",hp:"32/20",spd:"8",top:"30km/h",ds:"吉拉法为苏石化陆军部队特别设计的巷战型突击机器人，设计相当激进。使用醇-2燃料。它在模仿动物的仿生双腿之上架设了一台重型机炮。同时附带一面防暴盾牌（参考镇爆专家）阻挡正面步兵火力。机炮可以替换成重机枪，也可以是反装甲导弹。相比精心训练的士兵，它能携带的火力更强，性价比也更高，机动性也远胜普通士兵的双腿。由于搭载了自律芯片，它只需要预先输入敌我识别的指令就可以自主行动。具有轻型反电子战外壳，黑客入侵时的检定额外-4。其重武器技能和全自动射击技能均为15，闪避8。被入侵时相当于智力8。",pr:68e3,tier:"顶奢",grp:""},{n:"艺妓",mf:"荒坂",size:"大型",mode:"步行",ra:"SR",wpn:"近战武器",endur:"6h",auto:"Y",hp:"40/7",spd:"8",top:"25km/h",ds:"在荒坂总部旅游过，或是在荒坂旗下酒店里喝过小酒的人绝对会对这一款机器人印象深刻。她们总是身穿和服，迈着优雅的碎步从帷幕后登场，为客人演奏三味线与太鼓。一旦发生意外，她们会立刻从双手里弹出螳螂刀，从裂开的脸里弹出霰弹枪将不速之客肢解成肉块。有都市传说声称这些造型优雅的机械艺妓里用的是活人的脑子，但荒坂从来没有正面回击过这则流言……它具有轻型反电子战外壳，黑客入侵时的检定额外-4，使用双持喷气式螳螂刀和一挺内置在嘴里的“街巷清扫者”进行战斗，近战战斗技能均为15，远程技能为12，闪避技能15（可以闪避远程攻击）。出于显而易见的原因，你很难在日本和荒坂的地盘之外看见这款战斗机器人。被入侵时相当于智力7。",pr:78e3,tier:"顶奢",grp:""},{n:"青年军-2A",mf:"罗马工业",size:"大型",mode:"步行",ra:"SR",wpn:"步兵武器",endur:"6h",auto:"Y",hp:"30/10",spd:"6",top:"10km/h",ds:"欧共体2037“军团”计划中标并预计投产的一款低成本人形战斗机器人，拥有人类的大小和外形，使用高强度轻质合金组成四肢，可以搭载任何单兵火力在战场上以量取胜。它们的局域指挥链AI系统让它们可以自主结成小队共享算力，并以一个协同的整体进行作战。换言之，它们出现在战场上的数量越多就越聪明。加价2000可以为其加装反电子战外壳，免疫黑客入侵。其所有战斗技能均为12，反应6，闪避8。每有3台“青年军”在100m半径内一起作战时，它的战斗技能额外+1，最高+5。被入侵时相当于智力5。",pr:46e3,tier:"奢侈",grp:""},{n:"兵马俑",mf:"康陶",size:"大型",mode:"步行",ra:"SR",wpn:"步兵武器",endur:"8h",auto:"Y",hp:"35/16",spd:"7",top:"10km/h",ds:"康陶自主研发的新一代战斗机器人，被设计成人类的大小和外形。也是它当前在军事领域中出口的主力产品。使用了从IEC处获得专利的自律战斗芯片。它可以搭载任何轻步兵火力，也可以承担更重的装备进行火力突击。康陶的设计师甚至专门为它的每个部位设计了1个义体插槽，让其可以兼容为赛博格设计的义体装备。使其成为了战场上最万金油的机械士兵。它的高级自律芯片可以进行敌我识别并自律作战，也能像一个冷血无情的士兵一样服从命令。加价2000可以为其加装反电子战外壳，免疫黑客入侵。其所有射击技能均为14，反应8，闪避10。被入侵时相当于智力6。",pr:72e3,tier:"顶奢",grp:""},{n:"八岐大蛇",mf:"荒坂",size:"大型",mode:"步行",ra:"SSR",wpn:"重机枪*2",endur:"12h",auto:"N",hp:"50/20",spd:"8/14/18",top:"100km/h",ds:"荒坂装甲部队使用的无人步兵火力支援车，可以搭载两挺重机枪或者一挺机炮。有时候还会搭载反装甲导弹去偷袭军科的装甲部队。它最主要的使用方法是一击脱离，因此通常不会有太多的备弹量。少数时候会装载重机枪在巷战中进行火力支援，但由于身板过于脆弱，很容易被反装甲火力摧毁。它使用卫星通信，信号范围无限。被入侵时相当于智力5。",pr:11e4,tier:"顶奢",grp:""},{n:"GRAF3",mf:"吉拉法",size:"巨型",mode:"步行",ra:"R",wpn:"无",endur:"8h",auto:"N",hp:"200/7",spd:"4",top:"20km/h",ds:"工地里常见的陆行起重机器人，也是吉拉法的拳头产品之一。其看起来像长颈鹿脖子的液压起重臂可以吊起数吨的材料，四足的结构既可以在起重时充当强力支撑，又可以爬上一些履带和轮子难以抵达的位置。通常不会有人考虑将其用于军事目的。搬运货物时，视为拥有30的体格，有效信号半径500m。被入侵时相当于智力4。",pr:3e4,tier:"奢侈",grp:""},{n:"LD-2X 双头鹰",mf:"罗马工业",size:"巨型",mode:"飞行",ra:"SR",wpn:"火箭巢 对地导弹",endur:"12h",auto:"N",hp:"100/18",spd:"40",top:"680km/h",ds:"巴尔干地区国家常用的查打一体无人机，以独特的双体设计而获得了这个名字。巨大的飞翼拥有两个重型挂架，可以用来挂载两个16发火箭巢，或者两个4发导弹组。在与土耳其联合打击希腊军政府的战役中，一位格鲁乌出身的苏联军事顾问曾经就死于这架无人轰炸机之下，一时间导致了意大利和苏联关系的交恶。它使用卫星通信，重武器技能18，信号范围无限。被入侵时相当于智力7。",pr:6e5,tier:"顶奢",grp:""},{n:"BDF-6",mf:"军用科技",size:"巨型",mode:"飞行",ra:"SSR",wpn:"航空炸弹",endur:"12h",auto:"N",hp:"80/25",spd:"60",top:"1000km/h",ds:"军用科技的出口军事武器中性价比最高的一项，采用了飞翼设计的隐形无人轰炸机，使用醇-2燃料。可以在数十千米开外投下炸弹，在敌人尚未察觉时便回到最近的机场中。它专用的雷达波隐身对地制导炸弹是军用科技的最高机密，通常不对外售卖，但它易于修改的三个通用炸弹挂架可以用来携带多种多样的制导导弹，甚至连冷战时期的铁炸弹也可以。它的重武器技能17，潜行技能7（面对雷达波侦察时17），它使用卫星通信，信号范围无限。被入侵时相当于智力8。",pr:4e5,tier:"顶奢",grp:""},{n:"HAWK-7",mf:"IEC",size:"巨型",mode:"飞行",ra:"SSR",wpn:"机炮 航空火箭",endur:"12h",auto:"N",hp:"155/22",spd:"6/35",top:"600km/h",ds:"IEC开发的近地支援无人炮艇，使用醇-2燃料。其隐形设计的外形和强劲的火力成为了许多军队火力支援的首选。不论是其在第四次公司战争中的首秀，还是在战后的一系列地区战争中的表现，都是军阀武装和各国政府梦寐以求的武器。它的抗电子战外壳可以免疫黑客的入侵，同时搭载了一门位于机首下方的机炮，还包含四个隐藏的挂载点，每个挂载点可以挂载两发对地导弹或者专属的16发航空火箭弹巢。重武器和全自动技能16，潜行技能12。它使用卫星通信，信号范围无限。被入侵时相当于智力8。",pr:75e4,tier:"顶奢",grp:""},{n:"神风-G",mf:"荒坂",size:"巨型",mode:"飞行",ra:"SSR",wpn:"战术导弹",endur:"6h",auto:"Y",hp:"180/15",spd:"20",top:"1800km/h",ds:"荒坂使用的战术巡飞弹，使用醇-2燃料，一发即可消灭一整个坦克排。作为荒坂最机密的几项武器之一，就连出口款也没有设计。从第四次公司战争以来，没有被缴获过哪怕一枚。它的抗电子战外壳免疫一切黑客入侵，落地引爆后，它可以在半径50m范围内造成8D12+100无视所有护甲的反坦克伤害，若处于爆心15m范围内，则伤害翻倍。并在半径50m外100m内造成6d12的重反器材伤害。它可以持续以300km/h的时速巡航24小时，并在锁定目标后，以满速进行自杀式袭击。它使用卫星通信，信号范围无限。它无法被远程入侵。",pr:"非卖品",tier:"顶奢",grp:""},{n:'M5A1 "平原舞者"',mf:"军用科技",size:"巨型",mode:"步行",ra:"SSR",wpn:"坦克主炮 重机枪",endur:"24h",auto:"Y",hp:"280/39",spd:"6/15",top:"100km/h",ds:"军用科技在战后研发的新一代重型装甲单位，使用醇-2燃料。其基础定位接近于一台主战坦克，但激进地使用了无人构造，节省了内部空间的同时，还增强了其装甲和火力。它可以搭载一门130mm磁轨坦克炮，并携带一门重机枪进行目标指示和补充火力。由于全封闭的抗电子战外壳，黑客只有接线的时候才有可能入侵它（接线时，相当于智力7。）。内置的军用自律人工智能可以理解一切人类命令，并使用专属的加密频段和上级联络。在无命令的情况下，也能自主识别军用科技的雇员和其他不坏好意的人。重武器技能17，它使用卫星通信，信号范围无限。",pr:"非卖品",tier:"顶奢",grp:""},{n:"土蜘蛛",mf:"荒坂",size:"巨型",mode:"攀爬",ra:"SSR",wpn:"速射炮*5",endur:"48h",auto:"Y",hp:"188/26",spd:"12/18",top:"90km/h",ds:"荒坂在第四次公司战争中研发的绝密战争机器，使用醇-2燃料。在多次巷战中大放异彩。其自带六足，可以攀爬墙面，也可以高速移动。身上的五门57mm磁轨速射炮可以瞄准不同的目标，还可以发射致命的神风G巡飞弹。虽然具备坦克一般的体型，但在巷战环境下出奇灵活。甚至单机猎杀过一整个排的装甲部队。至今荒坂对其的产量成谜，也不知道是否会再度投入战场中。它的抗电子战外壳免疫一切黑客入侵，其自带光学迷彩，潜行技能10，战斗技能18。它使用卫星通信，信号范围无限。",pr:"非卖品",tier:"顶奢",grp:""}],vehicles:[{n:"匍行蜘蛛 爬行椅",mf:"泽塔科技",type:"轮椅",ra:"R",seat:"1",sdp:"4/0",ter:"陆",spd:"5",top:"10km/h",endur:"40km",ds:"这是一张椅子，但是它会动！它有六只像是蜘蛛一样的机械腿，可以在大部分表面上爬行。在过去，像这样的椅子是为了残疾人准备的，现在，这样的椅子单纯是为了那些连动腿都懒的懒虫们准备的。它无法爬上垂直的表面，放在上面的饮料会撒的。你可以将上面的椅子改装成黑客椅（趁手工具表)，反正已经有人这么干过了，而且还不少。",pr:250,tier:"贫民",grp:""},{n:"爆发™ 火箭轮椅",mf:"梅塔",type:"轮椅",ra:"SR",seat:"1",sdp:"4/0",ter:"陆",spd:"12/26",top:"90km/h",endur:"100km",ds:"这事最初只是游民的一个笑话，后来被一伙喝醉的游民汽修工做了出来，发现意外的还挺有趣。碰巧这群游民汽修工的其中一员后来成为了梅塔集团的销售经理，它便成为了上市售卖的产品。这个老式轮椅上加装了一个功率强大的醇2摩托车引擎，让它可以用90km/h的时速在公路上飞奔。但它的操控性能算不上好，驾驶它时，陆地载具驾驶技能-4。",pr:800,tier:"廉价",grp:""},{n:"“水牛”折叠脚踏车",mf:"康陶",type:"自行车",ra:"N",seat:"2",sdp:"4/0",ter:"陆",spd:"4/8",top:"13km/h",endur:"/",ds:"以轻便、易携带闻名的中国产小型自行车，使用了康陶自研的超轻金属材料，保证了整体强度的同时，也极大减轻了重量。适合在公园和城市的自行车道上进行短途骑行，在不需要的时候可以折叠放进包里。其7kg的重量使一个上学的小孩都可以轻松背动。",pr:75,tier:"贫民",grp:""},{n:"“原野”山地脚踏车",mf:"富士达",type:"自行车",ra:"R",seat:"1",sdp:"4/0",ter:"陆",spd:"8/10",top:"18km/h",endur:"/",ds:"富士达公司在2030年推出的民用脚踏车，适合在山地进行越野，也适合翻越基础设施不佳的城市水泥路。在你不想为每周的电费和醇二费用发愁时，它是个不错的代步工具。",pr:200,tier:"贫民",grp:""},{n:"便携式摩托",mf:"三菱",type:"摩托车",ra:"N",seat:"1",sdp:"9/0",ter:"陆",spd:"9/12/15",top:"30km/h",endur:"190km",ds:"你是否需要一辆车，但又担心偷盗、停车和花费问题？如果是的，那么便携摩托就是你需要的那个。适合学生、工人和教师，便携式摩托车是由一个中央车体和小型座椅、车灯、把手、引擎与电池包，以及单独驱动的车轮组成的。整套结构折叠成一个小包裹后，可以很容易地在一个轮子上拖着走，或被一个强壮的人提着走。",pr:300,tier:"贫民",grp:""},{n:"小宝丽",mf:"IEC",type:"摩托车",ra:"N",seat:"2",sdp:"20/0",ter:"陆",spd:"7/11/14",top:"60km/h",endur:"120km",ds:"IEC进军低端消费级电动车市场的一次尝试，结果大获成功。在东南亚地区打开了非常广阔的销路。发展出了许多独特的型号。其电动能源相对醇二要便宜不少，成了不少贫困家庭的主要出行工具。其基础版本附带一个可拆卸的后备盒，可以放置一些路上买的小物件，也可以干脆拆了作为第三个座位使用。",pr:500,tier:"贫民",grp:""},{n:"足轻",mf:"三菱",type:"摩托车",ra:"R",seat:"1",sdp:"40/0",ter:"陆",spd:"9/15/20",top:"90km/h",endur:"300km",ds:"三菱足轻是城市骑行者的最佳选择。经典的线条，干净的操控，以及电力驱动的优点，使足轻成为完美的城市交通工具，它有足够的速度让你到达目的地，也有足够的加速度让你迅速摆脱麻烦。",pr:1300,tier:"廉价",grp:""},{n:"“小僧”三轮脚踏车",mf:"康陶",type:"自行车",ra:"R",seat:"3",sdp:"30/0",ter:"陆",spd:"8/12",top:"18km/h",endur:"/",ds:"三只轮子，一个货斗。这种非典型的三轮脚踏车可以从人力的踩踏中汲取电力，并一定程度上辅助运行。典型的三轮脚踏车可以容纳三人或者是少量货物。在日常档的电力辅助下，最高时速为30km/h，如果满载则降至18英里/小时。但如果电力充足，可以打开三档速度，在极限状况下可以用50英里/小时的速度行驶十分钟。",pr:750,tier:"廉价",grp:""},{n:"战马",mf:"刃",type:"摩托车",ra:"R",seat:"1",sdp:"44/4",ter:"陆",spd:"12/18/24",top:"100km/h",endur:"250km",ds:"夜城街头暴走族的入门级装备，也是那些想耍帅的年轻人们最酷的生日礼物。这辆摩托车用碳纤维构筑车身，由一流的设计者设计外形。使用改进过的老式醇二动力引擎，动力强劲，脾气火爆。它具备一辆好摩托车应该具备的一切。但它的安全性能不太好，耗油量也很高。夜城几乎50%以上和摩托车有关的事故里，都和这一款摩托有关系。但也许，也许这只是那些青年骑手们把控不住罢了。",pr:1e3,tier:"廉价",grp:""},{n:"冲击者悬浮滑板",mf:"IEC",type:"滑板",ra:"R",seat:"1",sdp:"20/0",ter:"飞",spd:"14/22",top:"80km/h",endur:"100km",ds:"使用了气动悬浮原理的酷炫滑板，夜之城的小崽子们经常开着它去炸街。操作它的难度相比摩托要更大，但也能做出比摩托还要更加酷炫的动作。它最多可以载重120kg，在非极限载重的情况下，它可以悬浮大约离地4m的高度，极限载重下，它最多只能保持30cm的高度悬浮。它实际上并不能保护它的驾驶者，因此除非特别瞄准，否则都将攻击滑板上的驾驶员。驾驶员可以在驾驶滑板的同时闪避。",pr:1300,tier:"廉价",grp:""},{n:"复仇女神 火箭滑板",mf:"梅塔",type:"滑板",ra:"SR",seat:"1",sdp:"40/0",ter:"飞",spd:"15/30",top:"150km/h",endur:"80km",ds:"IEC在悬浮滑板市场上的主要竞品，但它的原理更加简单粗暴：基本上就是把一台AV的引擎小型化，然后绑在了一块滑板上。这显然赋予了它极其强劲的动能，但也极大增加了它的不稳定性和危险性。每年它的事故报告多到数不过来，但多半经过调查后，都不是产品本身的问题，只是单纯使用者的技巧问题罢了。它最多可以载重200kg，在非极限载重的情况下，它可以悬浮大约离地10m的高度，极限载重下，它最多只能保持30cm的高度悬浮。它实际上并不能保护它的驾驶者，因此除非特别瞄准，否则都将攻击滑板上的驾驶员。驾驶员可以在驾驶滑板的同时闪避。",pr:2500,tier:"廉价",grp:""},{n:"草原猎鹰",mf:"梅塔",type:"摩托车",ra:"SR",seat:"1",sdp:"30/4",ter:"飞",spd:"6/30/35",top:"180km/h",endur:"280km",ds:"由游民DIY的飞天摩托处得来灵感，并经由梅塔集团的专业设计师制造的轻型飞行器。由于其的危险性，通常不被允许在夜之城的城市上空飞行，但恶土和荒漠是它绝佳的飞驰场所。只需额外花费500eb，就可以为其假加装额外的副油箱，使其的续航里程增加200km。",pr:3e3,tier:"廉价",grp:""},{n:"野火",mf:"ARCH",type:"摩托车",ra:"SR",seat:"1",sdp:"50/10",ter:"陆",spd:"12/20/30",top:"150km/h",endur:"580km",ds:"为北美摩托帮准备的重型摩托车，其自带的大油箱可以让车主轻松跨越美国西部的荒漠戈壁。较高的底盘也为其赋予了强大的越野能力，其自带的携行支架可以用来存放啤酒或是一把霰弹枪。在许多游民举办的飙车大赛中，它总是最亮眼的明星之一。",pr:2300,tier:"廉价",grp:""},{n:"彗星骑士",mf:"哈雷",type:"摩托车",ra:"SR",seat:"1",sdp:"52/12",ter:"陆",spd:"14/22/32",top:"200km/h",endur:"1300km",ds:"这台车最大的特点便是其夸张的大小，几乎有一辆轿车的一半体积。除了那对硕大的前后轮外，这辆摩托车的大部分体积都用来放置它强劲的醇二引擎和燃料箱。满速运行时，它的引擎会爆发出一股令人陶醉的轰鸣声，几乎每一个摩托车主都对其赞誉有加。在2043年时曾有一位车主骑着它横跨了整个旧美国的土地，让它一战成名。",pr:17e3,tier:"平价",grp:""},{n:"湿婆",mf:"昆达利尼",type:"摩托车",ra:"SR",seat:"1",sdp:"43/10",ter:"陆",spd:"17/32/42",top:"270km/h",endur:"400km",ds:"湿婆是昆达利尼的第一款高性能摩托车。在取得个人汽车和轻载卡车的成功后，昆达利尼承诺在湿婆提供同样优秀的电动缓冲器。在赛道上，其额定时速超过260千米/小时，其赛博辅助悬挂系统可让您在接近速度的理论上限的情况下在恶劣路面保持直立。它的加速度与其他高速摩托车相当，拥有着赛道级而非街头摩托的操纵性。但它就在那里：快如激光，比夜更黑。",pr:6e3,tier:"平价",grp:""},{n:"阿瑞斯",mf:"布伦南",type:"摩托车",ra:"SSR",seat:"1",sdp:"47/11",ter:"陆",spd:"12/18/ 24/30",top:"95km/h",endur:"150km",ds:"阿瑞斯采用了专利的布伦南摩托“宪兵”型底架，使其成为路上最耐用的摩托车之一。它配备了一个可拆除的武器吊舱。通常情况下，摩托车难以负担外部吊舱的重量。然而，布伦南的设计师创新性地将枪炮吊舱安装在挎斗结构中，让路面来支撑大部分重量。武器吊舱装有一门标准的20mm机炮。全计算机化的智能悬挂能让你在不牺牲操控性的情况下使用挎斗/武器吊舱。在游民和机车帮中很受欢迎，通常是非法的（多亏了那台标准的机炮）。可降价3500eb买到不带机炮的版本。",pr:21e3,tier:"优质",grp:""},{n:"亵渎者β",mf:"本森",type:"摩托车",ra:"SSR",seat:"1",sdp:"40/12",ter:"飞",spd:"19/60",top:"480km/h",endur:"700km",ds:"本森亵渎者β是这家老牌浮空摩托厂家对这一概念的全新诠释。也是少数推荐驾驶员穿上战斗机抗压服再驾驶的浮空摩托。它可以让驾驶员接上神经链接，就像自己的外接肢体一样开动它。使驾驶时的一切检定+2。它看起来像是摩托车和气垫船的怪异嵌合体。却能像战斗机一样在高空巡航，并发出难以想象的巨大噪音。",pr:1e5,tier:"奢华",grp:""},{n:"乌鸦",mf:"新美国汽车",type:"汽车",ra:"N",seat:"2",sdp:"50/7",ter:"陆",spd:"10",top:"50km/h",endur:"300km",ds:"新美国汽车公司的乌鸦曾是北美最受欢迎的电动城市汽车之一，甚至在海外也有授权生产。在第四次公司战争后，因新美国汽车公司的倒闭而停产。从那以后，有许多企业对这一型号的汽车进行了仿制和再生产。如今市面上常见的该型号多为假冒伪劣产品，且用的技术非常过时。更别提还有不少还是翻新的二手车和事故车。",pr:3500,tier:"廉价",grp:""},{n:"海岸线-4",mf:"丰田",type:"小货车",ra:"N",seat:"2",sdp:"70/6",ter:"陆",spd:"6/10",top:"100km/h",endur:"600km",ds:"一款来自10年代的老式四驱敞篷小货车，其采用的醇二引擎有着极高的可靠性，而且维护也相对简单。在第三世界国家有着大量出口。虽然已经于2037年停产，但由于其坚固耐用的品质，在市面上还有大量二手车存货。一些游民至今仍用它进行长途运输业务。",pr:5e3,tier:"平价",grp:""},{n:"巧匠",mf:"康陶",type:"轿车",ra:"N",seat:"4",sdp:"50/7",ter:"陆",spd:"8/13/22",top:"76km/h",endur:"500km",ds:"为了适应中国十四亿人口的出行需求，康陶特别与中信联合推出的一款中低配电动汽车。只适合在城市道路上行驶，因此用的发动机性能不咋地。但这也让其价格看起来相对实惠，是许多中国平民的首选车辆，在海外与夜之城有不少出口，但还是无法和其他本地车商抢市场。花费额外的2000eb可以购买高配版本，不仅有升级的合金车身（+5sp），还搭载了IEC生产的搭载的量产型辅助驾驶AI芯片。",pr:7e3,tier:"平价",grp:""},{n:"舞舞",mf:"卷贝",type:"轿车",ra:"N",seat:"2",sdp:"30/2",ter:"陆",spd:"6/13/20",top:"100km/h",endur:"180km",ds:"对于预算紧张的人来说，这是一辆完美的汽车。舞舞是夜之城最便宜的量产汽车。所有设计决策都围绕着一个目标：降低成本！尺寸？尽可能小，但仍然能容纳两个（苗条的）人和（最多）一个购物袋。引擎？可能是从割草机上偷来的。材料？像一次性叉子一样耐用的塑料。安全测试评级？勉强合法。所有这些都捆绑在一个很容易负担得起的包装中。他们说公司不再关注消费者的最大利益了……",pr:2e3,tier:"廉价",grp:""},{n:"科尔比C125",mf:"桑顿",type:"轿车",ra:"R",seat:"4",sdp:"100/7",ter:"陆",spd:"9/17/23",top:"100km/h",endur:"800km",ds:"新美国大地上最常见的一款消费级四座轿车，是有些小钱的上班族和普通市民的出行首选。在夜之城，它以超高的性价比和相当不错的售后服务获得了很多车主的心，可惜这一车型的越野能力不强，导致一些看中了它性能的游民，只能自己上手改造。",pr:18e3,tier:"平价",grp:""},{n:"方铅矿 G240",mf:"桑顿",type:"轿车",ra:"R",seat:"4",sdp:"100/10",ter:"陆",spd:"6/12/ 18/24",top:"90km/h",endur:"500km",ds:"过去，人们只想要面包和马戏表演。然而，到了 21 世纪，汽车也加入了人们的欲望之中。没有车，你就无法去上班，无法送孩子去幼儿园，也无法逃避自发的街头混战。在政府推出刺激计划以生产平价汽车并在经济衰退的今日提振美国人的生活后， 桑顿“方铅矿”于 2031 年首次上路。由于桑顿当时在生产小型车方面经验不多，因此该公司从印度的马希尔摩托购买了方铅矿的发动机。不幸的是，这次合作并不被认为是成功的，方铅矿的性能平平，销量更不理想。尽管如此，它还是可以驾驶的——这是最重要的。",pr:13e3,tier:"平价",grp:""},{n:"赫拉 EC-D I360",mf:"天穹",type:"轿车",ra:"R",seat:"4",sdp:"90/10",ter:"陆",spd:"8/15/22",top:"100km/h",endur:"700km",ds:"汽车的质量要过硬…但也不能太过硬。天穹的董事会就为此支付了高昂的学费。2023年，他们发布了赫拉系列的第一款车型。结果它实在是耐用，又非常容易修理，险些让公司破产。必须指出的是，赫拉的定价经济实惠，很多当年的车主后来再也没有买过新车。即便是在许多年过去后的今天，夜之城的街道上还时常能看到天穹赫拉的身影。当然，岁月不饶人，其中的大多数都已经锈迹斑斑，开起来吱嘎作响。不过作为代步工具，它们还是在继续为人们服务，除非半路上撞了车。那样的话，也就不用去花心思抢救了。尽管赫拉实用可靠，但车身使用的材料既廉价又脆弱。好在对车主来说，如果在事故中失去了保险杠和一条腿，那么这两样东西都可以轻松地换掉。",pr:12e3,tier:"平价",grp:""},{n:"J-home 系列",mf:"三菱",type:"小货车",ra:"R",seat:"6",sdp:"100/7",ter:"陆",spd:"10/16/24",top:"90km/h",endur:"800km",ds:"在日本街头较为常见的小型面包车，说小是真的很小，坐六个人在里面都显得满满当当。但好在它的引擎足够强劲，可以轻松应付日本乡间的多山地形。日本的城市运输业很喜欢将它的乘客舱改造成货舱，并用来进行一些市区内小范围、小体量的运输。这样不仅成本低，而且效率也很不错。但是在美国，它就不是那么常见了。毕竟它并不是设计给美国人的……体型来使用的。",pr:1e4,tier:"平价",grp:""},{n:"哥伦布",mf:"维利福",type:"小货车",ra:"R",seat:"7",sdp:"110/7",ter:"陆",spd:"7/12/ 18/22",top:"80km/h",endur:"900km",ds:"很难想象夜之城的街道上没有哥伦布会是什么样子。这款小型面包车是维尔福装配线上最便宜、最新的车型。许多中低端运输服务都使用它来送货。哥伦布简单、实用，它的引擎当然不会让你心跳加速，但你可以打赌它能完成工作。",pr:12e3,tier:"平价",grp:""},{n:"U4020",mf:"高加索",type:"大货车",ra:"R",seat:"2",sdp:"180/17",ter:"陆",spd:"6/13/19",top:"70km/h",endur:"1500km",ds:"苏联人也许无法生产世界级的超级跑车、豪华轿车或舒适的家用车，但他们的工程用车却是首屈一指的。任何有幸驾驶过高加索“布拉茨克”的人都可以证明这一点。这款苏联工程巨兽配备了庞大的发动机，尽管体型巨大，但几乎在任何条件下它都可以一边拖着坦克一边顺利驾驶。缺点是什么？它满载的时候不能在老旧的桥梁上行驶……而且它冒出的烟就像轮胎着火一样。",pr:3e4,tier:"优质",grp:""},{n:"CA-30 智能重卡",mf:"康陶",type:"大货车",ra:"R",seat:"1",sdp:"150/14",ter:"陆",spd:"7/14/21",top:"80km/h",endur:"1300km",ds:"中国产智能平头重型卡车，每一台都安装了目前性价比最高的民用驾驶芯片。可以按照既定的程序在城市道路和乡野矿场之间自律行驶。在智能驾驶政策的推行下，它在中国一二线城市的国道上是十分常见的风景。即便如此，根据官方的要求，它依然保留了一个驾驶位，以在一些高危险道路和智能芯片无法顾及的道路接管驾驶。",pr:27e3,tier:"优质",grp:""},{n:"M2030 驼兽",mf:"梅塔",type:"大货车",ra:"R",seat:"3",sdp:"160/19",ter:"陆",spd:"6/12/18",top:"60km/h",endur:"1800km",ds:"自从新美国解体之后，横跨美国的高速公路基建正变得越发恶劣。而这量重卡正是梅塔为了考虑游民的生活而特别开发的。它的重型轮胎强调防护和越野性能，即便在没有公路的荒野上，游民也能驾驶着它平稳行驶，即便路上遇到尖锐的碎石和路钉，也会被它轻松碾过。它宽敞的驾驶室后方还留有一个给炮塔的空位，游民们通常会在上面安一台反器材机枪，用来防护刀锋掠夺者的觊觎。",pr:32e3,tier:"优质",grp:""},{n:"谷",mf:"卷贝",type:"小货车",ra:"R",seat:"2",sdp:"90/7",ter:"陆",spd:"7/14/18",top:"80km/h",endur:"800km",ds:"这款车型在沾满污垢时看起来最漂亮，所以不要把它放在车库里积满灰尘。谷相对较小的尺寸让其能够轻松穿越夜城郊外的垃圾山，而弹簧悬架和四轮驱动为每一次越野冒险增添了乐趣。即使是一条剧毒的污水河也无法将您从道路上甩掉。坚固的 ABS 通气管可以让腐烂的水远离发动机。小巧而又充满活力——卷贝的缩影。",pr:1e4,tier:"平价",grp:""},{n:"U420“泽雅”",mf:"高加索",type:"小货车",ra:"R",seat:"2",sdp:"150/12",ter:"陆",spd:"6/12/ 16/22",top:"90km/h",endur:"1000km",ds:"U420是一款小型卡车，车厢较短。在夜之城，人们经常看到它运送垃圾箱和其他小件货物， NCPD清洁人员也用它来处理有毒/放射性废物。这款卡车拥有强劲的发动机、3 吨的载重量和令人惊讶的低廉价格，在世界各地都很受欢迎。在驾驶泽雅进行长途货运时，您可能会开始思考在中央计划经济中货物的最佳分配。",pr:25e3,tier:"优质",grp:""},{n:"特拉克斯 388 杰斐逊",mf:"雪佛龙",type:"轿车",ra:"SR",seat:"2",sdp:"100/16",ter:"陆",spd:"10/15 20/26",top:"180km/h",endur:"700km",ds:"特拉克斯系列一直是企业中层商务人士的首选汽车，它优雅、令人尊敬，最重要的是——它很安全。它从上到下覆盖着装甲，可以穿越地雷爆炸，而它的防弹窗户可以挡住大口径子弹。缺点是什么？尽管其拥有强大的引擎，能够达到令人眼花缭乱的速度，但由于重量惊人，它加速缓慢。但迟到总比不到好。更不用说完好无损了。它的车门和车身自带防弹改装，其玻璃也可以当作掩体，具有11sp和10hp。",pr:55e3,tier:"奢华",grp:""},{n:"MH-630 温暖之家",mf:"维利福",type:"小货车",ra:"SR",seat:"8",sdp:"110/10",ter:"陆",spd:"6/9/ 13/18",top:"80km/h",endur:"800km",ds:"游民群体中十分炙手可热的一款房车，拥有很高的改造性能，它的车厢宽大，四处都是高效设计的可折叠空间。你看到的柜子可以当作桌子，抽屉可以当作椅子，厨房水槽可以兼做菜板……你完全可以带着一家六口人过上“居无定所”的流浪生活，只要记得路上去为它补给生活用水和燃料。你可以在很多拖车公园中见到这一款房车，甚至有不少人打算一辈子就住在这样的一辆车里。",pr:32e3,tier:"优质",grp:""},{n:"旅行家系列",mf:"丰田",type:"小货车",ra:"SR",seat:"4",sdp:"120/10",ter:"陆",spd:"4/8/ 14/18",top:"90km/h",endur:"1000km",ds:"一辆适合家庭出行的小型货车，拥有不错的续航能力，驾驶位也相当舒适。它最大的特色在于高度模块化的自定义组件，其独特的尾部车厢可以改装成座舱、车斗或者小型货舱。有些游民甚至将它改造成了战斗车辆，在车队左右作为护航。",pr:43e3,tier:"优质",grp:""},{n:"科尔特斯 V5000 勇气",mf:"维利福",type:"轿车",ra:"SR",seat:"4",sdp:"100/12",ter:"陆",spd:"16/24",top:"120km/h",endur:"750km",ds:"可能是维利福工厂生产的所有车辆中性价比最高的一款。科尔特斯的设计简洁而优雅，吸引了不少公司、政客和罪犯。它与阿尔瓦拉多采用相同的框架制造，但只有两个轴，因此更容易发生完全故障。但其强大的引擎使科尔特斯能够快速起步，其加固车身（与军用科技合作制造）在夜之城不可预测且危险的街道上提供了额外的保护，可以免疫手枪穿甲等级子弹的射击。它们通常是NCPD巡逻车的首选车型，在不远的未来，德拉曼出租车也是在这一车型之上改良而来的。",pr:3e4,tier:"优质",grp:""},{n:"阿尔瓦拉多 V4F 570 使者",mf:"维利福",type:"轿车",ra:"SR",seat:"4",sdp:"125/10",ter:"陆",spd:"10/18/ 24/26",top:"130km/h",endur:"750km",ds:"你不会开着阿尔瓦拉多去上班，而是开着它去兜风炸街。这辆船型汽车的引擎值得街道的尊重。尽管这辆六轮汽车尺寸巨大，但由于前面的四个轮胎有双轴，使它的操控性不至于太差。不幸的是，这种创新设计仍然相当不可靠，需要频繁的、有时是昂贵的维护。对于夜之城地下世界中的许多人来说，阿尔瓦拉多是炫耀奢华的理想之选。",pr:7e4,tier:"奢华",grp:""},{n:"雷霆-X",mf:"夸德拉",type:"跑车",ra:"SR",seat:"4",sdp:"110/7",ter:"陆",spd:"12/22/ 32/42",top:"220km/h",endur:"800km",ds:"雷霆-X是夸德拉推出的入门级轿跑车，适合那些有些小钱但手头又不是特别阔绰的人群。因此特别受那些青年富二代和暴发户的欢迎。它的造型相当大胆且前卫，带有十五种特别的配色和修改方案，而且车内的诸多部件都是模组化的，支持车主发挥想象力去DIY自己的爱车。当然，这些外观和功能上的DIY部件全部都是夸德拉自己生产的。",pr:12e4,tier:"奢华",grp:""},{n:"FJ-V200 越野吉普",mf:"军用科技",type:"轿车",ra:"SR",seat:"5",sdp:"100/13",ter:"陆",spd:"14/20/27",top:"140km/h",endur:"1200km",ds:"这台马力充足、续航持久的越野吉普适合在恶土和山巅上狂飙，它精心设计的悬挂让它能征服任何常见的陡坡和烂路，并尽量保证车内行驶的平稳。但它的民用款为了减重导致牺牲了不少装甲，如果用户希望的话，可以花费额外的3000eb升级军用车壳装甲（+20hp，+4SP）",pr:6e4,tier:"奢华",grp:""},{n:"陆地猛兽™装甲SUV",mf:"军用科技",type:"装甲车",ra:"SR",seat:"7",sdp:"120/22",ter:"陆",spd:"10/18/24",top:"100km/h",endur:"900km",ds:"作为军用科技在车辆领域上最受欢迎的产品，这是极少数能在市区中合法购买、上路的民用装甲SUV，无论是企业还是个人，都会用它作为穿越危险地带、运输VIP的高性价比手段。因此按照法律来说，它不会附带任何武装。它有人员舱和货舱两种款式，前者为标配，后者将后方的五人作为取消，用以运输货物或是部署特殊工作。它使用全覆式防弹驾驶舱，只用摄像头投影外部景象。它的全覆式装甲车窗有20sp15sdp。",pr:2e5,tier:"极奢",grp:""},{n:"火星征服者",mf:"梅塔",type:"工程车",ra:"SR",seat:"30",sdp:"300/16",ter:"陆",spd:"4/10/15",top:"80km/h",endur:"2000km",ds:"火星征服者是你所见过的最大的公路巨兽之一，一个正常身高的成年人都无法抵达它轮胎的顶部。它只适合无拘无束的野外，不适合在有限高的市内通行。这台7m高的庞然巨物据称可以塞进一整个游民家族，其后备的货斗可以用来装载上百吨的货物，或者干脆改造为一个舒适的游民生活空间。只要愿意，甚至可以将一座双层小别墅修在上面，而许多购买了它的游民都选择了后者。在一个游民家族里，它往往是一个家族族长最威风的座驾。有不少被特别定制的火星征服者以极其华丽的外观出现在美国中西部的荒野上。甚至有些拥有奇思妙想的族长将它改成了浮空车，这其中的原理恐怕没人知道。",pr:145e4,tier:"顶奢",grp:""},{n:"Vl-0900 公爵 加长款",mf:"涡轮霓虹",type:"轿车",ra:"SSR",seat:"8",sdp:"150/17",ter:"陆",spd:"13/19/26",top:"150km/h",endur:"950km",ds:"这款加长型号的奢华轿车专门为世界各地的明星和国家级政客设计。它宽大的车厢足够容纳6个人在它的后座上开趴，特别加固的防弹玻璃（17sp15hp）让它开过战区的枪林弹雨也能毫发无伤。当你在街上看见这一辆车招摇过市的时候，想都不要想，里面肯定坐着某位不得了的大人物。若真有些不长眼的蠢货打算用重火力招呼它，其自带的“皇家护卫”主动防御（APS）系统也能智能识别并击毁来袭的火箭弹和导弹。（被火箭弹和导弹攻击时，投掷一枚D10，出目6+成功拦截。）",pr:2e6,tier:"顶奢",grp:""},{n:"落日骑士",mf:"保时捷",type:"跑车",ra:"SSR",seat:"2",sdp:"130/10",ter:"陆",spd:"35/80",top:"330km/h",endur:"700km",ds:"“落日骑士”是一位欧洲赛车手的绰号。曾经有那么一段时间，他驾驶着保时捷专门为他定制的赛车，在赛场上几乎没有敌手。甚至在世界级的赛事上拿过三连冠的惊人成绩。可惜的是，他在2036年的一场比赛中，因为一次意外碰撞导致的事故而身亡。为了纪念这位选手曾经在赛场上的惊人表现，保时捷推出了这款竞赛级的超级跑车。其最大的特点在于其特别定制的竞赛引擎，可以在1.7秒内起步直达100km/h，并在5秒的时间内抵达它的设计极速。它适合那些如“落日骑士”一样，拥有追逐速度的不羁心灵，并不适合那些在马路上开得畏畏缩缩的胆小鬼们。",pr:23e5,tier:"顶奢",grp:""},{n:"Vc-0080 王座",mf:"涡轮霓虹",type:"跑车",ra:"SSR",seat:"4",sdp:"175/20",ter:"陆",spd:"18/35/62",top:"250km/h",endur:"800km",ds:"涡轮霓虹在2044年推出的顶级限量款超级跑车,全球仅有500辆。其最大的卖点在于结合了纳米科技的“液态金属”可变外壳，不仅可以变幻不同的色彩和图案，还能泛起最高3cm的金属波纹。当它驶过街道时，将带给每个路人最顶级的视觉体验。要是遇到了不法分子，这层“液态金属”的外壳也能如同防弹装甲板一样吸收扫过的子弹，而且还不受轻微磕碰的影响。（直到摧毁之前车体都是超重甲）其内饰座椅均采用真皮和真天鹅绒（克隆）进行填充，还有一个专属的AI助手辅助行驶与生活咨询。根据他们的广告词来说,坐在上面就好像罗马皇帝坐在他的王座上一样。拥有它的车主不论是驾驶着它还是把它的特制“液态金属”钥匙挂在身上，cool就获得+3的加值。",pr:4e6,tier:"顶奢",grp:""},{n:"“补丁狗”",mf:"无",type:"浮空车",ra:"N",seat:"4",sdp:"50/7",ter:"飞",spd:"9/18/27",top:"180km/h",endur:"300km",ds:"在一座正常的城市里，这样的一架“浮空车”是绝对不允许上路的，说他是浮空车都有些抬举它，毕竟它是游民和街区混混用废弃的大型无人机/浮空车引擎、回收的车壳和各种它们能找到的材料焊成的。这个名字就是这一类车的统称。它极其脆弱，而且也不兼容任何系统，需要驾驶者像驾驶手动档老车一样驾驶它，一不小心就会撞楼上。但如果你用的车壳品相好一点，车技好一点，那它还是勉强可以混进车流中的。驾驶它的载具技能-3，在城内驾驶它需要视地点过一个成功的空中载具检定，否则会发生事故。",pr:1e4,tier:"平价",grp:""},{n:"风扇大师",mf:"尼桑福特",type:"浮空车",ra:"N",seat:"3",sdp:"75/7",ter:"悬浮",spd:"4/12/22",top:"120km/h",endur:"500km",ds:"买不起航空汽油怎么办？为什么不尝试一种更便宜、更低技术含量的替代品呢？无论在城市内外（特别是在道路有限或没有道路的地区），尼桑福特都是一道常见的风景。它可观的货运能力、可靠性和耐用性使得这款悬浮卡车成为户外旅行者或拥有家具的城际旅客的理想交通工具。按照军用悬挂规格建造，如果你能在悬浮扇上到达那里，尼桑福特也能带你到达你的目的地！它甚至还是完全两栖的！注：风扇大师只能悬浮大约30~50cm的距离，并不能和其他浮空车一样进行离地飞行。",pr:2e4,tier:"优质",grp:""},{n:"小笼包",mf:"康陶",type:"浮空车",ra:"N",seat:"4",sdp:"45/4",ter:"飞",spd:"7/16/22",top:"120km/h",endur:"400km",ds:"康陶步入民用浮空车市场所出的第一款平价浮空车，使用的浮空车引擎还属于上个世代，具有严重的出力不足问题。但作为一款城市环境中的民用浮空车，它倒还省了限速的麻烦。它的用户手册里特别提到最好不要将重物塞满它的后备箱，在4人满载的情况下它最多只能飞行到离地10米左右的高度。如果再将后备箱满载（大约100kg），为了安全考虑，车载AI将会切换至离地30cm的公路模式。",pr:27e3,tier:"优质",grp:""},{n:"家庭飞行者",mf:"VMW",type:"浮空车",ra:"R",seat:"6",sdp:"50/7",ter:"飞",spd:"8/16/24",top:"160km/h",endur:"350km",ds:"一款来自VMW的老式浮空车系列，常年来一直销量火爆。到2043年时，VMW已经推出了它的第7个改型。最新的版本优化了其载重的能力，但其使用的引擎却有不小的安全隐患：它在子弹的直击下很容易变成一团飞行的火球，然而也很少有人会把这东西往战区里开。从消费者的角度来说，家庭飞行者价格实惠，利率合理（10%年化利率）。易于驾驶，维护费用低廉，并且具有市场上其他同类空气动力飞行器中最高的燃油效率之一。这些面对佣兵的安全隐患完全可以选择性忽视。",pr:37e3,tier:"优质",grp:""},{n:"飞驴",mf:"四方行",type:"浮空车",ra:"R",seat:"2",sdp:"70/10",ter:"飞",spd:"7/14/20",top:"100km/h",endur:"400",ds:"常见的小型空中短途货运浮空车，便宜耐操，性价比高。它采用全封闭货舱，理论上它也可以多坐4个人在里头，但会很挤，而且很晃。它使用了先进的重型浮空车引擎，可以运载三吨的货物在10m的高度飞行。但在满出力的情况下非常费燃料，这也是它十分受人诟病的地方。",pr:38e3,tier:"优质",grp:""},{n:"AeroVox",mf:"泽塔科技",type:"浮空车",ra:"R",seat:"4",sdp:"40/5",ter:"飞",spd:"11/20/26",top:"180km/h",endur:"400km",ds:"AeroVox是一台适合工薪族的经济型浮空车，虽然对于世界上的许多普通家庭来说，这个价格还是有些令人望而却步。但对于一个企业的普通职员来说，它已经物超所值了。对于那些能支付得起它的人而言，AeroVox是一项绝佳的通勤工具，可以避开地上的车流，轻松从空中通道抵达公司的高层停机坪。其最大的缺点在于，为了节约成本，泽塔科技使用了混合动力的浮空车引擎，使其载重、续航和装甲有些不尽人意。但对于一个在城区上班的工薪族来说，这几项也不是那么刚需。",pr:4e4,tier:"优质",grp:""},{n:"目的地",mf:"泽塔科技",type:"浮空车",ra:"R",seat:"4",sdp:"50/7",ter:"飞",spd:"10/20/28",top:"190km/h",endur:"550km",ds:"目的地是一款紧凑型的民用浮空车，乍看之下，它的各项指标在该领域平平无奇。但正是这种“平庸”让它在家庭浮空车领域没有明显的缺点和短板，且驾驶手感一流。即便是一个从未驾驶过汽车或浮空车的普通青少年，也可以在车载AI的辅助下平缓地抵达目的地。这也是它能在全球范围内有着两百万惊人销量的原因之一。若再加价5000eb升级自律车载AI，还可以直接使用GPS导航，无需驾驶者手握方向盘。",pr:35e3,tier:"优质",grp:""},{n:"商务方案",mf:"IEC",type:"浮空车",ra:"R",seat:"6",sdp:"65/7",ter:"飞",spd:"12/20/26",top:"170km/h",endur:"600km",ds:"本来是作为IEC为旗下员工设计的郊外园区通勤工具，但由于其出色的性能和效率，IEC决定推出该车型的消费版本。作为一辆六座的浮空车，它有足够的马力可以在满载的情况下保持30m的高度飞行。它的四枚引擎上自带一个可以调整位置的调节阀，可以在绝大多数飞行的情况中保持车舱内的水平。对于那些付得起它的中层管理人士来说，它经过一些改装也可以作为浮空货车或者会议室使用。如果再加价10000eb，可以购买附带了高级自律AI的豪华版本，使车主可以完全放松，享受地度过每一次飞行。",pr:69e3,tier:"奢华",grp:""},{n:"迈阿密阳光",mf:"四方行",type:"浮空车",ra:"R",seat:"6",sdp:"70/10",ter:"飞",spd:"10/20/30",top:"200km/h",endur:"300km",ds:"作为新美国汽车一款旧型号浮空车的改良款，迈阿密阳光是一辆各方面性价比都非常均衡的浮空车，甚至在浮空车这个领域都有相当不错的载重。由于它的货舱宽大，载重优秀（最高载重1t），使它非常适合家庭旅游出行。它使用的引擎是由莱茵金属的旧款军用AV引擎改造而来，可靠性和出力十分优秀。就是挤占的空间太大，民用的车壳无法提供军用AV的空间，导致其续航里程不太理想。",pr:44e3,tier:"优质",grp:""},{n:"飞马-IV",mf:"VMW",type:"浮空车",ra:"SR",seat:"4",sdp:"55/12",ter:"飞",spd:"15/36/54",top:"340km/h",endur:"400km",ds:"如果一位有点小钱的公司中层管理想要为自己弄一辆足够有排面的浮空车，它需要有流线型的镀金外壳、安静优雅的引擎、智能舒适的驾驶手感、以及偶尔可以飙到超高速进行远距通勤，那飞马4型绝对是他的首选。可惜的是，由于这一车型在家境小康的那些富人群体中很常见，也许你买了之后并不会让你成为富人群里最特殊的那一个……",pr:1e5,tier:"奢华",grp:""},{n:"白头鹰",mf:"泽塔科技",type:"浮空车",ra:"SR",seat:"2",sdp:"40/12",ter:"飞",spd:"20/50/80",top:"620km/h",endur:"600km",ds:"长相酷似旧时代战斗机的竞速型浮空车，采用了类似战斗机座舱的纵排式座位。它驾驶起来的手感也像是一架真正的战斗机，就连HUD和操作杆都是电影里的模样。操作它上手需要一段适应时间，也可以直接用神经链接驾驶。把这东西和别的浮空车停在一起，无论其他人开的是什么样的豪车，总会有不少目光聚焦在你的身上。",pr:18e4,tier:"奢华",grp:""},{n:"DELUXE-7",mf:"四方行",type:"浮空车",ra:"SR",seat:"4",sdp:"60/9",ter:"飞",spd:"13/26",top:"210km/h",endur:"600km",ds:"四方行公司在浮空车领域的成熟之作，承诺会彻底重新定义高端航电和极致奢华的概念。它配备了种类齐全的个人电子设备，安全装置和驾驶硬件，对这台浮空车来说没有哪样东西会是铺张浪费的。迷失于豪华的浮空车内部，在自动驾驶系统把你高速带往目的地时尽情享受全息娱乐系统。它造型优美，线条流畅，有着笨拙的地面载具绝无可能拥有的优雅。",pr:3e5,tier:"极奢",grp:""},{n:"旅行者1号",mf:"轨道航空",type:"浮空车",ra:"SR",seat:"2",sdp:"55/17",ter:"飞",spd:"18/130",top:"910km/h",endur:"710km",ds:"由轨道航空推出的空中跑车。用航空级钛合金铸造的车身，用太空站风格塑造的内饰，甚至配备了一台来自太空飞船的车载AI——至少广告词上是这么写的。不用购买昂贵的太空旅行票，也不需要额外的宇航员培训就可以享受的宇宙航行体验。其特制的引擎可以在4秒内加速到接近音速，最好准备好抗G的备用手段！",pr:43e4,tier:"极奢",grp:""},{n:"鹈鹕",mf:"贝尔-波音",type:"直升机",ra:"R",seat:"8",sdp:"80/15",ter:"飞",spd:"4/22",top:"120km/h",endur:"800km",ds:"常见于警用、消防和媒体记者的老式运载直升机，在部分第三世界国家还有被改装成军用的型号。它的货舱宽大，适用性广，可改造程度高，且有着比当代浮空车更高效率的醇2引擎。对于那些无法负担起重型浮空车的组织来说，它往往是性价比最高的选择。但它也拥有老式直升机的一切毛病，噪音大、速度慢、机动性差（相对于浮空车）、需要勤维护……总之，如果以上缺点你都不介意，那它绝对不会让你失望。",pr:96e3,tier:"奢华",grp:""},{n:"飞龙",mf:"贝尔-波音",type:"直升机",ra:"R",seat:"2",sdp:"40/12",ter:"飞",spd:"15/30",top:"170km/h",endur:"400km",ds:"一款轻量级的民用直升机，其最大的特色是主旋翼可以像无人机一样自由调整角度，因此机动性和操控性极为良好。它有两种款式，比较常见的款式使用了无人机的电动引擎。虽然功率和续航较差，但不失为一台价格实惠、坚固耐用的城市直升机。若要升级成醇2引擎，则需要额外花费5000eb（续航增加400km）.",pr:43e3,tier:"优质",grp:""},{n:"OAS-07 商务空轮",mf:"泽塔科技",type:"飞艇",ra:"R",seat:"20",sdp:"200/18",ter:"飞",spd:"6/14/ 20/28/35",top:"480km/h",endur:"3300km",ds:"你可以经常在世界各地的大城市上空看见它。在高楼大厦之间，那些悬浮的全息广告牌多半就挂在它们身上。不仅如此，它也是许多城市里常见的空中短途货运或是公共交通工具。如若日后的历史学家要为这个时代划定一个特征，那由OAS系列飞艇组成的全息天幕绝对是不可回避的一环。也多亏了它，那些高耸入云的高楼大厦们也开始兴建新的高楼通勤站台，既方便了浮空车主，也方便了市民通勤。",pr:"/",tier:"优质",grp:""},{n:"空中楼阁",mf:"吉拉法",type:"飞艇",ra:"SR",seat:"1000",sdp:"1000/22",ter:"飞",spd:"4/10/ 18/22/28",top:"280km/h",endur:"8000km",ds:"在这个时代，乘坐飞艇航行已经是一种乐趣。而空中楼阁是由吉拉法设计的超大型飞艇—AZ-08改装而来的空中游轮。通常飞行在离地1000~2000m左右的高度，环大陆航行。它满载的常规巡航速度通常在最大速度的一半，以便游客观赏风景，并尽量保持平稳。上面的设施琳琅满目，高空巡航的天上风景更是自带远超海景的体验。",pr:"/",tier:"顶奢",grp:""},{n:"“抹香鲸”",mf:"吉拉法",type:"飞艇",ra:"SR",seat:"400",sdp:"800/20",ter:"飞",spd:"8/16/ 24/38/46",top:"620km/h",endur:"10000km",ds:"厌倦了飞机和亚轨道运输机起飞时令人难受的负载以及天上各种各样的烦人规矩？同时你不是很在乎时间，想要更具性价比的机票和更加广阔的观景空间？那你绝对要试试看吉拉法的“抹香鲸”航班。这艘规模惊人的空中巨兽可以运输客人兼顾运货，在那些不太繁忙的线路，通常只会将中上层的甲板改造为客舱，而底舱则用来吊装集装箱。除了速度会比正常飞机慢一点之外，性价比要高不少，全世界的航空公司爱死它了。这东西飞一趟的利润，很多时候可比一艘小型货轮还高不少。",pr:"/",tier:"顶奢",grp:""},{n:"甲胄骑兵",mf:"泽塔科技",type:"浮空车",ra:"SR",seat:"6",sdp:"100/20",ter:"飞",spd:"8/19/32",top:"250km/h",endur:"700km",ds:"一款为商务人士准备的装甲浮空车，在经济性、效率和功能上做到了平衡上的极致。在一些不那么有钱的小企业那里非常受欢迎。这台浮空车有泽塔科技专门研发的航空碳纤维防护板和钛合金加固底盘，可以有效防御防空导弹和重机枪的直射。在其底盘上有一座折叠小型武器位，可以用以安放一挺重机枪，或是APS系统来进行自卫。",pr:14e4,tier:"奢华",grp:""},{n:"SP-290 引路者",mf:"IEC",type:"浮空车",ra:"SR",seat:"10",sdp:"80/17",ter:"悬浮",spd:"10/25/35",top:"220km/h",endur:"1000km",ds:"IEC为特殊用途专门研发的特种浮空车，从外观上看，只是一台平平无奇的面包车，但其身后的空间十分宽广，适合塞进定制的设备来作为特种车辆使用。根据不同的需求，可以作为中控指挥中心、电子战平台、移动式黑客节点、无人机母舰，甚至是轻型装甲车。它采用的航空型8引擎悬浮底盘可以在离地50cm的高度以220km的速度贴地飞行，也可以在应急时刻起飞到最高15米的高度，以180km/h的速度进行空中巡航。它自带炮艇式的全覆盖式防弹驾驶舱，没有车窗，只有外置摄像头投射周围的环境到驾驶舱内。",pr:21e4,tier:"极奢",grp:""},{n:"博爱号",mf:"阿斯特丽",type:"浮空车",ra:"SR",seat:"4",sdp:"90/22",ter:"飞",spd:"12/40/60",top:"380km/h",endur:"600km",ds:"你可以质疑法国人的其他方面，但你很难质疑法国人的审美。这款由军用浮空车改造而来的装甲浮空车专为那些频繁出入危险地带的商务人士准备，即便如此，它也具备了优雅的流线外形和红白相间的华丽配色。阿斯特丽的设计师认为在上面放置一个APS系统会“极大地影响整车的美观性”，于是为它安装了一个非常高级的电子干扰对抗装置，可以使来袭的导弹头失灵（遭遇来袭导弹时，投掷1d10，6+即可让让导弹失灵，每回合次数无限。）这也让它可以名正言顺地卖出比其他装甲浮空车更高的价格。",pr:4e5,tier:"极奢",grp:""},{n:"代达罗斯",mf:"IEC",type:"浮空车",ra:"SSR",seat:"4",sdp:"60/17",ter:"飞",spd:"18/40/70",top:"310km/h",endur:"700km",ds:"为顶级商业人士定制的高端浮空车，甚至使用了真金镶嵌在车体的外壳上，而车体的其他部分则俨然如一块白玉般光滑。仰仗于IEC独家的高超芯片技术，其内部搭载的AI智能程度几乎可以触及网络监察的底线，但IEC坚称他们和渡鸦微控合作的“座天使”AI助手是绝对安全合法的。这辆浮空车没有驾驶室，其内部空间看起来就像是一个小型的高级酒吧包间，为车主提供最舒适的旅行体验。AI助手不仅可以全盘管理驾驶事务，还会为车内的车主端茶送水，嘘寒问暖。甚至可以用提前预备好的材料为车主烹饪一顿完美的旅行餐，一定程度上比大部分公司高管的秘书都要能干。在遇到危险的时候，它会紧急为车主准备“抗压措施”，并以令人难以想象的动作闪躲来袭的导弹和子弹（视作一个拥有12反应，闪避18的个体）。",pr:69e5,tier:"顶奢",grp:""},{n:"联盟号",mf:"轨道航空",type:"浮空车",ra:"SSR",seat:"2",sdp:"55/20",ter:"飞",spd:"20/80/ 120",top:"750km/h",endur:"1060km",ds:"号称可以在超高空巡航的“空天浮空车”,被设计得极致优雅且美丽。它看起来就像是一枚水银铸造的飞船，连平时用来飞行的喷口也会在闲置的时候隐藏起来，以构成它流线型的优美外观。它采用全遮罩式的观察模式，没有车窗，但有一圈隐藏的摄像头拍摄周遭360°的影像并投影回车内。它有完全的自律AI承担自律驾驶功能，也可以通过神经链接来操作它的行动。有人会说亲自它的驾驶手感像一台战斗机，但要更加轻便灵活。这使得它在欧洲的许多浮空车竞赛项目中，总是能拔得头筹。",pr:5e6,tier:"顶奢",grp:""},{n:"ACJ730",mf:"阿斯特丽/ 轨道航空",type:"私人飞机",ra:"R",seat:"10",sdp:"140/18",ter:"飞",spd:"80/150",top:"900km/h",endur:"10000km",ds:"市面上较为常见的私人飞机，其宽广的燃料箱让它非常适合进行长途航行，且拥有非常令人讨喜的低调奢华风内饰。它的座椅可以折叠组合成一张舒适的床铺，并配有专门的服务AI为主人端茶送水。许多欧洲高管去美洲的分部开会时，只要不是紧急到需要亚轨道飞行器前往的会议，他们往往就会乘坐这种公务飞机慢慢飞过去，路上不仅有机会整理资料，还可以好好享受一番。",pr:26e5,tier:"顶奢",grp:""},{n:"晴空",mf:"贝尔-波音",type:"私人飞机",ra:"R",seat:"12",sdp:"100/15",ter:"飞",spd:"70/130",top:"873km/h",endur:"8300km",ds:"旧式设计的廉价私人飞机，基本上没有什么能够称作优点的地方，但也没什么太大的缺点。很适合一些手头有些余钱的百万富翁。许多中小型企业的高层管理都使用这种私人飞机进行出行访问，以至于成为了整间公司共用的公务机。",pr:17e5,tier:"顶奢",grp:""},{n:"鳐-0362",mf:"阿斯特丽/ 轨道航空",type:"私人飞机",ra:"SR",seat:"18",sdp:"150/15",ter:"飞",spd:"50/90/ 140",top:"890km/h",endur:"11800km",ds:"外观酷似鳐鱼的飞翼式客机，完全采用自动化驾驶技术。它的客舱是一个椭圆形的空间，可以完全改造成一间卧室或者一个会议室，乃至一个舞厅。让使用者可以拥有豪华游艇般的舒适体验。由于它优雅奇特的外观，加上实用性极高的内部空间，很多富豪都非常喜欢它。但保养它的价格非常昂贵，不是一般有钱人可以负担得起的。因此，这种客机在世界范围内的数量依旧相当稀少。",pr:74e5,tier:"顶奢",grp:""},{n:"涡流-SSBJ",mf:"苏霍伊",type:"私人飞机",ra:"SR",seat:"6",sdp:"120/20",ter:"飞",spd:"290/450",top:"2320km/h",endur:"6000km",ds:"这个相当狂野的设计将苏联过去一些退役的战斗机拆卸后重新组装成了公务客机。它有四个喷气式引擎，以及一个有些滑稽的长条形客舱。在各国都禁止平流层内超音速客机发展的今天，只有苏联还保留了这种超音速设计，以方便苏联和苏石化的领导层可以在全球范围内快速转移。因此这种公务机实际上只能在苏联的少数场合看见。据说乘坐它进行超音速巡航的体验不怎么愉快，毕竟它再怎么说也是一架战斗机的底子，对于那些脑满肠肥的老人家领导来说是在太不友好了。",pr:9e6,tier:"顶奢",grp:""},{n:"阿波罗-3",mf:"轨道航空",type:"私人飞机",ra:"SR",seat:"6",sdp:"140/20",ter:"飞",spd:"230/430 620/710",top:"3800km/h",endur:"13800km",ds:"相比于欧空局的那些亚轨道私人客机，阿波罗-3要更小，价格也更加“亲民”。至少那些不是金字塔尖的公司高管和中小企业CEO也可以买得起了。它的原理和普通民航类似，只是飞得更高，且速度更快。但缺点在于，乘坐它的体验并不算得上舒适，也难以在上面进行办公。而且它的空间十分紧凑，基本上没有多余的空间。即便有这般种种缺陷，拥有一艘亚轨道私人航天器还是现在不少富豪们的终极梦想。",pr:43e6,tier:"顶奢",grp:""},{n:"Skyrunner™",mf:"欧空局",type:"私人飞机",ra:"SSR",seat:"12",sdp:"90/24",ter:"飞",spd:"230/430 620/710",top:"4000km/h",endur:"15500km",ds:"天奔者™是欧空局针对顶尖富豪和国家级政要设计的亚轨道航天器，相比那些需要用火箭发射的亚轨道运输工具，它更加轻量化，也更加舒适。即便它的速度并没有那么快（亚轨道航天器通常可以达到第一宇宙速度）。为了考虑客户的舒适程度，它在起飞后的最初一小时内会在高空逐渐加速至突破音速，并以3~4马赫的时速在超高空巡航。它配备了完备的抗G手段，以确保每个乘客都能安全舒适地抵达目的地。对于那些想要刺杀他们的敌人来说，亚轨道也是一个相对难以拦截的目标。",pr:13e7,tier:"顶奢",grp:""},{n:"“鱼雷”警用拦截摩托车",mf:"昆达利尼",type:"摩托车",ra:"SSR",seat:"1",sdp:"50/19",ter:"陆",spd:"18/38",top:"220km/h",endur:"300km",ds:"飞镖摩托车的警用版：更重，更硬，更快。和民用版一样，它也有操控性上的小问题。鱼雷摩托车被用于各种单位的追捕任务。由于没有容纳囚犯的空间，它们通常会与一辆宝马罪犯运输车联合行动。因为它们那具有未来主义色彩的外观，鱼雷是电视上的警察节目中很受欢迎的载具。其上自带两个武器挂架，可以安装机枪，甚至是导弹。",pr:25e3,tier:"优质",grp:"装甲/军用"},{n:"科尔特斯 V6000 NCPD 霸王",mf:"维利福",type:"警车",ra:"SR",seat:"4",sdp:"130/19",ter:"陆",spd:"18/28",top:"160km/h",endur:"600km",ds:"专门为NCPD改良的科尔特斯车型。维尔福保证，霸王即使在最极端的条件下也能提供完全的安全保障。重型装甲车身可承受连续的枪击，其巨大的发动机可以清除临时路障等障碍物。在紧急情况下，操作人员可以将注意力集中在交火上，让汽车的中央计算机控制移动。此外，某些机密的工厂配发部件已被替换为军用技术和荒坂装甲车中常用的部件。在城市的街道上，它俨然已是一台动力强劲的装甲车。",pr:34e3,tier:"优质",grp:"装甲/军用"},{n:"轮入道",mf:"荒坂",type:"装甲车",ra:"SR",seat:"10",sdp:"150/20",ter:"陆",spd:"8/14/18",top:"80km/h",endur:"550km",ds:"“轮入道”是荒坂最出名的装甲车系列。曾在南美和非洲的一些战场上大放异彩。相比于军用科技的同系列装甲车，它要更加廉价且万金油。无论是城市镇暴还是战场突击，它都可以轻松胜任。这台装甲车有特别加装的重型底盘和防弹越野轮胎,窗户也是重型防弹玻璃（18sp15hp）。其上有一个中型载具武器槽可以用来加装小型机炮或是重机枪。",pr:3e5,tier:"极奢",grp:"装甲/军用"},{n:"AMX-45 雄狮",mf:"阿斯特丽",type:"装甲车",ra:"SR",seat:"8",sdp:"160/22",ter:"陆",spd:"6/12/16",top:"76km/h",endur:"600km",ds:"在非洲战场上常见的多用途轮式装甲车，拥有高度模块化的炮塔和底盘，可以随用户需求随时改造。在圣路易，警方使用的镇爆装甲车也同样使用它的底盘。它采用了无窗设计，将所有乘员都包裹在厚重的装甲中，仅通过外部摄像头采集信息。其炮塔是一个大型载具武器槽，可以用来安装从中型机炮到105mm口径榴弹炮在内的所有火力。",pr:43e4,tier:"极奢",grp:"装甲/军用"},{n:"BMP-7 obr.2033",mf:"苏石化",type:"装甲车",ra:"SR",seat:"11",sdp:"170/23",ter:"陆",spd:"5/10/15",top:"67km/h",endur:"700km",ds:"苏联上一代的履带式步战车，由于速度缓慢遭到了不少士兵的抱怨，但好处在于它在野外和复杂地形的机动性极强，且相对容易操作（载具驾驶+2）。然而机动性方面的缺点赋予了它厚重的装甲和强大的火力，它采用了无窗设计，仅通过摄像头观察外界。由于使用履带设计，所以无法瞄准它的轮胎，只有使用轻反器材以上火力才能击毁履带。其上有一个大型载具武器槽，通常用来安装重型机炮或者85mm俄制无后座炮",pr:4e5,tier:"极奢",grp:"装甲/军用"},{n:"轻骑兵-4",mf:"CCMMC",type:"装甲车",ra:"SR",seat:"6",sdp:"130/18",ter:"陆",spd:"14/20/27",top:"120km/h",endur:"800km",ds:"在中国、东南亚和东非地区常见的轻型装甲吉普车，使用了一款高性能的醇2引擎。它的起步速度、加速度和机动性都非常好，非常适合在城区内追击犯罪分子，或是在野外平原进行侦察。由于对机动性的追求，它在武装上的考量较为薄弱，且也容易在重火力伏击下被摧毁。它的窗户是重型防弹玻璃（18sp15hp），其上有一个中型载具武器槽可以用来安装镇爆装备或是小型机炮与重机枪。",pr:28e4,tier:"极奢",grp:"装甲/军用"},{n:"M70A1 “猎犬”轻型坦克",mf:"军用科技",type:"坦克",ra:"SR",seat:"4",sdp:"190/28",ter:"陆",spd:"10/18/24",top:"110km/h",endur:"900km",ds:"在第三世界的各大军阀库存和战场上，“猎犬”无疑是最受欢迎的轻型坦克款式之一，它虽然整体造型复古，且操作界面老旧，但它也足够简单易懂，一个没读过书的第三世界民兵只需要培训三个月就可以上手驾驶。它的特色是在平原地形的超高移速和那门88mm磁轨重炮，可以在伏击战中发挥巨大的战术优势。除了这门主炮以外，它还附带了一门M8B7同轴机枪，还可以在外部武器架上加装两发反坦克导弹。美中不足的是，它需要一名额外的装填手，且它的装甲在主战坦克里算不上强，甚至可以被使用穿甲弹的机炮轻易摧毁。",pr:92e4,tier:"豪华",grp:"装甲/军用"},{n:"AMX-68 查理曼",mf:"阿斯特丽",type:"坦克",ra:"SR",seat:"3",sdp:"200/30",ter:"陆",spd:"8/14/20",top:"90km/h",endur:"750km",ds:"适合在非洲草原上奔驰的轻型坦克，配备了强大的高悬挂越野履带和醇2引擎，其特色在于它使用的105mm速射弹匣炮，每个弹匣装有6发炮弹，可以在与主战坦克的对决中靠短时间的爆发火力取胜。然而其缺点在于当弹匣打完后它会有比普通坦克更长的火力空窗期（需要两个回合上弹），此时是它生存能力最为薄弱的时候。",pr:38e5,tier:"顶奢",grp:"装甲/军用"},{n:"T-18bvm “铁拳”主战坦克",mf:"苏石化",type:"坦克",ra:"SR",seat:"3",sdp:"250/32",ter:"陆",spd:"6/10/14",top:"65km/h",endur:"600km",ds:"苏石化武装部队上一代的主战坦克，在新一代T-30坦克横空出世后，这些老旧的，不适应时代的旧式坦克便大量进入了国际军火市场，仅留一部分升级款作为二线部队装备。它们配备的120mm滑膛炮已经不适应现代战场，但在许多第三世界战场和战乱地区的公司分部还是有着不错的销路。在非洲的WNS新闻曾经有过一段记者在“铁拳”坦克上进行战场实况拍摄的录像，也被苏石化拿来作为宣传广告。它自带的武装除了主炮以外，还有两门KPV重机枪，其中一门是同轴机枪。自带“午餐盒”爆反装甲（免疫一次30hp以上的伤害），额外花费60000eb还可以加装“指虎”主动防御（APS）系统。（面对来袭导弹和火箭弹时，投掷一枚d10，出7+成功拦截。每回合最多一次。）",pr:42e5,tier:"顶奢",grp:"装甲/军用"},{n:"泰坦",mf:"军用科技",type:"装甲车",ra:"SSR",seat:"11",sdp:"200/22",ter:"陆",spd:"8/16/20",top:"70km/h",endur:"600km",ds:"军用科技推出的重型履带式装甲突击载具，通常为各国的警方或者军方采购。也有一部分游民使用。它配备了强大的复合合金装甲，还为部分客户定制了特别的顶置无人炮塔。炮塔上可以安装两台M20-C机炮或者两挺双联重机枪，并附加两枚反坦克导弹（ACPA表），也可以安装一个重型火箭巢。一部分军阀甚至会将一门90mm磁轨炮安在上面，充当坦克使用。这辆车直到被摧毁之前都是超重甲，车身自带反应装甲（免疫一次30以上的伤害），它没有车窗，仅通过外置摄像头提供外部影像。额外支付60000eb可以加装“不朽”主动防御（APS）系统（被火箭弹和导弹攻击时，投掷一枚D10，出目7+成功拦截，一回合最多一次）。",pr:104e4,tier:"顶奢",grp:"装甲/军用"},{n:"Minamoto-40 “义经”",mf:"三菱菅生/ 荒坂",type:"坦克",ra:"SSR",seat:"2",sdp:"240/32",ter:"陆",spd:"12/18/24",top:"85km/h",endur:"700km",ds:"荒坂军工新时代最引人注目的军事成就，这台他们与三菱合作研发的坦克有四条可自由运动的履带，必要的时候还能当作机械足使用。使其在山地和林地等复杂地形有难以想象的高机动能力，同时还可以做出原地漂移等夸张的高难度机动动作。在第四次公司战争后的一些零星冲突中，军用科技士兵甚至报告过这些坦克能爬到高楼废墟上进行射击。这台坦克配备了一门102mm磁轨速射主炮和两台赤鬼机枪，自带的“折雀”主动防御（APS）系统甚至可以拦截磁轨炮弹（被火箭弹、导弹和炮弹攻击时，投掷一枚D10，出目5+成功拦截，一回合最多三次）。",pr:97e5,tier:"顶奢",grp:"装甲/军用"},{n:"M10A3 SEPv2 “悬浮壁垒”",mf:"军用科技",type:"坦克",ra:"SSR",seat:"3",sdp:"280/38",ter:"悬浮",spd:"4/20",top:"60km/h",endur:"550km",ds:"在军用科技2041年展览会之前，没人想过浮空车的悬浮技术可以被应用到坦克身上，直到军用科技用M10A3坦克让大家大开眼界。这台坦克的旧式车体还是传统履带，但在这一代，它可以用离地70cm的高度贴地飞行，并免疫反坦克地雷的伏击。它自带一门150mm重型磁轨主炮，一挺M20C机炮和两挺MH17机枪。自带的龙鳞式爆反装甲可以免疫三次30以上的伤害，同时附带的“龟甲阵”主动防御（APS）系统可以用极高的效率点杀来袭的导弹和火箭弹，但对于炮弹的防御较为疲软。（被火箭弹和导弹攻击时，投掷一枚D10，出目4+成功拦截，一回合最多两次）",pr:102e5,tier:"顶奢",grp:"装甲/军用"},{n:"HKP-33a2 “城市猎手”",mf:"IEC",type:"坦克",ra:"SSR",seat:"3",sdp:"300/40",ter:"陆",spd:"8/16/22",top:"72km/h",endur:"600km",ds:"在第四次公司战争中，主要发生的战斗场地都在城市、街巷等紧凑空间。IEC的许多珍贵公司财产也位于这些地方。为了应对这种新时代的战争形势，也为了解决困扰过去参谋们的巷战难题，IEC开发了这款令人瞩目的昂贵战争机器。它的复合式轮履一体设计可以让它在城市地区高速机动，也能高效越过废墟和路障。它的主炮是一门角度有限的130mm磁轨炮，还有两门可以自由转动角度的60mm磁轨速射炮塔，每一台都附带了额外的同轴机枪。它最特别的地方在于那台位于其扁平车身后部的“海伯利安”巷战雷达，开机后可以穿过钢筋混凝土墙壁，让方圆5km内的目标无所遁形。并用其两侧的垂直微型导弹发射器（共20发）对这些目标进行攻顶打击。同时，它还附带IEC研发的巷战型反应装甲（免疫两次40以上的伤害）和“冈格尼尔”主动防御（APS）系统，能有效拦截来袭的导弹和火箭弹（被火箭弹和导弹攻击时，骰一枚D10，出目4+成功拦截，一回合最多两次）",pr:11e6,tier:"顶奢",grp:"装甲/军用"},{n:"SH-45 巡逻执法者",mf:"贝尔-波音",type:"直升机",ra:"R",seat:"2",sdp:"40/16",ter:"飞",spd:"8/30/50",top:"300km/h",endur:"500km",ds:"经济实惠的警用直升机，是贝尔一款民用直升机的改型。它操作灵敏，体型小巧，非常适合在高楼林立的城市里执行任务。虽然性价比很高，但它的装甲薄弱，很容易被重火力击毁。因此它往往会停留在稍远的距离对街区进行火力支援。它常见的武装是两挺分别挂在两侧的MH17通用机枪（视为双联武器），也可以花费4000eb升级为碎人者加特林。",pr:68e3,tier:"奢华",grp:"装甲/军用"},{n:"空中哨兵",mf:"VMW",type:"浮空车",ra:"R",seat:"5",sdp:"50/20",ter:"飞",spd:"10/25/35",top:"260km/h",endur:"570km",ds:"为了应对新时代的多样化应急情况，VMW为警察、安保公司和空艇护卫研发了这一款轻型装甲浮空车。在装甲和速度之间的平衡上给出了最好的答案。它是一款模块化的装甲浮空车，具有非常丰富的可自定义挂载点。其顶部和底部各设计了一个中型武器槽，可以用来挂载机枪和榴弹机枪。还可以用来搭载提供额外续航（+100km）的挂载油箱，或者用来反导弹的APS系统。外部的一些卡槽可以用来安装额外装甲（+10hp,+2sp，-30km/h最大时速。）它们出现在城市的上空时，通常象征着安全和保护，许多生活在市中心附近的人，正是因为看见了它们的身影才滋生了加入警队的想法。",pr:86e3,tier:"奢华",grp:"装甲/军用"},{n:"AC-665 皇家骑士",mf:"阿斯特丽",type:"炮艇",ra:"SR",seat:"2",sdp:"150/22",ter:"飞",spd:"7/40/65",top:"520km/h",endur:"650km",ds:"这艘炮艇最大的特色便在于它真的有一杆“皇家骑枪”式105mm多功能磁轨炮悬挂在它的下方，它可以用来发射炮射导弹，或者单纯发射无制导高爆榴弹来作为战场支援火力使用。由于它使用多段电容轮流来进行充能，因此它的射速甚至可以和同口径的舰炮媲美(ROF上升至2)。然而这一阿斯特丽的专利技术在在出口时几乎可以达到它的一半价格，因此其出口款通常不会配备这种高端技术。除此之外，它的机翼上还有两个普通挂载点，用以挂载8发火箭巢或者双发导弹，以作为炮艇的支援火力。",pr:82e5,tier:"顶奢",grp:"装甲/军用"},{n:"赫拉克勒斯",mf:"泽塔科技",type:"炮艇",ra:"SR",seat:"8",sdp:"90/22",ter:"飞",spd:"12/30/60",top:"310km/h",endur:"670km",ds:"泽塔科技为私人安保武装特别设计的武装炮艇，也有一部分被NCPD和各国疯控小队采购。作为军用的炮艇它们显得有些过于简陋，但要是用来对付负隅顽抗的重装罪犯，已经绰绰有余了。这种炮艇自带一门位于底部的双联.50机枪炮塔和一挺顶部的榴弹机枪，还额外留下一个重型武器支架，用来安装对地导弹或重型火箭巢。相对于市面上常见的那些炮艇，它不附带雷达，装甲也有些脆弱。但毕竟一分钱一分货，你也不能多强求什么了。",pr:37e5,tier:"顶奢",grp:"装甲/军用"},{n:"MI-60",mf:"苏石化",type:"炮艇",ra:"SR",seat:"8",sdp:"150/20",ter:"飞",spd:"6/18/28",top:"280km/h",endur:"600km",ds:"一款来自第四次公司战争时期的旧式武装炮艇，现已从苏石化的军队中退役，仅有少数还在装备二线部队。但在海外，它往往是那些警察和军阀武装的经济之选。毕竟也不是所有人都能买得起则泽塔科技和军用科技的先进炮艇。它装备了军用规格的防弹玻璃（18sp20hp），一挺Gsh-33航空机炮，额外附带的挂载点也可以用来搭载两座32发航空火箭巢。它最大的特点在于其后备的乘员舱可以额外搭载6名士兵或者两台ACPA抵达前线，偶尔也会被创伤小组用来作为战区的贵宾营救。它的标配是旧式的俄军陆战雷达，只能侦测位于10km内位于旷野中的目标，无法探测房区内的活体目标。",pr:53e5,tier:"顶奢",grp:"装甲/军用"},{n:"前卫",mf:"泽塔科技",type:"炮艇",ra:"SSR",seat:"20",sdp:"200/25",ter:"飞",spd:"8/25/50",top:"470km/h",endur:"1200km",ds:"从第一辆浮空车诞生的那天起，新美国的研发人员就在为设计一台足够可靠的空中巴士而想破了脑袋。最终，泽塔科技公司给出了他们的解决方案，他们推出了前卫。这个庞然大物能够迅速地将一整个排的士兵运送到敌后。尽管它的设计主要考虑的是人员运输，但它也同时配备了“羽翼”主动防御（APS）系统，足以可靠地抵御敌人的伏击（面对导弹和火箭弹攻击时，投掷D10，出目7+拦截成功，每回合一次。）。在2069年，泽塔科技在这一型号的基础上设计了“勘测员”，并成功引领了新时代空中巴士的设计标杆。",pr:83e5,tier:"顶奢",grp:"装甲/军用"},{n:"狮鹫",mf:"军用科技",type:"炮艇",ra:"SSR",seat:"10",sdp:"180/27",ter:"飞",spd:"20/40/80",top:"500km/h",endur:"880km",ds:"第四次公司战争的经验迫使军用科技开始开发更加适应巷战环境的武装炮艇。在军用科技的2041年博览会上，“狮鹫”一经展出，就获得了来自世界各地的广泛订单。就连NCPD也一口气订购了8架，作为暴恐机动队的突击装备。有些议员声称花费巨款购买这样的军用设备给警方使用完全是铺张浪费，但狮鹫很好地在几次突击行动中证明了自己的价值——那些对它开火的目标都在顷刻间被打成了肉泥。狮鹫安装了两挺GAU-27重型航空加特林（同ACPA表20MM加特林），两个折叠的16发智能火箭巢（可更换为其他类型的导弹），并有特别的电子战诱导系统迷惑来袭导弹（遇到来袭的导弹时，投掷D10,出目6+使其偏航，每回合次数无限。）它使用全复合装甲包裹的驾驶舱，仅通过外置的摄像头观察战场环境，而宽敞的乘员舱更是能塞下四台ACPA进行空降作战。此外，它可以装配空战雷达或者陆战雷达，也可以多花费100000eb安装军用科技最新研发的巷战雷达.它可以穿透墙壁，侦测3km范围内的一切活体目标。",pr:98e5,tier:"顶奢",grp:"装甲/军用"},{n:"ka-67m “虎鲨”",mf:"苏石化",type:"直升机",ra:"SSR",seat:"2",sdp:"100/22",ter:"飞",spd:"26/48",top:"410km/h",endur:"600km",ds:"苏联的先进浮空炮艇，虽然整体上依然是传统直升机的外形设计，但采用了更先进的浮空矢量引擎，额外的挂载翼让它看起来像是一台喷气式战斗机，事实上你很难把它和一架垂直起降战机做出分别。它有一台双联装30mm机炮（500发备弹）作为主武器，同时在机翼和机腹下方共有五个挂架可以用来悬挂不同的武装。最常见的配置是在两翼悬挂两枚32发火箭巢和两枚4联装反坦克导弹，并在机腹悬挂一发1000kg制导炸弹/反舰导弹，也可以用来携带火控吊舱或是雷达/电子战吊舱来保证更高的精准度和生还率。是当代火力最为充足的炮艇之一。",pr:15e6,tier:"顶奢",grp:"装甲/军用"},{n:"DELTA-6 “蝰蛇”",mf:"军用科技",type:"直升机",ra:"SR",seat:"1",sdp:"60/22",ter:"飞",spd:"8/18/42",top:"300km/h",endur:"800km",ds:"有什么事情是直升机能做到，而浮空车做不到的？军用科技的“蝰蛇”攻击直升机将告诉你答案。它体积轻巧，有着几乎静音的突击旋翼引擎，还有像梭鱼一般的尖利外形，通过神经链接直连的棺式驾驶舱，两个可折叠的小型火箭巢/导弹挂载点，还有那门位于机首的37mm机炮（150发备弹），几乎可以说整台直升机就是围着它建造的。不仅可以对步兵造成毁灭性的打击，面对ACPA小队和轻装甲联队也能像割草一样轻松收割。它的缺点也显而易见：过于轻巧的机体让它无法装配过重的装甲，且牺牲的内部空间都用来存放武装。一旦被防空导弹命中，它将会变成天上最灿烂的烟花。",pr:67e5,tier:"顶奢",grp:"装甲/军用"},{n:"Mi-37E “驼鹿”",mf:"苏石化",type:"直升机",ra:"SR",seat:"50",sdp:"300/25",ter:"飞",spd:"5/15/30",top:"200km/h",endur:"1500km",ds:"苏石化引以为傲的超重型的双旋翼运载直升机，里面可以整整塞进一个排的士兵还有大量弹药物资。时至今日依然是苏石化空降突击部队的主要载具。相比技术尚不成熟的运载型AV和笨重的大型飞艇，这种性能强劲的旧式设计还有不少它的用武之地。但它的武装较弱，大部分时候只会在头部和尾部各加装一台重机枪，只有在苏联航母上服役的改进型号会携带鱼雷和反潜雷达进行反潜任务。",pr:214e5,tier:"顶奢",grp:"装甲/军用"},{n:"V-30 雁式",mf:"贝尔-波音",type:"直升机/ 浮空车",ra:"SSR",seat:"32",sdp:"130/20",ter:"飞",spd:"20/50/90",top:"600km/h",endur:"1000km",ds:"新美国海军陆战队和空军现役的战场运输载具，已经服役了20多年，是有口皆碑的战场出租车。它是在旧鱼鹰的设计上结合了重型浮空车矢量引擎制出的杰作，同时调整了外形，让它可以一定程度上减少被雷达探测的范围，还比旧鱼鹰机动性更高，速度更快。它通常不配备武装，只装配两挺碎人者加特林在机腹。除此之外，它还配备了一个额外的电子反制系统，可以干扰来袭导弹（遇到来袭的导弹时，投掷D10,出目6+使其偏航，每回合次数无限。）",pr:23e6,tier:"顶奢",grp:"装甲/军用"},{n:"VC-230U “战争骑士”",mf:"贝尔-波音",type:"炮艇",ra:"SSR",seat:"6",sdp:"180/20",ter:"飞",spd:"20/40/70",top:"500km/h",endur:"1000km",ds:"由雁式设计作为基底改装而成的重型空中炮艇，整体上要比雁式大上一圈。它上面挂满了各式武装，用以进行最高效率的对地支援。就连欧洲国家都有不少采购它来在第三世界战斗时进行高效率的火力投送。它有两门105mm重型榴弹炮，两门88mm电磁榴弹炮，四门20mm加特林，以及两个四联装的对地导弹挂架/16发垂射智能火箭巢。它上面能搭载最多四名炮手，用以操作不同的武器系统，由于它采用神经链接系统，所以理论上一名炮手也可以进行操作，只是会造成非常巨大的神经压力。炮手们每次只能用一半的武装同时对地支援，并可以用先进热成像和指向性对地穿墙雷达来判断敌方所在的位置，只要能确保制空权，它就能确保地面只剩一片焦土。此外，它和标配的雁式一样，配备了一个电子反制系统，可以干扰来袭导弹（遇到来袭的导弹时，投掷D10,出目6+使其偏航，每回合次数无限。）",pr:3e7,tier:"顶奢",grp:"装甲/军用"},{n:"暴风雨",mf:"阿斯特丽/ 轨道航空",type:"战斗机",ra:"SSR",seat:"1",sdp:"120/22",ter:"飞",spd:"320/500",top:"2988km/h",endur:"2500km",ds:"法国空军的多用途垂直起降战斗机，总体性能平庸，且不能隐形。但以极高的性价比和机动能力闻名。它牺牲隐形能力换来的是机翼+机身的7个挂架，以及一门位于机首的30mm航空机炮。从远距空空导弹到2000磅卫星制导炸弹，都可以挂在它的挂架上。尽管在模拟演习中和军用科技的顶级战斗机1V1空战的时候总是落于下风，可有赖于阿斯特丽和轨道航空共建的多维信息支援系统，只要它成群结队从各个角落出击，即便是面对等量的军用科技战斗机，也会拥有更高的胜利概率。",pr:65e6,tier:"顶奢",grp:"装甲/军用"},{n:"鸦天狗",mf:"荒坂",type:"战斗机",ra:"SSR",seat:"1",sdp:"100/20",ter:"飞",spd:"250/800",top:"4623km/h",endur:"2000km",ds:"日本自卫队和荒坂的现役战斗机。与其说是战斗机，不如说它更接近“拦截机”定位。它小巧玲珑的机身搭载了一台强大的矢量引擎，可以在加力燃烧时加速到接近4马赫的时速，同时保持极度高超的机动性，甚至可以在极限距离下躲过敌人发射的导弹。至于驾驶员……由荒坂培训的驾驶员一般来说只有脑子塞在这东西的羊水驾驶室，因此赛博精神病发率高得吓人。它只有两个挂载点位于机腹，通常是用来挂载“紫电-7”型远距空空导弹，也可以用来挂载空地导弹。若使用“野兽模式”的改装方案，还可以在它的机翼上多出两个额外的挂载点。它专用的“紫电-7”导弹是一种高超音速远距拦截弹，只要在它的射程内被锁定，留给敌方飞行员的反应时间往往只有不到五秒。",pr:76e6,tier:"顶奢",grp:"装甲/军用"},{n:"SU-59",mf:"苏霍伊",type:"战斗机",ra:"SSR",seat:"2",sdp:"220/24",ter:"飞",spd:"100/400",top:"1956km/h",endur:"3800km",ds:"苏联空军在新时代研发的三发动机超重型战斗轰炸机，拥有新一代战斗机里最大的体积和重量，也拥有现代战斗机最大的空中挂载能力（虽然只有7个挂载点，但其所有的挂载能力翻倍）。它可以用机腹的挂载点挂载一门极其骇人的90mm航空磁轨炮，不仅可以用它发射12马赫的超高音速制导炮弹点杀空中目标，也能使用超压高爆弹以极高效率对地支援。它通常只执行对地任务，但如果要执行对空拦截任务，它会在搭载远距空空导弹的同时，额外搭载一架“蛇-7”隐身无人僚机，该僚机可以搭载两枚中距空空导弹或者一枚远距空空导弹，由坐在SU-59副驾驶的武器官操控。敌机还在努力靠近SU-59的时候，往往就在不明不白中被僚机发射的导弹，或者电磁炮的高超音速炮弹摧毁了。",pr:"非卖品",tier:"顶奢",grp:"装甲/军用"},{n:"F-99 日冕",mf:"军用科技",type:"战斗机",ra:"SSR",seat:"1",sdp:"140/23",ter:"飞",spd:"200/600",top:"3004km/h",endur:"3200km",ds:"如果你想要在市面上挑选一架最棒的战斗机，那军用科技的F-99日冕是毫无争议的第一，但它的价格足够让大多数买家望而却步了。即便如此，也有一些国家（主要是英国）硬着头皮订购了一些，用以抵御欧洲大陆和殖民地附近的威胁。虽然它的机动性在主流战斗机中算不上拔尖——可现在有谁家的战斗机会在空战中考虑机动性？它的优越性在于它内置的“黑洞”电子战系统和它的新材料空战雷达，“黑洞”电子战系统能直接屏蔽10km半径的空域信号，让敌方的AWACS无从寻找自身的痕迹，也无法引导导弹攻击自己。它的雷达可以在500km的范围外发现敌机，并发射高超音速空空导弹进行拦截。敌人根本来不及侦测到它（更何况它还是隐形的）就被击毁了。如果它要执行对地任务，那它的5个挂架也可以用来搭载对地导弹或者1000磅激光制导巡航炸弹。",pr:96e6,tier:"顶奢",grp:"装甲/军用"}],vehmods:[{n:"履带化改造",mf:"/",slot:"1",size:"M/L",part:"底盘",ds:"将底盘改造为履带，速度减去四分之一（包括最大时速），但你在复杂地形上驾驶时不会受到任何减值。且除非被轻反器材穿甲等级及以上的武器瞄准，否则不会因为履带断裂而导致驾驶技能降低。",pr:"",tier:"",ra:"",grp:"机动系统"},{n:"浮空车化改造",mf:"/",slot:"2",size:"S/M",part:"底盘",ds:"将底盘改造为浮空车底盘，续航里程减半，但你可以飞行至最高离地十米的高度，你驾驶该载具使用的技能从地面载具驾驶更改为飞行载具驾驶。",pr:"",tier:"",ra:"",grp:"机动系统"},{n:"加强刹车板",mf:"/",slot:"1",size:"S",part:"引擎",ds:"更加灵敏的让你在应急时刻可以迅速让车辆减速、急停。在进行“紧急制动”、“急转弯”、“甩尾”的汽车特技时，你的检定+2。",pr:"",tier:"",ra:"",grp:"机动系统"},{n:"电动引擎",mf:"/",slot:"/",size:"S/M/L",part:"引擎",ds:"将引擎改成电动引擎，可以让油箱的弱点消失，但是攻击车体正面的引擎和底盘将会造成额外0.5倍的伤害，且续航里程减少四分之一",pr:"",tier:"",ra:"",grp:"机动系统"},{n:"醇二引擎",mf:"/",slot:"/",size:"S/M/L",part:"引擎",ds:"将引擎改成电动引擎，增设油箱的弱点（-8，瞄准时造成2倍伤害），但是车体正面的引擎护甲等级上升一级。",pr:"",tier:"",ra:"",grp:"机动系统"},{n:"燃油引擎",mf:"/",slot:"/",size:"S/M/L",part:"引擎",ds:"将引擎改成电动引擎，增设油箱的弱点（-8，瞄准时造成2倍伤害），但是车体正面的引擎护甲等级上升一级。",pr:"",tier:"",ra:"",grp:"机动系统"},{n:"悬浮底板",mf:"/",slot:"1",size:"M/L",part:"底盘",ds:"将轮子拆掉，更改为类似浮空车的悬浮底盘。相比浮空车用的底盘，悬浮底盘更加省油，且可以安装在大型车辆上。使用了悬浮底盘的车辆可以离地30~50cm飞行，无视复杂地形进行行驶，但不能真正飞行，续航里程减少四分之一。",pr:"",tier:"",ra:"",grp:"机动系统"},{n:"肌肉化引擎",mf:"/",slot:"1",size:"S/M/L",part:"引擎",ds:"为引擎增添额外的汽缸，使其动力更加强劲。载具的最高时速增加20km/h，战斗速度+2，不能安装在跑车上。",pr:"",tier:"",ra:"",grp:"机动系统"},{n:"扩容油箱",mf:"/",slot:"1",size:"S/M/L",part:"引擎",ds:"不能安装在电动车上，使续航里程增加50km/100km/200km。（对应S//M/L）",pr:"",tier:"",ra:"",grp:"机动系统"},{n:"额外排气口",mf:"/",slot:"1",size:"S",part:"引擎",ds:"增添额外的排气口，使战斗速度+1，不能安装在电动殷勤的载具上。",pr:"",tier:"",ra:"",grp:"机动系统"},{n:"氮气舱",mf:"/",slot:"1",size:"S/M/L",part:"引擎",ds:"在驾驶中免费发动，可以让当回合汽车的战斗速度+4，但驾驶技能-2。",pr:"",tier:"",ra:"",grp:"机动系统"},{n:"棺式驾驶舱",mf:"/",slot:"1",size:"M/L",part:"驾驶舱",ds:"取消了传统的操作方式，使用神经链接直连！仅通过外部的摄像头将画面传输至驾驶员的脑海中进行驾驶，驾驶技能+4。除此之外，还给了驾驶员额外的防护。安装了此项改造后，敌方不可直接瞄准驾驶员，只能瞄准驾驶舱。基础的棺式驾驶舱视作拥有16sp，20sdp，必须要击破驾驶舱的防护才能击中驾驶员。是部分驾驶舱防御改造的前提条件。",pr:"",tier:"",ra:"",grp:"基本改造"},{n:"人体工程学式飞控操作台",mf:"/",slot:"1",size:"M/L",part:"驾驶舱",ds:"类似浮空车和飞机的智能操作系统，可以让驾驶者舒服地躺在座椅上，用智能目镜链接车体的监视系统或是无人机来观察周围的情况，并使用类似游戏手柄的操作杆来进行驾驶。极大地缓解了公路驾驶的疲劳。驾驶技能+2，但一旦车身的观瞄系统报废，或是无人机被摧毁，驾驶员在当回合不能进行任何操作，需要过一个DV15的专注检定才能保证车辆不失控。",pr:"",tier:"",ra:"",grp:"基本改造"},{n:"自律化改造",mf:"/",slot:"1",size:"S",part:"驾驶舱",ds:"将车辆改造为自动驾驶，可以在市区内匀速平稳地抵达目的地，视为一个拥有10驾驶技能的驾驶者。但这种做法难以应对突发情况。",pr:"",tier:"",ra:"",grp:"基本改造"},{n:"智能驾驶舱",mf:"/",slot:"1",size:"S",part:"驾驶舱",ds:"去掉传统的方向盘、挂档器、油门和刹车，只有一个直连驾驶员神经链接的插口，让驾驶员可以像操作自己身体一样操作这辆载具。但它的舒适度完全无法和更加智能、舒适的棺式驾驶舱比较。驾驶技能+3。",pr:"",tier:"",ra:"",grp:"基本改造"},{n:"额外座椅",mf:"/",slot:"1",size:"M",part:"尾舱",ds:"为车辆额外添加两个座椅，但牺牲了后舱的空间，无法将后舱改造为其他形态。",pr:"",tier:"",ra:"",grp:"基本改造"},{n:"车载工坊",mf:"/",slot:"/",size:"M/XL",part:"尾舱",ds:"将尾厢的类型替换为一座大型工坊，技工可以在里面制造、升级物品。但不可用来制造载具。XL级的工坊可以花费400000eb升级为高级精度车床工坊，但依旧不能用来制造载具。",pr:"",tier:"",ra:"",grp:"基本改造"},{n:"运兵舱",mf:"/",slot:"/",size:"L/XL",part:"尾舱",ds:"将尾厢的类型替换为一个可以运输士兵和ACPA的运输舱，可以运输6/12（L/XL）名士兵，一台轻或中型ACPA占据3个座位，1台重型ACPA占据6个座位。",pr:"",tier:"",ra:"",grp:"基本改造"},{n:"弹药库",mf:"/",slot:"/",size:"M/L",part:"尾舱",ds:"在车舱内为武器增添一个储存弹药的仓库，可以为装配在车上的4个武器系统提供2个弹匣的备用弹药。（若是单发装填武器，则提供4发。）装配在L级的车舱上时，可提供的弹药量翻倍。",pr:"",tier:"",ra:"",grp:"基本改造"},{n:"商务车厢",mf:"/",slot:"/",size:"M",part:"尾舱",ds:"将尾厢的类型替换为一个小型商务会议室，附带了酒架、真（克隆）皮沙发、豪华地毯、全息投影装置和超梦目镜。同时加强了车厢的隔音性能，让任何秘密都能留在车厢之内。",pr:"",tier:"",ra:"",grp:"基本改造"},{n:"车斗",mf:"/",slot:"/",size:"M/L/XL",part:"尾舱",ds:"将尾厢的类型替换为露天的车斗，使其可以装载货物，或者作为一个中型炮塔的平台使用。（如果是L级的车舱，则可以作为重型炮塔的平台。）",pr:"",tier:"",ra:"",grp:"基本改造"},{n:"货舱",mf:"/",slot:"/",size:"M/L/XL",part:"尾舱",ds:"将尾厢的类型替换成无座的货舱，用来装载更多货物，同时保持隐蔽。作为无人机巢时，使搭载的无人机量翻倍。若是L级别的货舱，则搭载的无人机量翻四倍",pr:"",tier:"",ra:"",grp:"基本改造"},{n:"撞角",mf:"/",slot:"",size:"S/M/L",part:"车头",ds:"为车头添加一个冲撞用的铲斗，当以撞击的方式伤害他人或载具时，你造成伤害的骰子上升一级。（D4改为D6，D6改为D8，最高D20）",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"前装武器",mf:"/",slot:"",size:"S/M/L",part:"车头",ds:"在车头位置添加一个安置武器的槽位。在S级别的车头上只能安装机枪和重武器以外的步兵武器，在M和L的车头上可以安装一切步兵武器，但以此方式安装的武器只能朝正面开火。",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"小型炮塔",mf:"/",slot:"",size:"S/M/L",part:"车顶",ds:"在车顶（浮空车则可以安装在车底）添加一个可以安装步兵武器的小型炮塔，可以在上面装配任何单兵武器。",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"中型炮塔",mf:"/",slot:"",size:"M/L",part:"炮塔",ds:"在车顶（浮空车则可以安装在车底）添加一个可以安装武器的中型炮塔，可以在上面装配一挺双联装的单兵武器（ROFx2，全自动骰数+1，最大乘数+1,精准-2，价格x2）,或者一挺小型载具武器。",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"重型炮塔",mf:"/",slot:"",size:"M/L",part:"炮塔",ds:"在车顶（浮空车则可以安装在车底）添加一个可以安装武器的重型炮塔，可以在上面装配一挺四联装的单兵武器（ROFx4，全自动骰数+2，最大乘数+2,精准-2，价格x4）,或者一挺双联装的小型载具武器，或者一挺中型载具武器。同时可以在其顶部安装一个小型炮塔，以及一门同轴机枪",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"坦克炮塔",mf:"/",slot:"",size:"XL",part:"炮塔",ds:"在车顶（浮空车则可以安装在车底）添加一个可以安装步兵武器的坦克炮塔，可以在上面装配一挺四联装的小型载具武器，或者一挺双联装的中型载具武器，或是一挺重型载具武器。同时可以在其顶部额外安装一个中型炮塔，以及一门同轴机枪。",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"外挂武器点",mf:"/",slot:"",size:"M/L",part:"特殊",ds:"在外部空间额外增设一个武器挂载点，但只能用来挂载单兵火箭筒、导弹等重型武器。",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"无人式炮塔",mf:"/",slot:"",size:"",part:"尾舱",ds:"让你的炮塔智能化，你的乘员可以呆在安全的位置操作炮塔，而不需要冒着生命危险来到炮塔上进行操作。",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"自律化炮塔",mf:"/",slot:"",size:"M/L",part:"尾舱",ds:"让你的炮塔更加智能化，乘员只需要在智能链接的HUD上标记敌方单位，炮塔就能自动对该单位开火。炮塔的战斗技能为14，加价2000可以购买高级战斗芯片，升级到16。",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"加强弹链",mf:"/",slot:"",size:"M/L",part:"特殊",ds:"让你的车载武器弹匣容量翻倍。不可安装在单发装填的武器系统上。",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"自动装弹机",mf:"/",slot:"",size:"M/L",part:"尾舱",ds:"让你的武器可以自动装填，无需人力辅助。你载具上的武器系统可以直接使用弹药库里的弹药。",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"加固底盘",mf:"/",slot:"",size:"M/L",part:"底盘",ds:"该载具SDP+10/20（分别对应M和L载具）。",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"重型轮胎",mf:"/",slot:"",size:"S/M/L",part:"底盘",ds:"除非被轻反器材及以上的武器瞄准轮胎，否则不会因为轮胎爆裂而导致驾驶技能降低。只能安装在使用轮胎的陆行载具上。",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"加固油箱",mf:"/",slot:"",size:"S/M/L",part:"引擎",ds:"被瞄准该部位时，造成的伤害倍数-0.5倍。",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"民用无人机栖木",mf:"/",slot:"",size:"S",part:"车顶/尾舱",ds:"搭载了一架小型无人机（见无人机表萨瓦纳雀），使用无线供电，飞越在车顶上方大约2~5m高度，为周边100m以内的车况提供全周视野。无人机最高保持100km/h的时速，若超过该时速，无人机会和车辆断链。",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"无人机巢",mf:"/",slot:"",size:"M/L",part:"车顶/尾舱",ds:"在车顶放置或将尾舱改造为一个可以释放无人机群的巢穴，可以储存8/16（对应M/L）架中型无人机，每一台无人机可以自编程飞行或者通过无人机指挥平台进行链接，执行多种不同任务。",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"巡航无人机巢",mf:"/",slot:"",size:"M/L",part:"车顶/尾舱",ds:"在车顶放置或将尾舱改造为一个可以释放无人机群的发射管，可以储存4/8架中型巡航无人机，巡航无人机同防空导弹或反坦克导弹，可以搭载不同的弹头，并以自毁的方式完成任务。",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"探照灯",mf:"/",slot:"",size:"S/M/L",part:"特殊",ds:"安装一个可以自由操作的大功率探照灯，指向25m以内的目标时，目标需要过一个DV14的反应检定，失败则受到眼睛受损的严重伤势三回合。以此方式造成的严重伤势不会造成额外伤害。",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"民用雷达",mf:"/",slot:"",size:"M/L",part:"车顶",ds:"民用车辆装备的载具雷达，单纯用以辅助行驶使用。可以侦测100m内无遮挡的载具、行人和无人机目标。",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"野战雷达",mf:"/",slot:"",size:"M/L",part:"车顶",ds:"军用载具的野战雷达，用以侦测5km内无遮挡的载具、人性轮廓和建筑物。若在空中50m以上高度使用，则侦测距离翻倍。",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"对空雷达",mf:"/",slot:"",size:"M/L",part:"车顶",ds:"地面防空设备和空中载具使用的纳米波对空雷达，可以在10km距离内侦测空中载具，在2km内侦测中小型无人机。若在空中50m以上高度使用，则侦测距离翻倍。",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"巷战雷达",mf:"/",slot:"",size:"M/L",part:"车顶",ds:"",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"信号天线",mf:"/",slot:"",size:"S/M/L",part:"车顶",ds:"常用的民用信号中继天线，绝大部分车辆的天线都被隐藏在车体里，但你也可以在车顶上安装一个看起来像卫星天线的大锅，确保你开到南极都还能享受满格的信号。",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"间谍天线",mf:"/",slot:"",size:"M/L",part:"车顶",ds:"",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"劫持天线",mf:"/",slot:"",size:"M/L",part:"车顶",ds:"",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"C-9981车用环绕监控",mf:"康陶",slot:"",size:"S/M/L",part:"车顶",ds:"常见的民用车辆周身投影监控装置，通常是为了辅助康陶的浮空车AI进行自动驾驶使用。",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"梅塔3型车用封闭监视器",mf:"梅塔集团",slot:"",size:"S/M/L",part:"车顶",ds:"",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"SS-301监视器",mf:"IEC",slot:"",size:"S/M/L",part:"车顶",ds:"",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"FAV-80全视系统",mf:"世嘉达利",slot:"",size:"M/L",part:"车顶",ds:"",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"ZETA-β空战监视器",mf:"泽塔科技",slot:"",size:"M/L",part:"车顶",ds:"",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"K9智能周视系统",mf:"莱茵金属",slot:"",size:"M/L",part:"车顶",ds:"",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"鸮式集成观测装置",mf:"苏石化",slot:"",size:"M/L",part:"车顶",ds:"",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"LJ-44智能侦察装置",mf:"CCMMC",slot:"",size:"L",part:"车顶",ds:"",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"八目式载具虚拟周视镜",mf:"世嘉达利",slot:"",size:"M/L",part:"车顶",ds:"",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"MK930坦克集成观瞄系统",mf:"军用科技",slot:"",size:"M/L",part:"车顶",ds:"",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"车载热成像",mf:"/",slot:"",size:"M/L",part:"观瞄",ds:"",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"车载夜视仪",mf:"/",slot:"",size:"M/L",part:"观瞄",ds:"",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"智能索敌系统",mf:"/",slot:"",size:"M/L",part:"观瞄",ds:"",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"多目标瞄准系统",mf:"/",slot:"",size:"M/L",part:"观瞄",ds:"",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"望远镜",mf:"/",slot:"",size:"M/L",part:"观瞄",ds:"",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"无人机指挥平台",mf:"/",slot:"",size:"M/L",part:"观瞄",ds:"一个专业的车载无人机天线和指挥目镜，让你可以",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"驾驶/炮手二合一式链接",mf:"/",slot:"",size:"M/L",part:"观瞄",ds:"需要棺式驾驶舱/智能驾驶舱，让你可以在驾驶车辆的同时操作车上的武器，当你如此做时，该系统会如同植入义体一样消耗你20人性，并有可能导致你的赛博精神发作。若你车上链接的武器超过3件，则消耗的人性加倍。",pr:"",tier:"",ra:"",grp:"进攻系统"},{n:"轻型载具装甲",mf:"",slot:"1",size:"S/M/L",part:"装甲",ds:"使载具+2sp，最高18。若原本sp小于10，则提升至10sp.为关键部位加装了碳纤维防护板，最大程度加强车体的同时，保持了原车的轻便性能。只能安装一种装甲改造。",pr:"",tier:"",ra:"",grp:"防御系统"},{n:"中型载具装甲",mf:"",slot:"2",size:"M/L",part:"装甲",ds:"使载具+4sp，最高24。若原本sp小于18，则提升至18sp.但需要减少十分之一的时速，并-1战斗速度。用轻型装甲钢包裹全车，只能安装一种装甲改造。",pr:"",tier:"",ra:"",grp:"防御系统"},{n:"重型载具装甲",mf:"",slot:"3",size:"L",part:"装甲",ds:"使载具+6sp，最高30。若原本sp小于22，则提升至22sp.但需要减少五分之一的时速，并-2战斗速度。用重型装甲钢包裹全车，只能安装一种装甲改造。",pr:"",tier:"",ra:"",grp:"防御系统"},{n:"格栅装甲",mf:"",slot:"1",size:"S/M/L",part:"装甲",ds:"外装格栅，可以使火箭弹或者导弹的直射伤害减半。生效两次后本系统报废。",pr:"",tier:"",ra:"",grp:"防御系统"},{n:"防弹车窗",mf:"",slot:"1",size:"S/M/L",part:"车舱",ds:"使用加厚的钢化防弹玻璃使车窗变成一面提供了7减伤（不可减免全威力及以上等级火力）的掩体，任何低于全威力穿甲等级的来袭火力都必须在-7之后才能对车内的人进行造伤。面对全自动火力时，减伤也需要乘以全自动的乘数。在被击穿三次后报废。不与棺式驾驶舱兼容",pr:"",tier:"",ra:"",grp:"防御系统"},{n:"重型防弹车窗",mf:"",slot:"1",size:"S/M/L",part:"车舱",ds:"加装了加强筋的钢化防弹玻璃使车窗变成一面提供了14减伤（不可减免轻反器材及以上等级火力）的掩体，任何低于轻反器材穿甲等级的来袭火力都必须在-14之后才能对车内的人进行造伤。面对全自动火力时，减伤也需要乘以全自动的乘数。在被击穿五次后报废。不与棺式驾驶舱兼容",pr:"",tier:"",ra:"",grp:"防御系统"},{n:"全封闭式车厢",mf:"",slot:"",size:"M/L",part:"特殊",ds:"需要棺式驾驶舱，将驾驶舱整个封闭，提供三防的同时，用更坚固的装甲钢来抵御轻火力的袭击。在棺式驾驶舱的基础上，SP+4，SDP+10。只能为棺式驾驶舱选择一种装甲升级。",pr:"",tier:"",ra:"",grp:"防御系统"},{n:"军用全封闭车厢",mf:"",slot:"",size:"M/L",part:"特殊",ds:"需要棺式驾驶舱，将驾驶舱整个封闭，在正面使用了坦克级别的倾斜复合装甲，确保驾驶员安然无恙。在棺式驾驶舱的基础上，SP+8，SDP+15。只能为棺式驾驶舱选择一种装甲升级。",pr:"",tier:"",ra:"",grp:"防御系统"},{n:"反应装甲",mf:"",slot:"",size:"M/L",part:"特殊",ds:"增加1点部位SP，若一次破甲后的伤害大于20，则免疫这一次伤害，并让本系统报废。可重复加装，但额外加装的反应装甲不会叠加SP",pr:"",tier:"",ra:"",grp:"防御系统"},{n:"电子战诱导系统",mf:"",slot:"",size:"M/L",part:"特殊",ds:"",pr:"",tier:"",ra:"",grp:"防御系统"},{n:"APS系统",mf:"",slot:"",size:"M/L",part:"特殊",ds:"",pr:"",tier:"",ra:"",grp:"防御系统"},{n:"不朽 APS",mf:"",slot:"",size:"",part:"",ds:"",pr:"",tier:"",ra:"",grp:"防御系统"},{n:"投石索 APS",mf:"",slot:"",size:"",part:"",ds:"",pr:"",tier:"",ra:"",grp:"防御系统"},{n:"指虎 APS",mf:"",slot:"",size:"",part:"",ds:"",pr:"",tier:"",ra:"",grp:"防御系统"},{n:"宪法军工.50重机枪",mf:"",slot:"",size:"",part:"",ds:"",pr:"",tier:"",ra:"",grp:"武器系统"},{n:"斯通博文 KPV-pa重机枪",mf:"",slot:"",size:"",part:"",ds:"",pr:"",tier:"",ra:"",grp:"武器系统"},{n:"军科 碎人者六管加特林",mf:"",slot:"",size:"",part:"",ds:"",pr:"",tier:"",ra:"",grp:"武器系统"},{n:"BCL-20 车用机炮",mf:"",slot:"",size:"",part:"",ds:"",pr:"",tier:"",ra:"",grp:"武器系统"},{n:"EMG-25 重型磁轨炮",mf:"",slot:"",size:"",part:"",ds:"",pr:"",tier:"",ra:"",grp:"武器系统"}]};export{r as D};
